#!/bin/bash
# Generated by util/installer/build.sh; edit src/ and rebuild.
# Bootstrap inventory, planning, credential preparation and a resumable installation core.
# This file can be sourced for tests without inspecting or changing the machine.

gt_reset() {
  declare -gA FACT=() ACTION=() REASON=() PACKAGE=() CANDIDATE=() DISK_FREE=() DISK_NEED=()
  declare -ga NOTES=() JDKS=() DISKS=() CONSUMERS=() WEB=() CERTS=() NETWORK=()
  ROOT='' SCRATCH='' LOCK_FD='' LANG_CODE=en
  JAVA_REQUIRED=25 NODE_REQUIRED='^22.22.3 || ^24.15.0 || >=26.0.0' CLI_REQUIRED=22
  BLOCKS=0
  declare -gA ANSWER=() Q_TYPE=() Q_WHEN=() Q_CHOICES=() Q_EN=() Q_DE=() PLAN_PACKAGES=()
  declare -ga QUESTIONS=() PLAN=() PLAN_BLOCKERS=() PLAN_WARNINGS=()
  QUESTION_FD='' QUESTION_OUTPUT=2
  declare -gA SECRET=() SECRET_STATUS=() FILE_ANSWERS=()
  MODE='' ANSWERS_FILE='' TTY_STATE='' SECRET_INPUT=''
  declare -gA STATE=() PROPERTIES=() BUILD=()
  declare -gA RESULT=()
  declare -ga PRIVATE_DIRS=() PRIVATE_FILES=()
  CORE_CONFIRM=no CORE_HOME=/home/grafioschtrader
  CORE_REPO=/home/grafioschtrader/build/grafioschtrader
  CORE_REMOTE=https://github.com/grafioschtrader/grafioschtrader.git
  case "${LC_ALL:-${LC_MESSAGES:-${LANG:-en}}}" in de*) LANG_CODE=de ;; esac
}

gt_message() {
  local key=$1
  shift
  local en de
  case "$key" in
    title) en='Grafioschtrader installation check (read-only)'; de='Grafioschtrader Installationsprüfung (nur lesend)' ;;
    facts) en='Inventory'; de='Bestandsaufnahme' ;;
    actions) en='Compatibility recommendations (no changes made)'; de='Kompatibilitätsempfehlungen (keine Änderungen)' ;;
    notes) en='Notes'; de='Hinweise' ;;
    requirements) en='Source requirements unavailable; built-in floors are provisional'; de='Quellcode-Anforderungen unbekannt; eingebaute Mindestversionen sind vorläufig' ;;
    unavailable) en='Probe unavailable or failed: %s'; de='Prüfung nicht verfügbar oder fehlgeschlagen: %s' ;;
    stale) en='APT metadata is absent or older than 24 hours; package candidates may be stale'; de='APT-Metadaten fehlen oder sind älter als 24 Stunden; Paketkandidaten können veraltet sein' ;;
    existing) en='Existing installation: use %s; bootstrap must leave it untouched'; de='Bestehende Installation: %s verwenden; Erstinstallation darf sie nicht ändern' ;;
    partial) en='Foreign installation pieces must not be adopted or removed'; de='Fremde Installationsteile dürfen weder übernommen noch entfernt werden' ;;
    running) en='Unfinished installer state; resume with --install-core, --install-app, --install-web or --check-mail'; de='Unfertiger Installationszustand; mit --install-core, --install-app, --install-web oder --check-mail fortsetzen' ;;
    memory) en='Low RAM: %s'; de='Wenig RAM: %s' ;;
    legacy) en='Legacy platform: %s'; de='Ältere Plattform: %s' ;;
    footer) en='Check finished: %s blocking recommendations. Full application installation is not implemented yet.'; de='Prüfung beendet: %s blockierende Empfehlungen. Die vollständige Anwendungsinstallation ist noch nicht implementiert.' ;;
    root) en='Run inventory modes as root for a complete inventory.'; de='Bestandsaufnahme für einen vollständigen Bericht als root ausführen.' ;;
    mode) en='Use --check, --dry-run, --prepare, --install-core, --install-app, --install-web or --check-mail; see --help.'; de='--check, --dry-run, --prepare, --install-core, --install-app, --install-web oder --check-mail verwenden; siehe --help.' ;;
    pipe) en='Download the script to a file before running it; piped execution is refused.'; de='Skript vor dem Ausführen als Datei speichern; Ausführung über eine Pipe wird abgelehnt.' ;;
    lock) en='An installer is running or its existing lock cannot be read.'; de='Ein Installer läuft oder seine vorhandene Sperre kann nicht gelesen werden.' ;;
    *) en=$key; de=$key ;;
  esac
  # The format strings above are installer-owned translations, never probe output.
  # shellcheck disable=SC2059
  if [[ "$LANG_CODE" == de ]]; then printf "$de\n" "$@"; else printf "$en\n" "$@"; fi
}

gt_note() {
  local severity=$1 message
  shift
  message=$(gt_message "$@")
  NOTES+=("$severity: $message")
}

# Values from configurations and subprocesses never become shell code or terminal control sequences.
gt_safe() { printf '%s' "$1" | LC_ALL=C tr -d '\000-\010\013-\037\177'; }
gt_path() { printf '%s%s' "$ROOT" "$1"; }
gt_probe() {
  command -v "$1" >/dev/null 2>&1 || return 127
  timeout --signal=TERM --kill-after=2 12 "$@" 2>/dev/null
}
gt_capture() {
  local key=$1 value
  shift
  if value=$(gt_probe "$@"); then FACT[$key]=$value; else
    FACT[$key]=unknown
    gt_note UNKNOWN unavailable "$key"
  fi
}
gt_literal() {
  # Read a single literal key=value. Reject duplicate keys, substitutions and shell operators.
  local file=$1 key=$2 value
  [[ -r "$file" ]] || return 1
  value=$(awk -v key="$key" 'index($0,key "=")==1 {n++; v=substr($0,length(key)+2)} END {if(n==1) print v; else exit 1}' "$file") || return 1
  value=${value%$'\r'}
  if [[ "$value" == \"*\" || "$value" == \'*\' ]]; then value=${value:1:${#value}-2}; fi
  [[ "$value" != *[\$\`\;\\]* ]] || return 1
  printf '%s' "$value"
}

gt_version_at_least() {
  local actual=$1 required=$2 i
  local -a a b
  [[ "$actual" =~ ^[0-9]+(\.[0-9]+){0,3}$ && "$required" =~ ^[0-9]+(\.[0-9]+){0,3}$ ]] || return 1
  IFS=. read -r -a a <<< "$actual"
  IFS=. read -r -a b <<< "$required"
  for i in 0 1 2 3; do
    (( 10#${a[i]:-0} > 10#${b[i]:-0} )) && return 0
    (( 10#${a[i]:-0} < 10#${b[i]:-0} )) && return 1
  done
  return 0
}
gt_node_range_valid() {
  [[ "$1" =~ ^(\^|\>=)[0-9]+\.[0-9]+\.[0-9]+(\ \|\|\ (\^|\>=)[0-9]+\.[0-9]+\.[0-9]+)*$ ]]
}
gt_node_satisfies() {
  local version=${1#v} range=$2 clause required upper major minor patch
  [[ "$version" =~ ^[0-9]+\.[0-9]+\.[0-9]+$ ]] || return 1
  gt_node_range_valid "$range" || return 1
  while IFS= read -r clause; do
    required=${clause#^}; required=${required#>=}
    gt_version_at_least "$version" "$required" || continue
    [[ "$clause" == '>='* ]] && return 0
    IFS=. read -r major minor patch <<< "$required"
    if (( major > 0 )); then upper="$((major+1)).0.0"
    elif (( minor > 0 )); then upper="0.$((minor+1)).0"
    else upper="0.0.$((patch+1))"; fi
    gt_version_at_least "$version" "$upper" || return 0
  done < <(printf '%s\n' "$range" | sed 's/ || /\n/g')
  return 1
}
gt_parse_requirements() {
  local java node cli
  java=$(gt_literal "$1" java_required) && node=$(gt_literal "$1" node_required) &&
    cli=$(gt_literal "$1" angular_cli_required) || return 1
  [[ "$java" =~ ^[1-9][0-9]*$ && "$cli" =~ ^[1-9][0-9]*$ ]] && gt_node_range_valid "$node" || return 1
  JAVA_REQUIRED=$java NODE_REQUIRED=$node CLI_REQUIRED=$cli
}
gt_source_revision() {
  local remote commit base
  FACT[source.requirements]=fallback FACT[source.commit]=unknown FACT[source.collation]=unknown
  if [[ "${STATE[planned_commit]:-}" =~ ^[a-f0-9]{40}$ ]]; then remote="${STATE[planned_commit]} refs/heads/master"
  else remote=$(gt_probe git -c credential.helper= -c core.askPass= ls-remote \
      https://github.com/grafioschtrader/grafioschtrader.git refs/heads/master) || remote=''; fi
  if [[ -n "$remote" ]]; then
    read -r commit _ <<< "$remote"
    if [[ "$commit" =~ ^[a-f0-9]{40}$ ]]; then
      FACT[source.commit]=$commit
      base="https://raw.githubusercontent.com/grafioschtrader/grafioschtrader/$commit"
      if gt_probe curl --disable -fsS --connect-timeout 4 --max-time 10 \
          "$base/util/shellscripts/checkversion.sh" > "$SCRATCH/checkversion.sh" &&
        gt_probe curl --disable -fsS --connect-timeout 4 --max-time 10 \
          "$base/backend/grafioschtrader-server/src/main/resources/application.properties" > "$SCRATCH/application.properties" &&
        gt_parse_requirements "$SCRATCH/checkversion.sh"; then
        FACT[source.requirements]=remote
        FACT[source.collation]=no
        if grep -E '^spring\.datasource\.hikari\.connection-init-sql[[:space:]]*=' "$SCRATCH/application.properties" |
            grep -q "time_zone.*character_set_collations.*utf8mb3=utf8mb3_general_ci,utf8mb4=utf8mb4_general_ci"; then
          FACT[source.collation]=yes
        fi
      fi
    fi
  fi
  [[ "${FACT[source.requirements]}" == remote ]] || gt_note UNKNOWN requirements
  FACT[required.java]=$JAVA_REQUIRED FACT[required.node]=$NODE_REQUIRED FACT[required.angular_cli]=$CLI_REQUIRED
}
gt_system() {
  local field value os mem pidone lists newest now
  os=$(gt_path /etc/os-release)
  for field in ID ID_LIKE VERSION_ID VERSION_CODENAME; do
    value=$(gt_literal "$os" "$field") || value=unknown
    FACT[os.$field]=$value
  done
  gt_capture architecture dpkg --print-architecture
  mem=$(gt_path /proc/meminfo)
  for field in MemTotal MemAvailable SwapTotal; do
    value=$(awk -v key="$field:" '$1==key && $2~/^[0-9]+$/ {print int($2/1024)}' "$mem" 2>/dev/null)
    FACT[memory.$field]=${value:-unknown}
  done
  pidone=$(cat "$(gt_path /proc/1/comm)" 2>/dev/null) || pidone=unknown
  FACT[init]=$pidone
  gt_capture timezone timedatectl show --property=Timezone --value
  # fuser returns 1 for a free lock, 127 when unavailable.
  if value=$(gt_probe fuser "$(gt_path /var/lib/dpkg/lock-frontend)"); then FACT[dpkg.lock]=$value
  elif [[ $? == 1 ]]; then FACT[dpkg.lock]=free
  else FACT[dpkg.lock]=unknown; gt_note UNKNOWN unavailable dpkg.lock; fi
  lists=$(gt_path /var/lib/apt/lists)
  newest=$(find "$lists" -maxdepth 1 -type f \( -name '*Packages*' -o -name '*InRelease' -o -name '*Release' \) \
    -printf '%T@\n' 2>/dev/null | sort -nr | head -n 1)
  newest=${newest%%.*}; now=$(date +%s)
  FACT[apt.age_hours]=unknown
  if [[ "$newest" =~ ^[0-9]+$ ]]; then FACT[apt.age_hours]=$(((now-newest)/3600)); fi
  if [[ "${FACT[apt.age_hours]}" == unknown ]] || (( ${FACT[apt.age_hours]} > 24 )); then gt_note WARN stale; fi
  gt_capture listeners ss -Htlnp
  gt_capture firewall.ufw ufw status verbose
  if value=$(gt_probe nft list ruleset); then
    FACT[firewall.nftables]=$([[ -n "$value" ]] && echo present || echo empty)
  else FACT[firewall.nftables]=unknown; fi
  if value=$(gt_probe iptables-save); then
    FACT[firewall.iptables]=$([[ "$value" == *'-A '* ]] && echo present || echo empty)
  else FACT[firewall.iptables]=unknown; fi
}

gt_packages() {
  local name version state value
  PACKAGE=() CANDIDATE=()
  # shellcheck disable=SC2016
  if value=$(gt_probe dpkg-query -W '-f=${binary:Package}\t${Version}\t${db:Status-Abbrev}\n'); then
    while IFS=$'\t' read -r name version state; do
      [[ "$state" == ii* ]] && PACKAGE[${name%%:*}]=$version
    done <<< "$value"
    FACT[packages]=known
  else FACT[packages]=unknown; gt_note UNKNOWN unavailable packages; fi
  for name in "openjdk-$JAVA_REQUIRED-jdk-headless" maven nodejs mariadb-server nginx apache2; do
    # Do not let apt-cache create its binary caches during a read-only run.
    value=$(gt_probe apt-cache -o Dir::Cache::pkgcache= -o Dir::Cache::srcpkgcache= policy "$name") || value=
    version=$(awk '/Candidate:/ {print $2; exit}' <<< "$value")
    CANDIDATE[$name]=${version:-unknown}
    FACT[apt.candidate.$name]=${version:-unknown}
  done
}

gt_service() {
  local unit=$1 value
  value=$(gt_probe systemctl show "$unit" --property=LoadState --property=ActiveState --property=SubState --property=UnitFileState) || value=unknown
  printf '%s' "$value"
}
gt_installed_unit() { [[ "$(gt_service "$1")" == *'LoadState=loaded'* ]]; }
gt_installation() {
  local state_file status key unit=no user=no vars=no updater=no jar=no sudoers=no file images
  state_file=$(gt_path /var/lib/gt-install/state)
  FACT[host.class]=fresh
  FACT[containers]=absent
  if command -v docker >/dev/null; then
    # -a also detects stopped installations. Never inspect container environment variables.
    if images=$(gt_probe docker ps -a --format '{{.Image}}'); then FACT[containers]=$images
    else FACT[containers]=unknown; gt_note UNKNOWN unavailable 'Docker container inventory'; fi
  fi
  gt_installed_unit grafioschtrader.service && unit=yes
  [[ -f "$(gt_path /etc/systemd/system/grafioschtrader.service)" ]] && unit=yes
  gt_probe getent passwd grafioschtrader >/dev/null && user=yes
  [[ -f "$(gt_path /home/grafioschtrader/gtvar.sh)" ]] && vars=yes
  [[ -f "$(gt_path /home/grafioschtrader/gtupdate.sh)" ]] && updater=yes
  [[ -f "$(gt_path /etc/sudoers.d/grafioschtrader)" ]] && sudoers=yes
  for file in "$(gt_path /home/grafioschtrader)"/grafioschtrader-server-*.jar; do [[ -f "$file" ]] && jar=yes; done
  FACT[host.pieces]="user=$user unit=$unit gtvar=$vars gtupdate=$updater jar=$jar sudoers=$sudoers"
  if [[ -e "$state_file" ]]; then
    status=$(gt_literal "$state_file" status) || status=unknown
    FACT[state.status]=$status
    for key in schema installer_sha256 planned_commit built_commit completed_at; do
      FACT[state.$key]=$(gt_literal "$state_file" "$key") || FACT[state.$key]=unknown
    done
    # Only completion markers are shown, never arbitrary state values or the secrets file.
    FACT[state.completed_steps]=$(awk -F= '$1~/^step[._][a-zA-Z0-9_.-]+$/ && $2~/^(complete|completed|ok|1)$/ {print $1}' "$state_file" 2>/dev/null)
    case "$status" in
      complete)
        gt_question_model
        if gt_state_load; then FACT[host.class]=completed; else FACT[host.class]='invalid-state'; fi ;;
      running) FACT[host.class]=unfinished ;;
      *) FACT[host.class]='invalid-state' ;;
    esac
  elif [[ "$unit$vars$updater" == yesyesyes ]]; then FACT[host.class]=classic
  elif [[ "$user$unit$vars$updater$jar$sudoers" == *yes* ]]; then FACT[host.class]=foreign-partial
  elif [[ "${FACT[containers]}" == *ghcr.io/grafioschtrader/grafioschtrader-* ]]; then FACT[host.class]=docker
  elif [[ "${FACT[containers]}" == unknown ]]; then FACT[host.class]=unknown
  fi
}

gt_java() {
  local dir executable version vendor javac value selected
  local -A seen=()
  # update-alternatives queries do not change the selection or its auto/manual mode.
  FACT[java.alternatives]=$(gt_probe update-alternatives --query java) || FACT[java.alternatives]=unknown
  FACT[javac.alternatives]=$(gt_probe update-alternatives --query javac) || FACT[javac.alternatives]=unknown
  selected=$(command -v java) || selected=
  FACT[java.path]=${selected:-absent} FACT[java.suitable]=absent FACT[java.version]=absent
  JDKS=()
  local -a homes=()
  for dir in "${STATE[java_home]:-}" "${JAVA_HOME:-}"; do
    [[ -d "$dir" ]] && homes+=("$dir")
  done
  for dir in "$(gt_path /usr/lib/jvm)"/* "$(gt_path /usr/local)"/jdk-* "$(gt_path /opt)"/*; do
    [[ -d "$dir" ]] && homes+=("$dir")
  done
  value=$(gt_probe update-alternatives --list java) || value=
  while IFS= read -r executable; do
    [[ -n "$executable" ]] && homes+=("$(dirname "$(dirname "$executable")")")
  done <<< "$value"
  if [[ -n "$selected" ]]; then
    executable=$(readlink -f "$selected")
    homes+=("$(dirname "$(dirname "$executable")")")
  fi
  for dir in "${homes[@]}"; do
    dir=$(readlink -f "$dir") || continue
    [[ -z "${seen[$dir]:-}" && -r "$dir/release" ]] || continue
    seen[$dir]=1
    version=$(gt_literal "$dir/release" JAVA_VERSION) || version=unknown
    vendor=$(gt_literal "$dir/release" IMPLEMENTOR) || vendor=unknown
    javac=no; [[ -x "$dir/bin/java" && -x "$dir/bin/javac" ]] && javac=yes
    JDKS+=("$dir version=$version vendor=$vendor javac=$javac")
    if [[ "$version" =~ ^([0-9]+)(\.|$) && "$javac" == yes ]] && (( BASH_REMATCH[1] >= JAVA_REQUIRED )); then
      if [[ "${FACT[java.suitable]}" == absent || ( "${FACT[java.version]%%.*}" != "$JAVA_REQUIRED" && "${version%%.*}" == "$JAVA_REQUIRED" ) ]]; then
        FACT[java.suitable]=$dir FACT[java.version]=$version
      fi
    fi
  done
  return 0
}
gt_maven_probe() {
  local executable=$1 home=$2
  local -a environment=(-u JAVA_HOME -u _JAVA_OPTIONS MAVEN_SKIP_RC=1 MAVEN_OPTS="-Djava.io.tmpdir=$SCRATCH -Dstyle.color=never"
    MAVEN_ARGS= JAVA_TOOL_OPTIONS= JDK_JAVA_OPTIONS=)
  [[ "$home" == absent || "$home" == pending ]] || environment+=("JAVA_HOME=$home" "PATH=$home/bin:$PATH")
  (cd "$SCRATCH" && gt_probe env "${environment[@]}" "$executable" -v)
}

gt_maven_version() {
  sed -E $'s/\033\\[[0-9;]*[mK]//g' <<< "$1" | sed -nE 's/^Apache Maven ([0-9]+\.[0-9]+\.[0-9]+).*/\1/p' | head -n 1
}

gt_runtimes() {
  local executable value version dir
  FACT[maven.version]=absent FACT[maven.path]=absent
  local -a commands=()
  [[ ! -x "${STATE[maven]:-}" ]] || commands+=("${STATE[maven]}")
  executable=$(command -v mvn) && commands+=("$executable")
  for dir in "$(gt_path /opt)"/maven "$(gt_path /opt)"/apache-maven-*; do
    [[ -x "$dir/bin/mvn" ]] && commands+=("$dir/bin/mvn")
  done
  for executable in "${commands[@]}"; do
    # Version checks must not source mavenrc files or project-local JVM options.
    if value=$(gt_maven_probe "$executable" "${FACT[java.suitable]}"); then
      version=$(gt_maven_version "$value")
      if [[ -n "$version" ]]; then
        FACT[maven.version]=$version FACT[maven.path]=$executable
        gt_version_at_least "$version" 3.8 && break
      fi
    else FACT[maven.version]=unknown; fi
  done
  executable=$(command -v node) || executable=absent
  FACT[node.path]=$executable FACT[node.version]=absent FACT[node.origin]=absent
  if [[ "$executable" != absent ]]; then
    value=$(gt_probe env NODE_OPTIONS= node --version) || value=unknown
    FACT[node.version]=${value#v}
    case "$executable" in
      */.nvm/*) FACT[node.origin]=nvm ;;
      /usr/local/*) FACT[node.origin]=local-tarball ;;
      /opt/*) FACT[node.origin]=isolated-tarball ;;
      *)
        FACT[node.origin]=unknown
        if [[ -n "${PACKAGE[nodejs]:-}" ]]; then
          FACT[node.origin]=distribution
          [[ "${PACKAGE[nodejs]}" == *nodesource* ]] && FACT[node.origin]=nodesource
        fi ;;
    esac
  fi
  FACT[npm.packages]=unknown FACT[angular.version]=unknown FACT[semver.version]=unknown
  # npm ls is read-only except its cache/logs, which must remain inside our disposable directory.
  if value=$(gt_probe env NODE_OPTIONS= npm_config_cache="$SCRATCH/npm" npm_config_update_notifier=false \
      npm_config_logs_max=0 npm ls --global --depth=0 --parseable); then
    FACT[npm.packages]=$value
    while IFS= read -r dir; do
      case "$dir" in
        */@angular/cli|*/semver)
          version=$(sed -nE 's/^[[:space:]]*"version"[[:space:]]*:[[:space:]]*"([0-9]+\.[0-9]+\.[0-9]+)".*/\1/p' "$dir/package.json" 2>/dev/null | head -n 1)
          [[ "$dir" == */semver ]] && FACT[semver.version]=${version:-unknown} || FACT[angular.version]=${version:-unknown}
          ;;
      esac
    done <<< "$value"
  fi
}

gt_consumers() {
  local kind value file executable command_line
  for kind in node java; do
    FACT[$kind.consumers]=no
    # Avoid printing process arguments, which frequently contain passwords and API tokens.
    if value=$(gt_probe pgrep -x "$kind"); then
      while IFS= read -r value; do
        [[ "$value" =~ ^[0-9]+$ ]] || continue
        if [[ "$kind" == java ]]; then
          command_line=$(tr '\0' ' ' < "$(gt_path "/proc/$value/cmdline")" 2>/dev/null) || command_line=''
          [[ "$command_line" != *grafioschtrader-server-*.jar* ]] || continue
        fi
        CONSUMERS+=("$kind pid=$value")
        FACT[$kind.consumers]=yes
      done <<< "$value"
    elif [[ $? != 1 ]]; then FACT[$kind.consumers]=unknown; fi
  done
  value=$(gt_probe apt-cache -o Dir::Cache::pkgcache= -o Dir::Cache::srcpkgcache= rdepends --installed nodejs) || value=unknown
  FACT[node.reverse_dependencies]=$value
  if [[ "$value" == unknown ]]; then FACT[node.consumers]=unknown
  elif [[ -n "$(sed '1,2d;/^[[:space:]]*$/d' <<< "$value")" ]]; then FACT[node.consumers]=yes; fi
  while IFS= read -r -d '' file; do
    [[ "$file" != */grafioschtrader.service ]] || continue
    while IFS= read -r command_line; do
      executable=${command_line%% *}
      # Inspect wrappers too, but keep arguments and Environment values out of the report.
      command_line=${command_line//\"/ }
      command_line=${command_line//\'/ }
      if [[ "$command_line" =~ (^|[/[:space:]])(node|nodejs|npm)([[:space:]]|$) ]]; then
        CONSUMERS+=("node unit=$file executable=$executable"); FACT[node.consumers]=yes
      fi
      if [[ "$command_line" =~ (^|[/[:space:]])java([[:space:]]|$) ]]; then
        CONSUMERS+=("java unit=$file executable=$executable"); FACT[java.consumers]=yes
      fi
    done < <(sed -nE 's/^[[:space:]]*ExecStart[[:space:]]*=[-+!:@]*(.*)/\1/p' "$file" 2>/dev/null)
  done < <(find "$(gt_path /etc/systemd/system)" "$(gt_path /lib/systemd/system)" "$(gt_path /usr/lib/systemd/system)" \
    -type f \( -name '*.service' -o -name '*.conf' \) -print0 2>/dev/null)
}

gt_database() {
  local client value package version collation
  local -a options=(--no-defaults --protocol=SOCKET --user=root --batch --skip-column-names --connect-timeout=4)
  [[ -z "${1:-}" ]] || options[0]="--defaults-file=$1"
  FACT[database.vendor]=absent FACT[database.version]=absent FACT[database.query]=unknown
  FACT[database.schemas]=unknown FACT[database.users]=unknown FACT[database.gt_tables]=unknown FACT[database.gt_user]=unknown
  FACT[database.datadir]=/var/lib/mysql FACT[database.root_socket]=unknown FACT[database.active]=no
  FACT[database.service]=$(gt_service mariadb.service)
  FACT[database.socket]=$(gt_service mariadb.socket)
  for package in mariadb-server mysql-server mysql-community-server; do
    if [[ -n "${PACKAGE[$package]:-}" ]]; then
      FACT[database.vendor]=${package%%-server*}
      version=${PACKAGE[$package]#*:}; FACT[database.version]=${version%%-*}
    fi
  done
  [[ "${FACT[packages]}" == unknown ]] && FACT[database.vendor]=unknown
  FACT[database.buffer_pool_config]=$(grep -rlE '^[[:space:]]*innodb[-_]buffer[-_]pool[-_]size[[:space:]]*=' \
    "$(gt_path /etc/mysql)" 2>/dev/null || true)
  # Connecting to an inactive socket-activated server would START it, violating --check.
  if [[ "${FACT[database.service]}" != *'ActiveState=active'* ]] && ! gt_probe pgrep -x mariadbd >/dev/null &&
      ! gt_probe pgrep -x mysqld >/dev/null; then
    gt_note UNKNOWN unavailable 'database SQL (server inactive; socket activation deliberately avoided)'
    return 0
  fi
  FACT[database.active]=yes
  [[ "${FACT[database.vendor]}" != absent ]] || FACT[database.vendor]=unknown
  client=$(command -v mariadb || command -v mysql) || { gt_note UNKNOWN unavailable 'database client'; return 0; }
  # Preparation may supply a private options file; inventory uses no option files.
  if ! value=$(gt_probe "$client" "${options[@]}" -e "SELECT VERSION(), @@datadir, @@collation_server;"); then
    gt_note UNKNOWN unavailable 'database SQL (root socket login)'
    return 0
  fi
  FACT[database.query]=ok
  IFS=$'\t' read -r version value collation <<< "$value"
  FACT[database.version]=${version%%-*} FACT[database.datadir]=$value FACT[database.collation]=$collation
  [[ "$version" == *MariaDB* ]] && FACT[database.vendor]=mariadb || FACT[database.vendor]=mysql
  local sql='SELECT s.SCHEMA_NAME, COUNT(t.TABLE_NAME), COALESCE(SUM(t.TABLE_NAME="flyway_schema_history"),0) FROM information_schema.SCHEMATA s LEFT JOIN information_schema.TABLES t ON t.TABLE_SCHEMA=s.SCHEMA_NAME GROUP BY s.SCHEMA_NAME;'
  if value=$(gt_probe "$client" "${options[@]}" -e "$sql"); then
    FACT[database.schemas]=$value
    FACT[database.gt_tables]=$(awk -F '\t' '$1=="grafioschtrader" {print $2; found=1} END {if(!found) print "absent"}' <<< "$value")
  fi
  if value=$(gt_probe "$client" "${options[@]}" \
      -e 'SELECT User,Host,plugin FROM mysql.user;'); then
    FACT[database.users]=$value FACT[database.gt_user]=absent
    [[ "$(awk -F '\t' '$1=="grafioschtrader" && $2=="localhost" {print "yes"}' <<< "$value")" == yes ]] && FACT[database.gt_user]=present
  fi
  if value=$(gt_probe "$client" "${options[@]}" \
      -e "SELECT COUNT(*) FROM mysql.global_priv WHERE User='root' AND Host='localhost' AND priv LIKE '%unix_socket%';"); then
    FACT[database.root_socket]=$value
  fi
  if value=$(gt_probe "$client" "${options[@]}" \
      -e "SHOW SESSION VARIABLES LIKE 'character_set_collations';"); then FACT[database.character_set_collations]=${value:-unavailable-before-11.2}; fi
  if awk '$4 ~ /:3306$/ && $4 !~ /^(127\.|\[?::1\]?:)/ {found=1} END {exit !found}' <<< "${FACT[listeners]:-unknown}"; then
    gt_note WARN unavailable 'MariaDB listens beyond loopback; leave shared server networking unchanged'
  fi
}

gt_disk() {
  local requested=$1 need=$2 actual device available filesystem value
  actual=$(gt_path "$requested")
  while [[ ! -d "$actual" && "$actual" != / ]]; do actual=$(dirname "$actual"); done
  device=$(stat -Lc %d "$actual" 2>/dev/null) || device=unknown
  value=$(df -Pk "$actual" 2>/dev/null) || value=
  available=$(awk 'NR==2 {print int($4/1024)}' <<< "$value")
  filesystem=$(stat -Lf -c %T "$actual" 2>/dev/null) || filesystem=unknown
  DISKS+=("$requested device=$device free_MiB=${available:-unknown} filesystem=$filesystem required_MiB=$need")
  if [[ "$device" =~ ^[0-9]+$ && "$available" =~ ^[0-9]+$ ]]; then
    DISK_FREE[$device]=$available DISK_NEED[$device]=$((${DISK_NEED[$device]:-0}+need))
  else FACT[disk.unknown]=yes; gt_note UNKNOWN unavailable "disk $requested"; fi
}

gt_network() {
  local value interface host url status file
  gt_capture network.ipv4_route ip -4 route get 1.1.1.1
  FACT[network.lan_ipv4]=$(awk '{for(i=1;i<NF;i++) if($i=="src") print $(i+1)}' <<< "${FACT[network.ipv4_route]}")
  gt_capture network.ipv6_route ip -6 route show default
  interface=$(awk '{for(i=1;i<NF;i++) if($i=="dev") {print $(i+1); exit}}' <<< "${FACT[network.ipv6_route]}")
  FACT[network.global_ipv6]=unknown
  if [[ "$interface" =~ ^[a-zA-Z0-9_.:-]+$ ]]; then
    value=$(gt_probe ip -6 addr show dev "$interface" scope global -temporary -deprecated) || value=
    FACT[network.global_ipv6]=$(awk '$1=="inet6" && $2!~/^(f[cd]|fe[89ab])/ {sub(/\/.*/,"",$2); print $2}' <<< "$value")
  fi
  value=$(gt_probe curl --disable -4 -fsS --connect-timeout 4 --max-time 8 https://ifconfig.co/ip) || value=unknown
  [[ "$value" =~ ^([0-9]{1,3}\.){3}[0-9]{1,3}$ ]] || value=unknown
  FACT[network.public_ipv4]=$value
  local -A hosts=([github.com]=1 [raw.githubusercontent.com]=1 [registry.npmjs.org]=1 [repo.maven.apache.org]=1
    [deb.nodesource.com]=1 [nodejs.org]=1 [packages.adoptium.net]=1 [download.bell-sw.com]=1 [dlcdn.apache.org]=1)
  while IFS= read -r -d '' file; do
    while IFS= read -r url; do
      host=${url#*://}; host=${host%%/*}; host=${host##*@}
      [[ "$host" =~ ^[a-zA-Z0-9.-]+(:[0-9]+)?$ ]] && hosts[$host]=1
    done < <(awk '/^[[:space:]]*#/ {next} /^[[:space:]]*(URIs:|deb(-src)?[[:space:]])/ {
      for(i=1;i<=NF;i++) if($i~/^https?:\/\//) print $i
    }' "$file" 2>/dev/null)
  done < <(find "$(gt_path /etc/apt)" -maxdepth 2 -type f \( -name '*.list' -o -name '*.sources' \) -print0 2>/dev/null)
  for host in "${!hosts[@]}"; do
    if status=$(gt_probe curl --disable -sSI -o /dev/null --connect-timeout 3 --max-time 6 \
        -w '%{http_code}' "https://$host/"); then NETWORK+=("$host HTTP=$status"); else NETWORK+=("$host UNKNOWN"); fi
  done
  url=https://github.com/grafioschtrader/grafioschtrader/releases/download/Latest/latest.tar.gz
  if value=$(gt_probe curl --disable -fsSIL -o /dev/null --connect-timeout 3 --max-time 10 -w '%{url_effective}' "$url"); then
    # Redirects to release assets contain signed query parameters. Report only the host.
    host=${value#*://}; host=${host%%/*}; host=${host%%\?*}
    NETWORK+=("frontend-release host=$host reachable=yes")
  else NETWORK+=('frontend-release UNKNOWN'); fi
}

gt_web_directives() {
  # Tokenize nginx outside quotes/comments; Apache directives end at the physical newline.
  # This reads text only, including compact "server { listen 80; ... }" configurations.
  awk -v kind="$2" '
    function emit() {gsub(/^[ \t\r\n]+|[ \t\r\n]+$/, "", text); if(length(text)) print text; text=""}
    {
      for(i=1;i<=length($0);i++) {
        c=substr($0,i,1)
        if(escaped) {text=text c; escaped=0; continue}
        if(c=="\\") {text=text c; escaped=1; continue}
        if(quote!="") {text=text c; if(c==quote) quote=""; continue}
        if(c=="\042" || c=="\047") {quote=c; text=text c; continue}
        if(c=="#") break
        if(kind=="nginx" && (c==";" || c=="{" || c=="}")) {
          if(c=="{") text=text " {"
          emit()
          if(c=="}") print "}"
        } else text=text c
      }
      if(kind=="apache") emit(); else text=text " "
    }
    END {emit()}
  ' "$1"
}

gt_web_status() {
  local label=$1 names=$2 listeners=$3 entry name port scheme result
  [[ -n "$listeners" ]] || listeners=80:http
  [[ -n "$names" ]] || names=127.0.0.1
  for entry in $listeners; do
    port=${entry%:*}; scheme=${entry#*:}
    for name in $names; do
      if [[ ! "$name" =~ ^[a-zA-Z0-9][a-zA-Z0-9.-]*$ ]]; then
        gt_note UNKNOWN unavailable "non-literal vhost name: $label"
        continue
      fi
      if result=$(gt_probe curl --disable --noproxy '*' -sS -o /dev/null --connect-timeout 2 --max-time 4 \
          --resolve "$name:$port:127.0.0.1" -w '%{http_code}' "$scheme://$name:$port/"); then :
      else result=unknown; fi
      WEB+=("$label probe name=$name port=$port scheme=$scheme HTTP=$result")
    done
  done
}

gt_web() {
  local file line key value names port certificate result kind include label listeners
  local index=0 depth block_depth block in_block include_file
  local -A visited=() kinds=()
  FACT[web.apache2]=${PACKAGE[apache2]:-absent} FACT[web.nginx]=${PACKAGE[nginx]:-absent}
  FACT[web.certbot]=${PACKAGE[certbot]:-absent}
  FACT[web.certbot_plugins]="nginx=${PACKAGE[python3-certbot-nginx]:-absent} apache=${PACKAGE[python3-certbot-apache]:-absent}"
  FACT[web.certbot_timer]=$(gt_service certbot.timer)
  FACT[web.cloudflared]=$(gt_service cloudflared.service)
  FACT[web.apache_modules]=$(find "$(gt_path /etc/apache2/mods-enabled)" -maxdepth 1 -name '*.load' -printf '%f\n' 2>/dev/null || true)
  local -a files=()
  for file in "$(gt_path /etc/nginx/nginx.conf)" "$(gt_path /etc/nginx/sites-enabled)"/* "$(gt_path /etc/nginx/conf.d)"/*.conf \
      "$(gt_path /etc/apache2/apache2.conf)" "$(gt_path /etc/apache2/sites-enabled)"/*; do
    if [[ -f "$file" ]]; then
      files+=("$file")
      [[ "$file" == */apache2/* ]] && kinds[$file]=apache || kinds[$file]=nginx
    fi
  done
  while (( index < ${#files[@]} )); do
    file=${files[index]}; index=$((index+1)); kind=${kinds[$file]}
    result=$(readlink -f "$file") || continue
    [[ -z "${visited[$result]:-}" ]] || continue
    visited[$result]=1
    WEB+=("config=$file")
    names='' listeners='' depth=0 block_depth=0 block=0 in_block=0 label=$file
    # Read only selected directives. Never run nginx -T/apachectl: they can open logs on disk.
    while IFS= read -r line; do
      read -r key value <<< "$line"
      if [[ "$key" == server && "$value" == '{' || "$key" == '<VirtualHost' ]]; then
        block=$((block+1)); label="$file#$block"; in_block=1; names='' listeners=''; block_depth=$((depth+1))
        WEB+=("$label server_kind $kind")
        if [[ "$key" == '<VirtualHost' ]]; then
          for result in ${value%>}; do
            port=${result##*:}
            if [[ "$port" =~ ^[0-9]+$ ]]; then
              [[ "$port" == 443 ]] && listeners+=" $port:https" || listeners+=" $port:http"
            fi
          done
        fi
      fi
      if [[ "$line" == '}' && "$depth" == "$block_depth" && "$in_block" == 1 || "$key" == '</VirtualHost>' ]]; then
        gt_web_status "$label" "$names" "$listeners"
        in_block=0
      fi
      case "$key" in
        server_name|ServerName|ServerAlias) names+=" ${value//\"/}"; WEB+=("$label $key $value") ;;
        listen)
          WEB+=("$label listen $value")
          result=${value%% *}; port=${result##*:}
          if [[ "$port" =~ ^[0-9]+$ ]]; then
            [[ "$value" == *ssl* ]] && listeners+=" $port:https" || listeners+=" $port:http"
          else gt_note UNKNOWN unavailable "non-numeric web listen: $file"; fi ;;
        '<VirtualHost') WEB+=("$label $line") ;;
        SSLEngine) [[ "$value" != on ]] || listeners=${listeners//:http/:https} ;;
        root|DocumentRoot|location) WEB+=("$label $key $value") ;;
        ProxyPass|ProxyPassMatch) WEB+=("$label $key ${value%% *}") ;;
        ssl_certificate_key|SSLCertificateKeyFile) WEB+=("$label $key ${value//\"/}") ;;
        ssl_certificate|SSLCertificateFile)
          certificate=${value//\"/}; WEB+=("$label $key $certificate"); gt_certificate "$(gt_path "$certificate")" ;;
        include|Include|IncludeOptional)
          include=${value//\"/}
          if [[ "$include" == *'$'* || "$include" == *' '* ]]; then
            gt_note UNKNOWN unavailable "dynamic web include: $file"
          else
            if [[ "$include" != /* ]]; then
              [[ "$kind" == nginx ]] && include="/etc/nginx/$include" || include="/etc/apache2/$include"
            fi
            result=no
            while IFS= read -r include_file; do
              [[ -f "$include_file" ]] || continue
              files+=("$include_file"); kinds[$include_file]=$kind; result=yes
            done < <(compgen -G "$(gt_path "$include")" | LC_ALL=C sort)
            if [[ "$result" == no && "$key" != IncludeOptional ]]; then gt_note UNKNOWN unavailable "web include: $file"; fi
            # The file is inventoried, but assigning included directives to a parent vhost requires expansion.
            if (( in_block )); then gt_note UNKNOWN unavailable "included vhost context: $file"; fi
          fi ;;
      esac
      [[ "$line" != *'{' ]] || depth=$((depth+1))
      [[ "$line" != '}' ]] || depth=$((depth-1))
    done < <(gt_web_directives "$file" "$kind")
    if (( in_block )); then gt_note UNKNOWN unavailable "unterminated vhost: $file"; fi
  done
  for certificate in "$(gt_path /etc/letsencrypt/live)"/*/fullchain.pem; do
    [[ -f "$certificate" ]] && gt_certificate "$certificate"
  done
  FACT[tls.other_clients]=
  for file in "$(gt_path /root/.acme.sh)" "$(gt_path /root/.lego)" "$(gt_path /etc/dehydrated)" \
      "$(gt_path /var/lib/dehydrated)"; do
    [[ -d "$file" ]] && FACT[tls.other_clients]+="$file "
  done
  return 0
}
gt_certificate() {
  local value
  if value=$(gt_probe openssl x509 -in "$1" -noout -subject -enddate -ext subjectAltName); then
    CERTS+=("$1: $value")
  else CERTS+=("$1: UNKNOWN"); fi
}
gt_dynamic_dns() {
  local file
  FACT[dns.duckdns]=no FACT[dns.ddclient]=no
  [[ "${FACT[containers]:-}" == *duckdns* ]] && FACT[dns.duckdns]=yes
  FACT[dns.updater_files]=
  while IFS= read -r -d '' file; do
    # Only file names leave the collector; cron lines and ddclient files can contain credentials.
    if grep -qiE 'duckdns\.org(/update)?|duckdns' "$file" 2>/dev/null; then
      FACT[dns.duckdns]=yes FACT[dns.updater_files]+="$file "
    fi
  done < <(find "$(gt_path /var/spool/cron/crontabs)" "$(gt_path /etc/cron.d)" \
    "$(gt_path /etc/systemd/system)" "$(gt_path /etc/crontab)" "$(gt_path /etc/ddclient.conf)" \
    -type f -print0 2>/dev/null)
  [[ -f "$(gt_path /etc/ddclient.conf)" ]] && FACT[dns.ddclient]=yes
  return 0
}
gt_action() { ACTION[$1]=$2 REASON[$1]=$3; [[ "$2" != block ]] || BLOCKS=$((BLOCKS+1)); }
gt_compatibility() {
  local distro=${FACT[os.ID]} release=${FACT[os.VERSION_ID]} arch=${FACT[architecture]} candidate version device
  ACTION=() REASON=() DISKS=() DISK_FREE=() DISK_NEED=()
  BLOCKS=0
  unset 'FACT[disk.unknown]'
  if [[ "$distro" != debian && "$distro" != ubuntu ]]; then
    case " ${FACT[os.ID_LIKE]} " in *' ubuntu '*) distro=ubuntu ;; *' debian '*) distro=debian ;; esac
  fi
  case "$distro:$release" in
    debian:12|debian:13|ubuntu:24.04|ubuntu:26.04) gt_action platform reuse 'supported primary release' ;;
    debian:11) gt_action platform reuse 'legacy release'; gt_note WARN legacy 'Debian 11 LTS ended 2026-08-31' ;;
    ubuntu:22.04) gt_action platform reuse 'legacy release'; gt_note WARN legacy 'Ubuntu 22.04 standard support ends 2027-04' ;;
    *) gt_action platform block 'unsupported or unknown distribution/release' ;;
  esac
  case "$arch" in amd64|arm64) gt_action architecture reuse "$arch" ;; armhf)
    if [[ "$(date -u +%F)" < 2027-04-30 ]]; then gt_action architecture reuse armhf; gt_note WARN legacy 'armhf requires Node 22; support ends 2027-04-30'
    else gt_action architecture block 'armhf Node 22 support ended 2027-04-30'; fi ;;
    *) gt_action architecture block 'unsupported or unknown architecture' ;;
  esac
  if [[ "${FACT[init]}" == systemd ]]; then gt_action init reuse systemd; else gt_action init block 'PID 1 must be systemd'; fi
  case "${FACT[host.class]}" in
    classic|completed) gt_action host reuse 'existing installation; bootstrap disabled'; gt_note WARN existing './gtupdate.sh (grafioschtrader)' ;;
    docker) gt_action host reuse 'existing Docker installation; bootstrap disabled'; gt_note WARN existing docker/update.sh ;;
    foreign-partial|invalid-state) gt_action host block 'existing foreign pieces or invalid installer state'; gt_note WARN partial ;;
    unknown) gt_action host block 'installation inventory UNKNOWN' ;;
    unfinished) gt_action host block 'resumption requires --install-core and a valid core journal'; gt_note WARN running ;;
    *) gt_action host install 'fresh host' ;;
  esac
  candidate=${CANDIDATE[openjdk-$JAVA_REQUIRED-jdk-headless]:-unknown}
  if [[ "${FACT[java.suitable]}" != absent ]]; then
    gt_action java reuse "${FACT[java.suitable]}; preserve system alternatives"
    version=${FACT[java.version]%%.*}
    (( version == JAVA_REQUIRED )) || gt_note WARN unavailable 'Java newer than the tested major'
  elif [[ "$candidate" != unknown && "$candidate" != '(none)' ]]; then
    gt_action java install "distribution JDK candidate $candidate; preserve alternatives"
  elif [[ "$arch" == armhf ]]; then gt_action java isolate 'Liberica JDK tarball; preserve alternatives'
  else gt_action java install 'Temurin JDK repository; preserve alternatives'; fi
  version=${FACT[maven.version]}
  candidate=${CANDIDATE[maven]:-unknown}; candidate=${candidate#*:}; candidate=${candidate%%-*}
  if gt_version_at_least "$version" 3.8; then gt_action maven reuse "${FACT[maven.path]}"
  elif gt_version_at_least "$candidate" 3.8; then gt_action maven install "distribution Maven $candidate"
  else gt_action maven isolate 'verified Apache Maven 3.9 tarball'; fi
  if gt_node_satisfies "${FACT[node.version]}" "$NODE_REQUIRED"; then gt_action node reuse "${FACT[node.path]}"
  elif [[ "${FACT[node.version]}" != absent && "${FACT[node.consumers]}" != no ]]; then
    gt_action node isolate 'official Node tarball; other consumers must keep their runtime'
  else gt_action node install 'isolated official Node 24 archive on amd64/arm64; Node 22 on armhf'; fi
  if gt_version_at_least "${FACT[angular.version]}" "$CLI_REQUIRED"; then gt_action angular_cli reuse "${FACT[angular.version]}"
  else gt_action angular_cli install "Angular CLI $CLI_REQUIRED using selected Node/npm"; fi
  if [[ "${FACT[semver.version]}" =~ ^[0-9]+\. ]]; then gt_action semver reuse "${FACT[semver.version]}"
  else gt_action semver install 'global npm semver using selected Node/npm'; fi
  case "${FACT[database.vendor]}" in
    absent)
      gt_action mariadb install 'MariaDB server/client'
      candidate=${CANDIDATE[mariadb-server]:-unknown}; candidate=${candidate#*:}; candidate=${candidate%%-*}
      if gt_version_at_least "$candidate" 11.5 && [[ "${FACT[source.collation]}" != yes ]]; then
        gt_action mariadb block 'planned connection collation initialization absent or unknown'
      fi ;;
    mariadb)
      if gt_version_at_least "${FACT[database.version]}" 10.3; then gt_action mariadb reuse "${FACT[database.version]}"
      else gt_action mariadb block 'MariaDB 10.3 or newer required'; fi
      if gt_version_at_least "${FACT[database.version]}" 11.5 && [[ "${FACT[source.collation]}" != yes ]]; then
        gt_action mariadb block 'planned connection collation initialization absent or unknown'
      fi ;;
    *) gt_action mariadb block 'Oracle MySQL or unknown database vendor' ;;
  esac
  case "${FACT[database.gt_tables]}" in
    absent) gt_action database install 'create grafioschtrader database' ;;
    0) gt_action database reuse 'empty database; confirmation required in question stage' ;;
    unknown)
      if [[ "${FACT[database.vendor]}" == absent ]]; then gt_action database install 'create after installing MariaDB'
      else gt_action database block 'database contents UNKNOWN; authenticate before planning changes'; fi ;;
    *) gt_action database block 'non-empty grafioschtrader database must not be adopted' ;;
  esac
  case "${FACT[database.gt_user]}" in
    present) gt_action database_user reuse 'password must be supplied and verified later; never rotate it' ;;
    absent) gt_action database_user install 'grafioschtrader@localhost' ;;
    *) gt_action database_user block 'database accounts UNKNOWN until authenticated inventory' ;;
  esac
  if [[ "${FACT[database.vendor]}" == absent ]]; then gt_action database_user install 'create after installing MariaDB'; fi
  gt_web_recommendation
  version=${FACT[memory.MemTotal]}
  if [[ "$version" =~ ^[0-9]+$ ]]; then
    (( version >= 2000 )) || gt_note WARN memory 'backend build may be slow; swap advised'
    (( version >= 3700 )) || gt_note WARN memory 'downloaded frontend can be newer than the backend source'
    FACT[frontend.mode]=build; (( version >= 3700 )) || FACT[frontend.mode]=download
    if (( version < 4000 )) && [[ "${FACT[memory.SwapTotal]}" == 0 ]]; then
      gt_action swap install 'offer 2 GiB swap in question stage; verify btrfs support'
      gt_disk / 2048
    else gt_action swap reuse 'no additional swap proposed'; fi
    if [[ "${FACT[memory.MemAvailable]}" =~ ^[0-9]+$ ]] && (( ${FACT[memory.MemAvailable]} < version / 2 )); then
      gt_note WARN memory 'other processes use more than half of RAM'
      FACT[memory.largest_processes]=$(gt_probe ps -eo pid,comm,rss --sort=-rss | head -n 6) || FACT[memory.largest_processes]=unknown
    fi
  else gt_action memory block 'RAM size UNKNOWN'; fi
  gt_disk /home 4096
  gt_disk /var/www 0
  gt_disk /opt 300
  gt_disk "${FACT[database.datadir]}" 2048
  gt_action disk reuse 'requirements aggregated by filesystem device'
  [[ "${FACT[disk.unknown]:-no}" != yes ]] || gt_action disk block 'disk capacity UNKNOWN'
  for device in "${!DISK_NEED[@]}"; do
    if (( DISK_FREE[$device] < DISK_NEED[$device] )); then gt_action disk block "device $device needs ${DISK_NEED[$device]} MiB; ${DISK_FREE[$device]} MiB free"; fi
  done
  # A check never authorizes a package transaction or adopts an existing installation.
}

gt_port_free() {
  [[ "${FACT[listeners]}" != unknown ]] || return 1
  ! awk -v port="$1" '$4 ~ (":" port "$") {found=1} END {exit !found}' <<< "${FACT[listeners]}"
}
gt_next_port() {
  local port=$1
  [[ "${FACT[listeners]}" != unknown ]] || { echo unknown; return; }
  while (( port < 65536 )); do gt_port_free "$port" && { echo "$port"; return; }; port=$((port+1)); done
  echo unknown
}
gt_proxy_port_default() {
  local port=8081
  [[ "${FACT[listeners]:-unknown}" != unknown ]] || { echo unknown; return; }
  while (( port < 65536 )); do
    if [[ "$port" != "${ANSWER[BACKEND_PORT]:-${FACT[ports.backend_primary]:-9090}}" &&
          "$port" != "${ANSWER[BACKEND_HTTP_PORT]:-${FACT[ports.backend_http]:-8080}}" ]] && gt_port_free "$port"; then
      echo "$port"; return
    fi
    port=$((port+1))
  done
  echo unknown
}
gt_web_recommendation() {
  local owners
  owners=$(awk '$4 ~ /:(80|443)$/ {print}' <<< "${FACT[listeners]}")
  if [[ "${FACT[listeners]}" == unknown ]]; then gt_action web block 'port owners UNKNOWN'
  elif [[ -n "$owners" && "$owners" != *nginx* && "$owners" != *apache2* ]]; then
    gt_action web reuse 'foreign proxy owns 80/443; choose proxy topology or no web integration later'
  elif [[ "$owners" == *nginx* && "$owners" != *apache2* ]]; then gt_action web reuse nginx
  elif [[ "$owners" == *apache2* && "$owners" != *nginx* ]]; then gt_action web reuse apache2
  elif [[ "${FACT[web.nginx]}" != absent && "${FACT[web.apache2]}" == absent ]]; then gt_action web reuse nginx
  elif [[ "${FACT[web.apache2]}" != absent && "${FACT[web.nginx]}" == absent ]]; then gt_action web reuse apache2
  else gt_action web install 'selection required; default nginx'; fi
  FACT[ports.backend_primary]=$(gt_next_port 9090)
  FACT[ports.backend_http]=$(gt_next_port 8080)
  if [[ "${FACT[ports.backend_primary]}" == "${FACT[ports.backend_http]}" && "${FACT[ports.backend_primary]}" != unknown ]]; then
    FACT[ports.backend_primary]=$(gt_next_port "$((${FACT[ports.backend_primary]}+1))")
  fi
  FACT[ports.proxy_http]=$(gt_proxy_port_default)
  return 0
}

gt_report_rows() {
  local title=$1 row
  shift
  printf '\n[%s]\n' "$title"
  for row in "$@"; do gt_safe "$row"; printf '\n'; done
}
gt_report() {
  local key
  gt_message title
  gt_message facts
  while IFS= read -r key; do
    printf '%s=' "$key"; gt_safe "${FACT[$key]}"; printf '\n'
  done < <(printf '%s\n' "${!FACT[@]}" | LC_ALL=C sort)
  gt_report_rows JDKs "${JDKS[@]}"
  gt_report_rows disks "${DISKS[@]}"
  gt_report_rows consumers "${CONSUMERS[@]}"
  gt_report_rows web "${WEB[@]}"
  gt_report_rows certificates "${CERTS[@]}"
  gt_report_rows network "${NETWORK[@]}"
  printf '\n'; gt_message actions
  BLOCKS=0
  while IFS= read -r key; do
    [[ "${ACTION[$key]}" != block ]] || BLOCKS=$((BLOCKS+1))
    printf '%-18s %-8s ' "$key" "${ACTION[$key]}"; gt_safe "${REASON[$key]}"; printf '\n'
  done < <(printf '%s\n' "${!ACTION[@]}" | LC_ALL=C sort)
  printf '\n'; gt_message notes
  for key in "${NOTES[@]}"; do gt_safe "$key"; printf '\n'; done | LC_ALL=C sort -u
  gt_message footer "$BLOCKS"
  gt_toolchain_guidance
}
gt_inventory() {
  gt_source_revision
  gt_system
  gt_packages
  gt_installation
  gt_java
  gt_runtimes
  gt_consumers
  gt_database
  gt_network
  gt_web
  gt_dynamic_dns
}
gt_check() {
  local completed_status
  completed_status=0
  gt_completed || completed_status=$?
  (( completed_status == 3 )) || return "$completed_status"
  gt_inventory
  gt_compatibility
  gt_report
  (( BLOCKS == 0 )) || return 2
}

# Question definitions contain no shell expressions. Conditions, defaults and validation are shared
# by the plain renderer and the planner; future front ends must use these same functions.
gt_text() { if [[ "$LANG_CODE" == de ]]; then printf '%s\n' "$2"; else printf '%s\n' "$1"; fi; }
gt_question_model() {
  local key type when choices en de
  QUESTIONS=() Q_TYPE=() Q_WHEN=() Q_CHOICES=() Q_EN=() Q_DE=()
  while IFS='|' read -r key type when choices en de; do
    QUESTIONS+=("$key"); Q_TYPE[$key]=$type Q_WHEN[$key]=$when Q_CHOICES[$key]=$choices Q_EN[$key]=$en Q_DE[$key]=$de
    [[ "$type" != yesno ]] || Q_CHOICES[$key]='yes no'
  done <<'QUESTIONS'
DOMAIN|domain|always||Public domain; empty for LAN only|Öffentliche Domain; leer für nur LAN
DNS_FAMILY|choice|domain|ipv4 ipv6 both|Reachable address families; choose ipv6 for DS-Lite/CGNAT|Erreichbare Adressfamilien; ipv6 bei DS-Lite/CGNAT wählen
DUCKDNS_UPDATER|yesno|duckdns||Run a DuckDNS updater here; no if your router or another client updates it|DuckDNS hier aktualisieren; nein bei Aktualisierung durch Router oder anderen Client
DUCKDNS_TOKEN|secret|duck_updater||DuckDNS token required during installation|DuckDNS-Token bei der Installation erforderlich
TLS_SOURCE|choice|domain|letsencrypt existing proxy|TLS provider: certbot, existing certificate, or terminating proxy|TLS-Anbieter: certbot, vorhandenes Zertifikat oder vorgeschalteter Proxy
LETSENCRYPT_EMAIL|email|letsencrypt||Email for Let's Encrypt|E-Mail für Let's Encrypt
LETSENCRYPT_CERT_NAME|lineage|letsencrypt||Reuse this Certbot lineage with its renewal configuration; - requests a new certificate|Diese Certbot-Zertifikatsreihe samt Erneuerung verwenden; - fordert ein neues Zertifikat an
TLS_CERT|path|existing_tls||Readable full-chain certificate file; renewal remains your responsibility|Lesbare Zertifikatsdatei mit vollständiger Kette; Erneuerung bleibt Ihre Aufgabe
TLS_KEY|path|existing_tls||Private key file, readable only by its owner|Privater Schlüssel, nur für den Eigentümer lesbar
TLS_PROXY_LISTEN|port|proxy||Local HTTP port receiving proxy traffic|Lokaler HTTP-Port für Proxy-Anfragen
TLS_PROXY_FROM|address|proxy||Proxy IP address; empty allows every source|IP-Adresse des Proxys; leer erlaubt alle Quellen
WEBSERVER|choice|always|nginx apache2 none|Web integration; none leaves manual configuration pending|Web-Integration; none lässt die manuelle Konfiguration offen
VHOST_INCLUDE|yesno|vhost||Permit an include in the identified vhost after backup and route checks|Include im erkannten Vhost nach Sicherung und Routenprüfung erlauben
BACKEND_PORT|port|always||Primary backend port, bound to loopback|Primärer Backend-Port, an Loopback gebunden
BACKEND_HTTP_PORT|port|apache||Additional loopback HTTP port required by Apache topology|Zusätzlicher Loopback-HTTP-Port für die Apache-Topologie
ADMIN_EMAIL|email|always||Email whose registration becomes administrator|E-Mail-Adresse, deren Registrierung Administrator wird
ALLOWED_USERS|integer|always||Maximum number of users|Maximale Anzahl Benutzer
SMTP_CONFIGURE|yesno|always||Configure mail; no prevents completed registration|Mail konfigurieren; no verhindert abgeschlossene Registrierungen
SMTP_HOST|host|smtp||SMTP host|SMTP-Server
SMTP_PORT|port|smtp||SMTP port|SMTP-Port
SMTP_AUTH|yesno|smtp||SMTP authentication required|SMTP-Anmeldung erforderlich
SMTP_USER|email|smtp||SMTP login and sender email; also required for unauthenticated relays|SMTP-Anmeldung und Absender-E-Mail; auch für Relays ohne Anmeldung erforderlich
SMTP_SECURITY|choice|smtp|starttls tls none|SMTP transport security; none only for unauthenticated relays|SMTP-Transportverschlüsselung; none nur für Relays ohne Anmeldung
SMTP_PASSWORD|secret|smtp_auth||SMTP password required during installation|SMTP-Passwort bei der Installation erforderlich
SMTP_TEST|yesno|smtp||Send a test message during installation|Bei der Installation eine Testnachricht senden
DB_PASSWORD|secret|always||Grafioschtrader database password (spring.datasource.password)|Grafioschtrader-Datenbankpasswort (spring.datasource.password)
DB_REUSE_EMPTY|yesno|empty_db||Reuse the existing empty grafioschtrader database|Vorhandene leere Datenbank grafioschtrader verwenden
DB_ROOT_PASSWORD|secret|root_password||MariaDB root password; new for a new server, current for an existing server|MariaDB-Root-Passwort; neu für neuen Server, aktuell für vorhandenen Server
JASYPT_PASSWORD|secret|always||Encryption password (JASYPT_ENCRYPTOR_PASSWORD)|Verschlüsselungspasswort (JASYPT_ENCRYPTOR_PASSWORD)
BUFFER_POOL|yesno|buffer||Set MariaDB buffer pool and restart the server, affecting every database|MariaDB-Puffer setzen und Server neu starten; betrifft alle Datenbanken
JAVA_HEAP|heap|always||Java heap: -Xms<size> -Xmx<size>, with m or g units|Java-Heap: -Xms<Größe> -Xmx<Größe>, mit m oder g
DOCROOT|path|always||Absolute document root; existing application content must remain untouched|Absolutes Dokumentenverzeichnis; vorhandene Anwendungen müssen erhalten bleiben
TIMEZONE|timezone|always||Host time zone used for the first cron setup|Host-Zeitzone für die erste Cron-Einrichtung
SWAP|yesno|swap||Create 2 GiB at /swapfile and add it to /etc/fstab|2 GiB unter /swapfile anlegen und in /etc/fstab eintragen
NODE_REPLACE|yesno|node_shared||Replace shared Node.js instead of isolating; affects other consumers|Gemeinsames Node.js ersetzen statt isolieren; betrifft andere Anwendungen
FIREWALL_ALLOW|yesno|ufw||Add ufw TCP rules for 22 and the selected web ports|ufw-TCP-Regeln für 22 und die gewählten Web-Ports ergänzen
QUESTIONS
}

gt_question_applies() {
  case "${Q_WHEN[$1]}" in
    always) return 0 ;;
    domain) [[ -n "${ANSWER[DOMAIN]:-}" ]] ;;
    duckdns) [[ "${ANSWER[DOMAIN]:-}" == *.duckdns.org ]] ;;
    duck_updater) [[ "${ANSWER[DUCKDNS_UPDATER]:-}" == yes ]] ;;
    letsencrypt) [[ "${ANSWER[TLS_SOURCE]:-}" == letsencrypt ]] ;;
    existing_tls) [[ "${ANSWER[TLS_SOURCE]:-}" == existing ]] ;;
    proxy) [[ "${ANSWER[TLS_SOURCE]:-}" == proxy ]] ;;
    apache) [[ "${ANSWER[WEBSERVER]:-}" == apache2 ]] ;;
    vhost) [[ "${ANSWER[WEBSERVER]:-none}" != none && ${#WEB[@]} -gt 0 ]] ;;
    smtp) [[ "${ANSWER[SMTP_CONFIGURE]:-}" == yes ]] ;;
    smtp_auth) [[ "${ANSWER[SMTP_CONFIGURE]:-}" == yes && "${ANSWER[SMTP_AUTH]:-}" == yes ]] ;;
    empty_db) [[ "${FACT[database.gt_tables]:-}" == 0 ]] ;;
    root_password) [[ "${FACT[database.vendor]:-unknown}" == absent || "${FACT[database.query]:-unknown}" != ok ||
      "${FACT[database.gt_user]:-unknown}" == unknown || "${FACT[database.schemas]:-unknown}" == unknown ||
      "${FACT[database.password_auth]:-}" == yes ]] ;;
    buffer) [[ -z "${FACT[database.buffer_pool_config]:-}" && "${FACT[database.vendor]:-absent}" != mysql ]] ;;
    swap) [[ "${ACTION[swap]:-}" == install ]] ;;
    node_shared) [[ "${ACTION[node]:-}" == isolate ]] ;;
    ufw) [[ "${FACT[firewall.ufw]:-}" == *'Status: active'* ]] ;;
    *) return 1 ;;
  esac
}

gt_memory_defaults() {
  local mem=${FACT[memory.MemTotal]:-0} row=0 pool=384 max
  [[ "$mem" =~ ^[0-9]+$ ]] || mem=0
  if (( mem >= 6000 )); then row=2; pool=2048
  elif (( mem >= 3000 )); then row=1; pool=1024; fi
  local -a heaps=('-Xms128m -Xmx896m' '-Xms256m -Xmx1792m' '-Xms512m -Xmx2048m') sizes=(896 1792 2048)
  max=${sizes[row]}
  [[ "${ANSWER[BUFFER_POOL]:-no}" == yes ]] || pool=0
  if (( row > 0 && (max+pool)*100 > mem*60 )); then row=$((row-1)); fi
  printf '%s' "${heaps[row]}"
}

gt_certificate_covers() {
  # x509 -checkhost prints a mismatch but still exits zero on OpenSSL 3.0. Verification
  # returns a meaningful status. Trusting the leaf here checks names only; deployment trust
  # is checked separately against the system store in gt_plan_certificate.
  gt_probe openssl x509 -in "$1" -noout -ext subjectAltName | grep -q 'DNS:' || return 1
  gt_probe openssl verify -trusted "$1" -partial_chain -no_check_time -verify_hostname "$2" "$1" >/dev/null
}
gt_tls_default() {
  local row file existing=no
  for row in "${CERTS[@]}"; do
    file=${row%%: *}
    if [[ -r "$file" ]] && gt_certificate_covers "$file" "${ANSWER[DOMAIN]}"; then
      [[ "$file" == */etc/letsencrypt/live/* ]] && { echo letsencrypt; return; }
      existing=yes
    fi
  done
  [[ "$existing" != yes ]] || { echo existing; return; }
  if [[ "${REASON[web]:-}" == 'foreign proxy'* || "${FACT[web.cloudflared]:-}" == *'LoadState=loaded'* ]]; then echo proxy
  else echo letsencrypt; fi
}
gt_certificate_default() {
  local row web_row file label directive value wanted_label=''
  for row in "${CERTS[@]}"; do
    file=${row%%: *}
    if [[ -r "$file" ]] && gt_certificate_covers "$file" "${ANSWER[DOMAIN]}"; then
      if [[ "$1" == TLS_CERT ]]; then printf '%s' "${file#"$ROOT"}"; return; fi
      for web_row in "${WEB[@]}"; do
        read -r label directive value <<< "$web_row"
        if [[ "$directive" == ssl_certificate || "$directive" == SSLCertificateFile ]]; then
          [[ "$(gt_path "$value")" != "$file" ]] || wanted_label=$label
        fi
      done
      for web_row in "${WEB[@]}"; do
        read -r label directive value <<< "$web_row"
        if [[ -n "$wanted_label" && "$label" == "$wanted_label" && ( "$directive" == ssl_certificate_key || "$directive" == SSLCertificateKeyFile ) ]]; then printf '%s' "$value"; return; fi
      done
      value=${file#"$ROOT"}
      [[ ! -r "${file%/*}/privkey.pem" ]] || printf '%s/privkey.pem' "${value%/*}"
      return
    fi
  done
}
gt_certbot_default() {
  local row file name
  for row in "${CERTS[@]}"; do
    file=${row%%: *}
    [[ "$file" == "$(gt_path /etc/letsencrypt/live)/"*/fullchain.pem ]] || continue
    name=${file%/fullchain.pem}; name=${name##*/}
    gt_validate_answer LETSENCRYPT_CERT_NAME "$name" || continue
    if gt_certificate_covers "$file" "${ANSWER[DOMAIN]}"; then printf '%s' "$name"; return; fi
  done
  printf '-'
}
gt_vhost_root_default() {
  local row label directive value name match
  local -A matches=()
  for row in "${WEB[@]}"; do
    read -r label directive value <<< "$row"
    case "$directive" in server_name|ServerName|ServerAlias)
      for name in ${value//\"/}; do
        if [[ -n "${ANSWER[DOMAIN]:-}" && "$name" == "${ANSWER[DOMAIN]}" || "$name" == "${FACT[network.lan_ipv4]:-unknown}" ]]; then matches[$label]=1; fi
      done ;;
    esac
  done
  (( ${#matches[@]} == 1 )) || return 1
  for match in "${!matches[@]}"; do :; done
  for row in "${WEB[@]}"; do
    read -r label directive value <<< "$row"
    if [[ "$label" == "$match" && ( "$directive" == root || "$directive" == DocumentRoot ) ]]; then
      value=${value//\"/}; gt_valid_path "$value" || return 1
      printf '%s' "$value"; return 0
    fi
  done
  return 1
}
gt_default() {
  local value
  case "$1" in
    DNS_FAMILY)
      if [[ "${FACT[network.global_ipv6]:-unknown}" != unknown && -n "${FACT[network.global_ipv6]:-}" ]]; then
        [[ "${FACT[network.public_ipv4]:-unknown}" == unknown ]] && echo ipv6 || echo both
      else echo ipv4; fi ;;
    DUCKDNS_UPDATER) echo no ;;
    TLS_SOURCE) gt_tls_default ;;
    LETSENCRYPT_CERT_NAME) gt_certbot_default ;;
    TLS_CERT|TLS_KEY) gt_certificate_default "$1" ;;
    TLS_PROXY_LISTEN) gt_proxy_port_default ;;
    WEBSERVER)
      case "${REASON[web]:-}" in nginx|apache2) echo "${REASON[web]}" ;;
        'foreign proxy'*) [[ "${ANSWER[TLS_SOURCE]:-}" == proxy ]] && echo nginx || echo none ;;
        *) echo nginx ;; esac ;;
    BACKEND_PORT) echo "${FACT[ports.backend_primary]:-9090}" ;;
    BACKEND_HTTP_PORT) echo "${FACT[ports.backend_http]:-8080}" ;;
    ALLOWED_USERS) echo 20 ;;
    SMTP_PORT) echo 587 ;;
    SMTP_CONFIGURE|SMTP_AUTH) echo yes ;;
    SMTP_SECURITY) case "${ANSWER[SMTP_PORT]:-}" in 587) echo starttls ;; 465) echo tls ;; esac ;;
    SMTP_TEST) echo yes ;;
    SWAP) echo no ;;
    DB_REUSE_EMPTY|NODE_REPLACE|VHOST_INCLUDE|FIREWALL_ALLOW) echo no ;;
    BUFFER_POOL)
      value=${FACT[database.schemas]:-unknown}
      if [[ "${FACT[database.vendor]:-}" == absent ]]; then echo yes
      elif [[ "$value" == unknown ]] || awk -F '\t' '$1 !~ /^(mysql|information_schema|performance_schema|sys|grafioschtrader)$/ {found=1} END {exit !found}' <<< "$value"; then echo no
      else echo yes; fi ;;
    JAVA_HEAP) gt_memory_defaults ;;
    DOCROOT) gt_vhost_root_default || echo "/var/www/${ANSWER[DOMAIN]:-gt}" ;;
    TIMEZONE) value=${FACT[timezone]:-unknown}; [[ "$value" != unknown ]] && echo "$value" ;;
    *) printf '' ;;
  esac
}

gt_valid_hostname() {
  local name=$1 label
  [[ ${#name} -le 253 && "$name" != *..* && "$name" != .* && "$name" != *. ]] || return 1
  local -a labels
  IFS=. read -r -a labels <<< "$name"
  (( ${#labels[@]} > 0 )) || return 1
  for label in "${labels[@]}"; do
    [[ ${#label} -le 63 && "$label" =~ ^[a-zA-Z0-9]([a-zA-Z0-9-]*[a-zA-Z0-9])?$ ]] || return 1
  done
}
gt_valid_address() {
  local value=$1 octet part left right count=0
  local -a parts
  if [[ "$value" == *:* ]]; then
    [[ "$value" =~ ^[0-9a-fA-F:]+$ && "$value" != *:::* ]] || return 1
    if [[ "$value" == *::* ]]; then
      left=${value%%::*}; right=${value#*::}; [[ "$right" != *::* ]] || return 1
      value="$left:$right"
      IFS=: read -r -a parts <<< "$value"
      for part in "${parts[@]}"; do [[ -z "$part" || ${#part} -le 4 ]] || return 1; [[ -z "$part" ]] || count=$((count+1)); done
      (( count < 8 ))
    else
      [[ "$value" != :* && "$value" != *: ]] || return 1
      IFS=: read -r -a parts <<< "$value"
      (( ${#parts[@]} == 8 )) || return 1
      for part in "${parts[@]}"; do [[ ${#part} -le 4 ]] || return 1; done
    fi
  else
    [[ "$value" =~ ^[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+$ ]] || return 1
    IFS=. read -r -a parts <<< "$value"
    for octet in "${parts[@]}"; do [[ ${#octet} -le 3 ]] && (( 10#$octet <= 255 )) || return 1; done
  fi
}
gt_normalize_addresses() {
  local address left right part count fill i
  local -a pieces
  while IFS= read -r address; do
    [[ -n "$address" ]] || continue
    gt_valid_address "$address" || { printf 'unknown\n'; continue; }
    if [[ "$address" != *:* ]]; then printf '%s\n' "$address"; continue; fi
    if [[ "$address" == *::* ]]; then
      left=${address%%::*}; right=${address#*::}; count=0
      IFS=: read -r -a pieces <<< "$left:$right"
      for part in "${pieces[@]}"; do [[ -z "$part" ]] || count=$((count+1)); done
      fill=''
      for ((i=count; i<8; i++)); do fill+='0:'; done
      address="${left:+$left:}$fill$right"; address=${address%:}
    fi
    IFS=: read -r -a pieces <<< "$address"
    for ((i=0; i<8; i++)); do
      (( i == 0 )) || printf ':'
      printf '%x' "$((16#${pieces[i]}))"
    done
    printf '\n'
  done | LC_ALL=C sort -u
}
gt_valid_path() {
  # Restrict to literal, normalized paths usable in all target configuration formats.
  [[ "$1" =~ ^/([a-zA-Z0-9_.-]+/)*[a-zA-Z0-9_.-]+$ && "/$1/" != */../* && "/$1/" != */./* ]]
}
gt_validate_answer() {
  local key=$1 value=$2 min max
  [[ -n "${Q_TYPE[$key]:-}" && "$value" != *[$'\001'-$'\037'$'\177']* ]] || return 1
  case "${Q_TYPE[$key]}" in
    domain) [[ -z "$value" ]] || { [[ "$value" == *.* && ! "$value" =~ ^[0-9.]+$ ]] && gt_valid_hostname "$value"; } ;;
    host) gt_valid_hostname "$value" ;;
    email) [[ "$value" =~ ^[a-zA-Z0-9._%+-]+@[^@]+$ ]] && gt_valid_hostname "${value#*@}" && [[ "${value#*@}" == *.* ]] ;;
    yesno) [[ "$value" == yes || "$value" == no ]] ;;
    choice) [[ "$value" =~ ^[a-zA-Z0-9_-]+$ && " ${Q_CHOICES[$key]} " == *" $value "* ]] ;;
    port) [[ "$value" =~ ^[1-9][0-9]{0,4}$ ]] && (( value <= 65535 )) ;;
    integer) [[ "$value" =~ ^[1-9][0-9]{0,8}$ ]] ;;
    path) gt_valid_path "$value" ;;
    lineage) [[ -z "$value" || "$value" == - || "$value" =~ ^[a-zA-Z0-9][a-zA-Z0-9._-]{0,99}$ ]] ;;
    timezone) gt_valid_path "/$value" && [[ "$value" == UTC || -f "$(gt_path "/usr/share/zoneinfo/$value")" ]] ;;
    address) [[ -z "$value" ]] || gt_valid_address "$value" ;;
    heap)
      [[ "$value" =~ ^-Xms([1-9][0-9]{0,5})([mg])\ -Xmx([1-9][0-9]{0,5})([mg])$ ]] || return 1
      min=${BASH_REMATCH[1]}; max=${BASH_REMATCH[3]}
      [[ "${BASH_REMATCH[2]}" != g ]] || min=$((min*1024))
      [[ "${BASH_REMATCH[4]}" != g ]] || max=$((max*1024))
      (( min <= max )) ;;
    text) [[ "$value" != *[$'\n\r']* && ${#value} -le 512 ]] ;;
    secret) return 1 ;; # Dry-run neither collects nor generates secrets.
    *) return 1 ;;
  esac
}

gt_ask() {
  local key=$1 value default prompt
  default=$(gt_default "$key")
  prompt=$(gt_text "${Q_EN[$key]}" "${Q_DE[$key]}")
  while :; do
    printf '%s (%s)%s [%s]: ' "$prompt" "$key" "${Q_CHOICES[$key]:+ ${Q_CHOICES[$key]}}" "$default" >&"$QUESTION_OUTPUT"
    if ! IFS= read -r -u "$QUESTION_FD" value || [[ "$value" == '!quit' ]]; then return 130; fi
    [[ -n "$value" ]] || value=$default
    [[ "$key" != DOMAIN ]] || value=${value,,}
    if gt_validate_answer "$key" "$value"; then ANSWER[$key]=$value; return 0; fi
    gt_text 'Invalid value; try again. !quit cancels.' 'Ungültiger Wert; erneut eingeben. !quit bricht ab.' >&"$QUESTION_OUTPUT"
  done
}
gt_dns_checklist() {
  [[ -n "${ANSWER[DOMAIN]:-}" ]] || return 0
  if [[ "${ANSWER[TLS_SOURCE]:-}" == proxy ]]; then
    gt_text 'Proxy: preserve Host; overwrite client-supplied X-Forwarded-For / X-Forwarded-Proto; forward HTTPS to the local HTTP port.' \
      'Proxy: Host erhalten; Client-Header X-Forwarded-For / X-Forwarded-Proto ersetzen; HTTPS an den lokalen HTTP-Port weiterleiten.'
  else
    gt_text 'Domain checklist: configure A/AAAA records for the selected reachable families and admit TCP 80/443 at the router/firewall.' \
      'Domain-Checkliste: A/AAAA für die gewählten erreichbaren Familien setzen und TCP 80/443 an Router/Firewall freigeben.'
    printf 'IPv4=%s IPv6=%s LAN=%s\n' "${FACT[network.public_ipv4]:-unknown}" "${FACT[network.global_ipv6]:-unknown}" "${FACT[network.lan_ipv4]:-unknown}"
    if [[ "${ANSWER[DOMAIN]}" == *.duckdns.org ]]; then
      gt_text 'DuckDNS: create the account and subdomain yourself; keep the token for installation.' \
        'DuckDNS: Konto und Subdomain selbst anlegen; Token für die Installation bereithalten.'
    fi
  fi
}
gt_questions() {
  local key
  ANSWER=()
  gt_question_model
  if [[ "$MODE" == --install-core ]]; then
    gt_text 'Core configuration: the plan will name the changes before execution. !quit cancels.' \
      'Kernkonfiguration: Der Plan benennt die Änderungen vor der Ausführung. !quit bricht ab.' >&"$QUESTION_OUTPUT"
  elif [[ "$MODE" == --prepare ]]; then
    gt_text 'Preparation only; no installation. Secrets follow the configuration questions. !quit cancels.' \
      'Nur Vorbereitung; keine Installation. Geheimnisse folgen den Konfigurationsfragen. !quit bricht ab.' >&"$QUESTION_OUTPUT"
  else
    gt_text 'Dry-run: no passwords are requested or generated. !quit cancels; Enter accepts the default.' \
      'Dry-run: Passwörter werden weder abgefragt noch erzeugt. !quit bricht ab; Enter übernimmt den Vorschlag.' >&"$QUESTION_OUTPUT"
  fi
  for key in "${QUESTIONS[@]}"; do
    gt_question_applies "$key" || continue
    [[ "${Q_TYPE[$key]}" != secret ]] || continue
    if [[ "$key" == WEBSERVER && ( "${REASON[web]:-}" == nginx || "${REASON[web]:-}" == apache2 ) ]]; then
      ANSWER[$key]=${REASON[web]}
    else gt_ask "$key" || return $?; fi
    if [[ "$key" == DOMAIN || "$key" == TLS_SOURCE ]]; then gt_dns_checklist >&"$QUESTION_OUTPUT"; fi
  done
}

# Secret values live outside ANSWER, which is printable. No caller may enable tracing while
# handling them. Preparation uses only private temporary files and read-only SQL.
gt_secret_error() {
  gt_text 'Credentials could not be read or verified; no installation was performed.' \
    'Zugangsdaten konnten nicht gelesen oder geprüft werden; keine Installation ausgeführt.' >&2
  return 2
}

gt_valid_secret() {
  [[ -n "$1" && "$1" != *[$'\001'-$'\037'$'\177']* ]]
}

gt_restore_terminal() {
  if [[ -n "$TTY_STATE" ]]; then
    stty "$TTY_STATE" <&"$QUESTION_FD"
    TTY_STATE=''
  fi
}

gt_read_secret() {
  # read normally discards NUL. Read one byte with a NUL delimiter to reject it explicitly.
  local char invalid=no LC_ALL=C
  SECRET_INPUT=''
  while IFS= read -r -n 1 -d '' -u "$QUESTION_FD" char; do
    [[ "$char" != $'\n' ]] || { [[ "$invalid" == no ]] && gt_valid_secret "$SECRET_INPUT"; return $?; }
    if [[ -z "$char" || "$char" == *[$'\001'-$'\037'$'\177']* ]]; then
      if [[ -t "$QUESTION_FD" && ( "$char" == $'\177' || "$char" == $'\010' ) ]]; then
        SECRET_INPUT=${SECRET_INPUT%?}
      else invalid=yes; fi
    else SECRET_INPUT+=$char; fi
  done
  SECRET_INPUT=''
  return 130
}

gt_ask_secret() {
  set +vx
  local key=$1 twice=${2:-no} first status
  if [[ -t "$QUESTION_FD" ]]; then
    TTY_STATE=$(stty -g <&"$QUESTION_FD") || return 2
    stty -echo <&"$QUESTION_FD" || { gt_restore_terminal; return 2; }
  fi
  while :; do
    printf '%s (%s): ' "$(gt_text "${Q_EN[$key]}" "${Q_DE[$key]}")" "$key" >&"$QUESTION_OUTPUT"
    status=0; gt_read_secret || status=$?
    printf '\n' >&"$QUESTION_OUTPUT"
    if (( status == 130 )); then gt_restore_terminal; return 130; fi
    if (( status == 0 )); then
      first=$SECRET_INPUT
      if [[ "$twice" == yes ]]; then
        printf '%s (%s): ' "$(gt_text 'Repeat password' 'Passwort wiederholen')" "$key" >&"$QUESTION_OUTPUT"
        gt_read_secret || status=$?
        printf '\n' >&"$QUESTION_OUTPUT"
        if (( status == 130 )); then gt_restore_terminal; return 130; fi
        [[ "$first" == "$SECRET_INPUT" ]] || status=1
      fi
      if (( status == 0 )); then
        SECRET[$key]=$first SECRET_STATUS[$key]=collected SECRET_INPUT=''
        gt_restore_terminal; return 0
      fi
    fi
    SECRET_INPUT=''
    gt_text 'Empty, invalid or mismatched input; try again. Ctrl-C cancels.' \
      'Leere, ungültige oder abweichende Eingabe; erneut eingeben. Strg-C bricht ab.' >&"$QUESTION_OUTPUT"
  done
}

gt_answers_file() {
  set +vx
  local file=$1 fd metadata opened contents line key value
  FILE_ANSWERS=()
  [[ -f "$file" && ! -L "$file" ]] || { gt_secret_error; return 2; }
  metadata=$(stat -c '%u:%a:%d:%i' -- "$file") || return 2
  [[ "$metadata" == 0:600:* ]] || { gt_secret_error; return 2; }
  exec {fd}<"$file" || return 2
  opened=$(stat -Lc '%u:%a:%d:%i' "/dev/fd/$fd")
  if [[ "$metadata" != "$opened" || -L "$file" ]] || IFS= read -r -d '' contents <&"$fd"; then
    exec {fd}<&-; gt_secret_error; return 2
  fi
  exec {fd}<&-
  # Every byte after the first '=' is literal data, including quotes and whitespace.
  while IFS= read -r line || [[ -n "$line" ]]; do
    [[ -n "$line" && "$line" != \#* ]] || continue
    key=${line%%=*}; value=${line#*=}
    if [[ "$line" != *=* || ! "$key" =~ ^[A-Z_]+$ || -z "${Q_TYPE[$key]:-}" || -n "${FILE_ANSWERS[$key]+present}" ||
        "$value" == *[$'\001'-$'\037'$'\177']* ]]; then
      FILE_ANSWERS=(); gt_secret_error; return 2
    fi
    FILE_ANSWERS[$key]=$value
  done <<< "$contents"
}

gt_file_questions() {
  local key
  ANSWER=()
  for key in "${QUESTIONS[@]}"; do
    gt_question_applies "$key" || continue
    [[ "${Q_TYPE[$key]}" != secret ]] || continue
    if [[ -n "${FILE_ANSWERS[$key]+present}" ]]; then ANSWER[$key]=${FILE_ANSWERS[$key]}
    else ANSWER[$key]=$(gt_default "$key"); fi
    if ! gt_validate_answer "$key" "${ANSWER[$key]}"; then
      printf '%s: %s\n' "$(gt_text 'Invalid/missing answer' 'Ungültige/fehlende Antwort')" "$key" >&2; return 2
    fi
    if [[ "$key" == WEBSERVER && ( "${REASON[web]:-}" == nginx || "${REASON[web]:-}" == apache2 ) && "${ANSWER[$key]}" != "${REASON[web]}" ]]; then
      gt_secret_error; return 2
    fi
  done
  for key in "${!FILE_ANSWERS[@]}"; do
    gt_question_applies "$key" || { gt_secret_error; return 2; }
  done
}

gt_collect_secret() {
  local key=$1 twice=${2:-no}
  if [[ -n "$ANSWERS_FILE" ]]; then
    gt_valid_secret "${FILE_ANSWERS[$key]:-}" || { gt_secret_error; return 2; }
    SECRET[$key]=${FILE_ANSWERS[$key]} SECRET_STATUS[$key]=collected
  else gt_ask_secret "$key" "$twice"; fi
}

gt_db_options() {
  # The output is a pathname only. Escape MariaDB option-file syntax, never shell syntax.
  local key=$1 user=$2 file value=${SECRET[$1]:-}
  value=${value//\\/\\\\}; value=${value//\"/\\\"}
  file=$(umask 077; mktemp "$SCRATCH/db.XXXXXX") || return 2
  printf '[client]\nuser=%s\npassword="%s"\n' "$user" "$value" > "$file"
  printf '%s' "$file"
}

gt_prepare_root() {
  local file
  gt_question_applies DB_ROOT_PASSWORD || return 0
  if [[ "${FACT[database.vendor]}" == absent ]]; then
    gt_collect_secret DB_ROOT_PASSWORD yes; return $?
  fi
  [[ "${FACT[database.vendor]}" == mariadb && "${FACT[database.active]}" == yes ]] || { gt_secret_error; return 2; }
  gt_collect_secret DB_ROOT_PASSWORD || return $?
  file=$(gt_db_options DB_ROOT_PASSWORD root) || return 2
  gt_database "$file"
  rm -f -- "$file"
  [[ "${FACT[database.query]}" == ok && "${FACT[database.gt_user]}" != unknown && "${FACT[database.schemas]}" != unknown ]] || { gt_secret_error; return 2; }
  FACT[database.password_auth]=yes SECRET_STATUS[DB_ROOT_PASSWORD]=verified
  # Recompute database recommendations with authenticated facts before asking about reuse.
  ACTION=() REASON=() DISKS=() DISK_FREE=() DISK_NEED=()
  gt_compatibility
}

gt_prepare_secrets() {
  set +vx
  local key twice file client value
  unset 'FACT[database.gt_auth]'
  [[ "${FACT[database.vendor]}" == absent || "${FACT[database.gt_user]}" == absent || "${FACT[database.gt_user]}" == present ]] || { gt_secret_error; return 2; }
  for key in "${QUESTIONS[@]}"; do
    [[ "${Q_TYPE[$key]}" == secret && "$key" != DB_ROOT_PASSWORD ]] || continue
    gt_question_applies "$key" || continue
    twice=no
    [[ "$key" != JASYPT_PASSWORD ]] || twice=yes
    [[ "$key" != DB_PASSWORD || "${FACT[database.gt_user]}" == present ]] || twice=yes
    gt_collect_secret "$key" "$twice" || return $?
  done
  if [[ "${FACT[database.gt_user]}" == present ]]; then
    [[ "${FACT[database.active]}" == yes ]] || { gt_secret_error; return 2; }
    client=$(command -v mariadb || command -v mysql) || { gt_secret_error; return 2; }
    file=$(gt_db_options DB_PASSWORD grafioschtrader) || return 2
    value=$(gt_probe "$client" "--defaults-file=$file" --protocol=TCP --host=127.0.0.1 --port=3306 \
      --user=grafioschtrader --batch --skip-column-names --connect-timeout=4 -e 'SELECT CURRENT_USER();') || value=''
    rm -f -- "$file"
    [[ "$value" == grafioschtrader@localhost ]] || { gt_secret_error; return 2; }
    FACT[database.gt_auth]=ok SECRET_STATUS[DB_PASSWORD]=verified
  fi
  if [[ -z "${SECRET[JWT_SECRET]:-}" ]]; then
    value=$(gt_probe openssl rand -base64 72) || { gt_secret_error; return 2; }
    value=${value//[$'/+=\n']/}; value=${value:0:48}
    [[ "$value" =~ ^[a-zA-Z0-9]{48}$ ]] || { gt_secret_error; return 2; }
    SECRET[JWT_SECRET]=$value SECRET_STATUS[JWT_SECRET]=generated
  fi
}

# A plan consists of display data, never executable command strings. Even blocked plans remain
# inspectable. Revalidate every answer here so future front ends cannot bypass the model.
gt_plan_row() { PLAN+=("$1 | $2 | $(gt_text "$3" "${4:-$3}")"); }
gt_plan_block() { PLAN_BLOCKERS+=("$(gt_text "$1" "${2:-$1}")"); }
gt_plan_warn() { PLAN_WARNINGS+=("$(gt_text "$1" "${2:-$1}")"); }
gt_plan_file() {
  if [[ -e "$(gt_path "$1")" || -L "$(gt_path "$1")" ]]; then
    gt_plan_block "Target already exists: $1; ownership must be resolved." "Ziel existiert bereits: $1; Eigentümerschaft muss geklärt werden."
  fi
  gt_plan_row create "$1" "$2" "${3:-$2}"
}
gt_plan_package() {
  local name=$1
  [[ -z "${PLAN_PACKAGES[$name]:-}" ]] || return 0
  if [[ -n "${PACKAGE[$name]:-}" ]]; then
    PLAN_PACKAGES[$name]=reuse
    gt_plan_row reuse "package:$name" "${PACKAGE[$name]}"
  else
    PLAN_PACKAGES[$name]=install
    gt_plan_row install "package:$name" 'APT candidate; transaction below' 'APT-Kandidat; Transaktion siehe unten'
  fi
}
gt_plan_needs_apt() {
  local package
  for package in "${!PLAN_PACKAGES[@]}"; do
    [[ "${PLAN_PACKAGES[$package]}" != install ]] || return 0
  done
  return 1
}
gt_plan_packages() {
  local package value line
  local -a requested=()
  for package in "${!PLAN_PACKAGES[@]}"; do
    [[ "${PLAN_PACKAGES[$package]}" != install ]] || requested+=("$package")
  done
  (( ${#requested[@]} )) || return 0
  # --simulate neither downloads nor changes packages. --no-download would incorrectly
  # reject simulations for packages whose .deb files are not already cached.
  if ! value=$(gt_probe env LC_ALL=C apt-get --simulate \
      -o Dir::Cache::pkgcache= -o Dir::Cache::srcpkgcache= install "${requested[@]}"); then
    gt_plan_block 'APT simulation failed or timed out; resolve package candidates before installation.' \
      'APT-Simulation fehlgeschlagen oder Zeitlimit erreicht; Paketkandidaten vor der Installation klären.'
    return 0
  fi
  while IFS= read -r line; do
    case "$line" in
      'Remv '*) gt_plan_row remove package "$line"
        gt_plan_block 'APT would remove packages; this increment cannot authorize removals.' 'APT würde Pakete entfernen; diese Stufe erlaubt keine Entfernungen.' ;;
      'Inst '*) gt_plan_row install package "$line"
        # Any existing package upgrade can affect a shared service. Show it and require resolution.
        if [[ "$line" =~ ^Inst[[:space:]]+[^[:space:]]+[[:space:]]+\[ ]]; then
          gt_plan_block "APT would upgrade an existing package: $line" "APT würde ein vorhandenes Paket aktualisieren: $line"
        fi ;;
      'Conf '*) gt_plan_row configure package "$line" ;;
    esac
  done <<< "$value"
}
# Planning and execution consume the same package/module selections.
gt_base_package_names() {
  printf '%s\n' git curl wget ca-certificates gnupg sudo openssl logrotate whiptail tzdata
}

gt_plan_base_packages() {
  local package
  while IFS= read -r package; do
    gt_plan_package "$package"
    if [[ "${STATE[step.base_packages]:-}" == complete && -z "${PACKAGE[$package]:-}" ]]; then
      gt_plan_block "Previously verified base package is missing: $package; restore it before resuming."
    fi
  done < <(gt_base_package_names)
}

gt_web_package_names() {
  [[ "${ANSWER[WEBSERVER]}" != none ]] || return 0
  printf '%s\n' "${ANSWER[WEBSERVER]}"
  [[ "${ANSWER[TLS_SOURCE]:-}" != letsencrypt ]] || printf '%s\n' certbot
}

gt_apache_module_names() {
  case "$1" in
    lan) printf '%s\n' proxy proxy_ajp proxy_http proxy_wstunnel headers alias dir mime authz_core deflate filter ;;
    tls) printf '%s\n' ssl ;;
    *) return 2 ;;
  esac
}

gt_plan_web_runtime() {
  local package modules
  while IFS= read -r package; do gt_plan_package "$package"; done < <(gt_web_package_names)
  [[ "${ANSWER[WEBSERVER]}" == apache2 ]] || return 0
  modules=$(gt_apache_module_names lan | paste -sd ' ')
  gt_plan_row enable apache-modules "$modules (a2enmod also enables required module dependencies)"
  if [[ -n "${ANSWER[DOMAIN]:-}" && "${ANSWER[TLS_SOURCE]:-}" != proxy ]]; then
    modules=$(gt_apache_module_names tls | paste -sd ' ')
    gt_plan_row enable apache-tls-modules "$modules (a2enmod also enables required module dependencies)"
  fi
}

gt_plan_toolchains() {
  local item candidate
  gt_plan_base_packages
  case "${ACTION[java]}" in
    reuse) gt_plan_row reuse java "${REASON[java]}" ;;
    install)
      candidate=${CANDIDATE[openjdk-$JAVA_REQUIRED-jdk-headless]:-unknown}
      if [[ "$candidate" != unknown && "$candidate" != '(none)' ]]; then gt_plan_package "openjdk-$JAVA_REQUIRED-jdk-headless"
      else
        gt_plan_file /etc/apt/keyrings/adoptium.gpg 'Adoptium signing key; verify fingerprint' 'Adoptium-Signaturschlüssel; Fingerabdruck prüfen'
        gt_plan_file /etc/apt/sources.list.d/adoptium.sources 'signed-by Adoptium source' 'Adoptium-Quelle mit signed-by'
        gt_plan_row install "package:temurin-$JAVA_REQUIRED-jdk" 'candidate available after repository setup' 'Kandidat nach Einrichtung der Paketquelle verfügbar'
        gt_plan_block 'Temurin package transaction must be resolved after repository setup.' 'Temurin-Pakettransaktion muss nach Einrichtung der Paketquelle geprüft werden.'
      fi ;;
    isolate) gt_plan_file "/opt/jdk-$JAVA_REQUIRED-gt" 'Liberica JDK tarball, verified checksum' 'Liberica-JDK-Archiv mit geprüfter Prüfsumme' ;;
  esac
  gt_plan_row preserve java-alternatives 'Restore every changed selection; automatic groups may become manual.' \
    'Alle geänderten Alternativen zurücksetzen; automatische Gruppen können auf manuell wechseln.'
  case "${ACTION[maven]}" in
    install) gt_plan_package maven ;;
    isolate) gt_plan_row isolate '/opt/apache-maven-<version>' 'Apache Maven 3.9 archive, verified SHA-512; resolve exact version before execution' \
      'Apache-Maven-3.9-Archiv mit geprüfter SHA-512; genaue Version vor Ausführung festlegen' ;;
    reuse) gt_plan_row reuse maven "${REASON[maven]}" ;;
  esac
  if [[ "${ACTION[node]}" == reuse ]]; then gt_plan_row reuse node "${REASON[node]}"
  elif [[ "${ANSWER[NODE_REPLACE]:-no}" != yes || "${FACT[architecture]}" == armhf ]]; then
    gt_plan_file /opt/nodejs-gt 'Official Node archive satisfying source requirements; verify SHASUMS256.txt' \
      'Offizielles Node-Archiv gemäß Quellcode-Anforderungen; SHASUMS256.txt prüfen'
  else
    gt_plan_file /etc/apt/keyrings/nodesource.gpg 'NodeSource signing key; verify fingerprint' 'NodeSource-Signaturschlüssel; Fingerabdruck prüfen'
    gt_plan_file /etc/apt/sources.list.d/nodesource.sources 'NodeSource 24.x source with signed-by' 'NodeSource-24.x-Quelle mit signed-by'
    [[ "${ANSWER[NODE_REPLACE]:-no}" == yes ]] && item=replace || item=install
    gt_plan_row "$item" package:nodejs 'NodeSource 24; affects the system runtime' 'NodeSource 24; betrifft die System-Laufzeit'
    gt_plan_block 'NodeSource candidate and full transaction are unverified until its repository is available.' \
      'NodeSource-Kandidat und vollständige Transaktion sind ungeprüft, bis die Paketquelle verfügbar ist.'
  fi
  if [[ "${ANSWER[NODE_REPLACE]:-no}" == yes ]]; then
    gt_plan_warn 'Node replacement requested; every shared consumer must be checked before execution.' \
      'Node-Ersatz gewünscht; alle betroffenen Anwendungen müssen vor Ausführung geprüft werden.'
  fi
  gt_plan_row configure npm "@angular/cli@$CLI_REQUIRED and semver in /opt/gt-build-tools; selected Node; NG_CLI_ANALYTICS=false" \
    "@angular/cli@$CLI_REQUIRED und semver in /opt/gt-build-tools; gewähltes Node; NG_CLI_ANALYTICS=false"
}
gt_plan_database() {
  local pool=384M mem=${FACT[memory.MemTotal]:-0}
  if [[ "${FACT[database.vendor]}" == absent ]]; then
    gt_plan_package mariadb-server; gt_plan_package mariadb-client
    gt_plan_row configure mariadb 'Remove anonymous accounts and test schema only on a newly installed server.' \
      'Anonyme Konten und test-Schema nur auf einem neu installierten Server entfernen.'
  fi
  gt_plan_row "${ACTION[database]}" database:grafioschtrader 'utf8mb4 / utf8mb4_general_ci; never adopt non-empty data' \
    'utf8mb4 / utf8mb4_general_ci; niemals vorhandene Daten übernehmen'
  if [[ "${FACT[database.gt_tables]}" == 0 && "${ANSWER[DB_REUSE_EMPTY]:-no}" != yes ]]; then
    gt_plan_block 'Reuse of the empty database was not accepted.' 'Verwendung der leeren Datenbank wurde nicht bestätigt.'
  fi
  if [[ "${FACT[database.gt_user]}" == present ]]; then
    gt_plan_row verify 'account:grafioschtrader@localhost' 'Supply current password and verify TCP login before any database changes; never rotate it.' \
      'Aktuelles Passwort angeben und TCP-Anmeldung vor Datenbankänderungen prüfen; Passwort niemals ändern.'
    if [[ "$MODE" != --prepare || "${FACT[database.gt_auth]:-}" != ok ]]; then
      gt_plan_block 'Existing database account credentials remain unverified.' 'Zugangsdaten des vorhandenen Datenbankkontos bleiben ungeprüft.'
    fi
  elif [[ "${FACT[database.gt_user]}" == absent || "${FACT[database.vendor]}" == absent ]]; then
    gt_plan_row create 'account:grafioschtrader@localhost' 'Use the confirmed password; grant grafioschtrader.* only.' \
      'Bestätigtes Passwort verwenden; Rechte nur für grafioschtrader.* vergeben.'
  else
    gt_plan_row block 'account:grafioschtrader@localhost' 'Authenticate inventory before deciding whether the account exists.' \
      'Bestandsaufnahme authentifizieren, bevor über das Vorhandensein des Kontos entschieden wird.'
  fi
  if [[ "${ANSWER[BUFFER_POOL]:-no}" == yes ]]; then
    [[ "$mem" =~ ^[0-9]+$ ]] || mem=0
    if (( mem >= 6000 )); then pool=2G; elif (( mem >= 3000 )); then pool=1G; fi
    gt_plan_file /etc/mysql/mariadb.conf.d/60-grafioschtrader.cnf "innodb_buffer_pool_size=$pool"
    gt_plan_row restart mariadb 'Affects all listed schemas, including other applications.' 'Betrifft alle aufgeführten Schemas, auch andere Anwendungen.'
  fi
}

gt_plan_ports() {
  local key port
  local -A used=()
  for key in BACKEND_PORT BACKEND_HTTP_PORT TLS_PROXY_LISTEN; do
    port=${ANSWER[$key]:-}; [[ -n "$port" ]] || continue
    if ! gt_port_free "$port" || [[ -n "${used[$port]:-}" ]]; then
      gt_plan_block "Port $port ($key) is occupied, duplicated or UNKNOWN." "Port $port ($key) ist belegt, doppelt vergeben oder UNKNOWN."
    fi
    used[$port]=$key
  done
  if [[ "${ANSWER[WEBSERVER]}" != none && "${ANSWER[TLS_SOURCE]:-}" != proxy ]]; then
    for port in 80 443; do
      [[ "$port" != 443 || -n "${ANSWER[DOMAIN]}" ]] || continue
      [[ -z "${used[$port]:-}" ]] || gt_plan_block "Backend port $port overlaps a planned web listener." "Backend-Port $port überschneidet sich mit einem geplanten Web-Listener."
    done
  fi
  gt_plan_row configure backend "127.0.0.1:${ANSWER[BACKEND_PORT]} (${ANSWER[WEBSERVER]}); HTTP=${ANSWER[BACKEND_HTTP_PORT]:-same}"
}
gt_plan_web() {
  local web=${ANSWER[WEBSERVER]} domain=${ANSWER[DOMAIN]} row label directive value name match='' root='' conflict=no unknown=no file kind=''
  local -A matches=()
  if [[ "$web" == none ]]; then
    gt_plan_file /root/gt-install-webserver.conf 'Manual proxy configuration; web milestone remains pending.' 'Manuelle Proxy-Konfiguration; Web-Meilenstein bleibt offen.'
    gt_plan_warn 'No web integration selected; installation would be incomplete.' 'Keine Web-Integration gewählt; Installation wäre unvollständig.'
    return 0
  fi
  gt_plan_web_runtime
  # Static inventory is evidence, never permission to rewrite an ambiguous foreign server block.
  for row in "${NOTES[@]}"; do [[ "$row" != *UNKNOWN*web* && "$row" != *UNKNOWN*vhost* ]] || unknown=yes; done
  for row in "${WEB[@]}"; do
    read -r label directive value <<< "$row"
    case "$directive" in server_name|ServerName|ServerAlias)
      for name in ${value//\"/}; do
        if [[ -n "$domain" && " ${FACT[plan.names]:-$domain} " == *" $name "* || "$name" == "${FACT[network.lan_ipv4]:-unknown}" ]]; then matches[$label]=1; fi
        [[ "$name" != *'*'* && "$name" != '~'* ]] || unknown=yes
      done ;;
    esac
  done
  if (( ${#matches[@]} == 1 )); then
    for match in "${!matches[@]}"; do :; done
    for row in "${WEB[@]}"; do
      read -r label directive value <<< "$row"; [[ "$label" == "$match" ]] || continue
      case "$directive" in
        server_kind) kind=$value ;;
        root|DocumentRoot) root=${value//\"/} ;;
        location|ProxyPass|ProxyPassMatch) [[ "$value" != *'/api'* && "$value" != *'/m2m'* && "$value" != *'/socket'* && "$value" != *'/ws'* && "$value" != *'/grafioschtrader'* ]] || conflict=yes ;;
      esac
    done
    [[ "$web:$kind" == nginx:nginx || "$web:$kind" == apache2:apache ]] || unknown=yes
  elif (( ${#matches[@]} > 1 )); then unknown=yes; fi
  FACT[plan.vhost_root]=$root
  if [[ -n "$match" ]]; then
    if [[ -z "$root" || "${ANSWER[DOCROOT]}" != "$root" ]]; then
      gt_plan_block 'Snippet document root must match the identified vhost root.' 'Dokumentenverzeichnis des Snippets muss zum erkannten Vhost passen.'
    fi
    [[ "$web" == nginx ]] && file=/etc/nginx/snippets/grafioschtrader.conf || file=/etc/apache2/conf-available/grafioschtrader.conf
    gt_plan_file "$file" 'GT routes and frontend fallback' 'GT-Routen und Frontend-Fallback'
    if [[ "${ANSWER[VHOST_INCLUDE]:-no}" == yes && "$unknown" == no && "$conflict" == no ]]; then
      gt_plan_row backup "${match%#*}.gt-install.<timestamp>" 'Before inserting include; restore on validation failure.' 'Vor Include-Einfügung; bei fehlgeschlagener Prüfung wiederherstellen.'
      gt_plan_row modify "$match" "include $file"
    else
      gt_plan_block 'Existing vhost needs an unambiguous, conflict-free include and explicit consent.' \
        'Vorhandener Vhost benötigt einen eindeutigen, konfliktfreien Include und ausdrückliche Zustimmung.'
    fi
  else
    [[ "$web" == nginx ]] && file=/etc/nginx/sites-available/grafioschtrader || file=/etc/apache2/sites-available/grafioschtrader.conf
    gt_plan_file "$file" 'Own vhost: /api, /m2m, /socket/websocket, /ws, /grafioschtrader; preserve other sites.' \
      'Eigener Vhost: /api, /m2m, /socket/websocket, /ws, /grafioschtrader; andere Sites erhalten.'
    gt_plan_file "${file/sites-available/sites-enabled}" 'Enable own vhost' 'Eigenen Vhost aktivieren'
  fi
  [[ "$unknown" == no ]] || gt_plan_block 'Effective web configuration is ambiguous or includes unresolved context.' 'Effektive Web-Konfiguration ist mehrdeutig oder enthält ungeklärte Includes.'
  if [[ "${ANSWER[TLS_SOURCE]:-}" != proxy ]]; then
    for name in 80 443; do
      [[ "$name" != 443 || -n "$domain" ]] || continue
      if ! gt_port_free "$name" && ! awk -v port="$name" -v owner="$web" '$4 ~ (":" port "$") && index($0,owner) {found=1} END {exit !found}' <<< "${FACT[listeners]}"; then
        gt_plan_block "Web port $name belongs to another process or is UNKNOWN." "Web-Port $name gehört einem anderen Prozess oder ist UNKNOWN."
      fi
    done
  fi
  gt_plan_row verify "$web" 'Configuration test and existing vhost HTTP comparisons before/after reload; restore on failure.' \
    'Konfigurationstest und HTTP-Vergleich vorhandener Vhosts vor/nach Reload; bei Fehler wiederherstellen.'
}
gt_plan_storage() {
  local path=${ANSWER[DOCROOT]} actual device max mem=${FACT[memory.MemTotal]:-unknown} filesystem
  actual=$(gt_path "$path")
  if [[ -L "$actual" || -e "$actual" && ! -d "$actual" ]]; then
    gt_plan_block "Document root is a symlink or not a directory: $path" "Dokumentenverzeichnis ist ein Symlink oder kein Verzeichnis: $path"
  elif [[ -e "$actual/grafioschtrader" || -L "$actual/grafioschtrader" ]]; then
    gt_plan_block "GT content already exists in $path" "GT-Inhalt existiert bereits in $path"
  elif [[ -d "$actual" && -n "$(find "$actual" -mindepth 1 -maxdepth 1 -print -quit)" && "$path" != "${FACT[plan.vhost_root]:-}" ]]; then
    gt_plan_block "Non-empty document root is not the selected vhost root: $path" "Nichtleeres Dokumentenverzeichnis gehört nicht zum gewählten Vhost: $path"
  fi
  gt_plan_row create "$path/grafioschtrader" 'Only this directory is writable by grafioschtrader; preserve shared content.' \
    'Nur dieses Verzeichnis ist für grafioschtrader beschreibbar; gemeinsame Inhalte erhalten.'
  [[ -e "$actual" ]] || gt_plan_row create "$path/index.html" 'Landing page in newly created document root' 'Startseite im neu angelegten Dokumentenverzeichnis'
  DISKS=() DISK_FREE=() DISK_NEED=(); unset 'FACT[disk.unknown]'
  gt_disk /home 4096; gt_disk /opt 300; gt_disk "${FACT[database.datadir]}" 2048; gt_disk "$path" 300
  if [[ "${ANSWER[SWAP]:-no}" == yes ]]; then
    filesystem=$(stat -Lf -c %T "$(gt_path /)" 2>/dev/null) || filesystem=unknown
    if [[ "$filesystem" == btrfs || "$filesystem" == unknown ]]; then
      gt_plan_block 'Swap creation on btrfs/UNKNOWN needs a supported mkswapfile implementation.' 'Swap auf btrfs/UNKNOWN benötigt eine geprüfte mkswapfile-Implementierung.'
    fi
    gt_disk / 2048; gt_plan_file /swapfile '2 GiB swap, mode 600'
    gt_plan_row backup '/etc/fstab.gt-install.<timestamp>' 'Before adding swap entry' 'Vor Ergänzung des Swap-Eintrags'
    gt_plan_row modify /etc/fstab '/swapfile; activate swap' '/swapfile; Swap aktivieren'
  fi
  [[ "${FACT[disk.unknown]:-no}" != yes ]] || gt_plan_block 'Disk capacity UNKNOWN.' 'Freier Speicherplatz UNKNOWN.'
  for device in "${!DISK_NEED[@]}"; do
    (( DISK_FREE[$device] >= DISK_NEED[$device] )) || gt_plan_block "Device $device: ${DISK_NEED[$device]} MiB required, ${DISK_FREE[$device]} MiB available."
  done
  max=${ANSWER[JAVA_HEAP]##*Xmx}; [[ "$max" != *g ]] || max="$((${max%g}*1024))m"; max=${max%m}
  if [[ "$mem" =~ ^[0-9]+$ ]] && (( max >= mem )); then gt_plan_block 'Maximum Java heap must be smaller than RAM.' 'Maximaler Java-Heap muss kleiner als RAM sein.'; fi
}

gt_dns_required() { [[ -n "${ANSWER[DOMAIN]:-}" && "${ANSWER[TLS_SOURCE]:-}" != proxy ]]; }
gt_dns_tool_available() { command -v dig >/dev/null 2>&1; }

# Inputs are normalized, newline-separated address sets. Every published address
# must be usable, but a host need not publish all of its stable IPv6 addresses.
gt_dns_records_match() {
  local family=$1 records=$2 expected=$3 address
  if [[ "${ANSWER[DNS_FAMILY]}:$family" == ipv4:AAAA || "${ANSWER[DNS_FAMILY]}:$family" == ipv6:A ]]; then
    [[ -z "$records" ]]; return
  fi
  [[ -n "$records" && -n "$expected" &&
     $'\n'"$records"$'\n' != *$'\nunknown\n'* && $'\n'"$expected"$'\n' != *$'\nunknown\n'* ]] || return 1
  if [[ "$family" == A ]]; then [[ "$records" == "$expected" ]]; return; fi
  while IFS= read -r address; do
    [[ $'\n'"$expected"$'\n' == *$'\n'"$address"$'\n'* ]] || return 1
  done <<< "$records"
}

gt_plan_dns() {
  local domain=${ANSWER[DOMAIN]} family name result records expected mismatched=no matched_www=yes
  FACT[plan.names]=$domain
  FACT[dns.status]=skipped
  gt_dns_required || return 0
  if ! gt_dns_tool_available; then
    FACT[dns.status]='missing-tool'
    gt_plan_package bind9-dnsutils
    gt_plan_block 'Missing DNS check prerequisite: dig (bind9-dnsutils). Install the confirmed prerequisite, then repeat DNS checks.' \
      'Fehlende DNS-Prüfvoraussetzung: dig (bind9-dnsutils). Bestätigtes Voraussetzungspaket installieren, danach DNS erneut prüfen.'
    return 0
  fi
  for name in "$domain" "www.$domain"; do
    for family in A AAAA; do
      result=$(gt_probe dig +time=2 +tries=1 +noall +answer "$name" "$family") || result=unknown
      records=$(awk -v type="$family" '$4==type {print tolower($5)}' <<< "$result" | LC_ALL=C sort -u)
      [[ "$family" == A ]] && expected=${FACT[network.public_ipv4]:-unknown} || expected=${FACT[network.global_ipv6]:-unknown}
      if [[ "${ANSWER[DNS_FAMILY]}:$family" == ipv4:AAAA || "${ANSWER[DNS_FAMILY]}:$family" == ipv6:A ]]; then expected=''; fi
      records=$(gt_normalize_addresses <<< "$records")
      expected=$(gt_normalize_addresses <<< "$expected")
      gt_plan_row verify "DNS:$name:$family" "records=${records:-none}; expected=${expected:-none}"
      if [[ "$result" == unknown ]] || ! gt_dns_records_match "$family" "$records" "$expected"; then
        [[ "$name" == "$domain" ]] && mismatched=yes || matched_www=no
      fi
    done
  done
  [[ "$matched_www" != yes ]] || FACT[plan.names]+=" www.$domain"
  FACT[dns.status]=matched
  if [[ "$mismatched" == yes ]]; then
    FACT[dns.status]=mismatch
    if [[ "${ANSWER[TLS_SOURCE]}" == letsencrypt ]]; then
      gt_plan_block 'DNS does not match selected address families or is UNKNOWN; resolve before certbot. No DNS update was sent.' \
        'DNS passt nicht zu den gewählten Adressfamilien oder ist UNKNOWN; vor certbot klären. Kein DNS-Update gesendet.'
    else gt_plan_warn 'DNS differs or is UNKNOWN; existing-certificate deployment needs a reachability check.' \
      'DNS weicht ab oder ist UNKNOWN; Erreichbarkeit bei Verwendung des vorhandenen Zertifikats prüfen.'; fi
  fi
}

# This package-only plan authorizes no web, application or database changes.
gt_dns_tools_plan() {
  PLAN=() PLAN_BLOCKERS=() PLAN_WARNINGS=() PLAN_PACKAGES=()
  gt_system; gt_packages
  gt_plan_package bind9-dnsutils
  [[ -z "${PACKAGE[bind9-dnsutils]:-}" ]] || gt_plan_block \
    'bind9-dnsutils is installed but dig is missing from PATH; repair the package or PATH before continuing.'
  [[ "${FACT[dpkg.lock]}" == free ]] || gt_plan_block 'DNS prerequisite: package lock is held or UNKNOWN.'
  if [[ "${FACT[apt.age_hours]}" == unknown ]] || (( ${FACT[apt.age_hours]} > 24 )); then
    gt_plan_block 'DNS prerequisite: APT metadata is absent/stale; run sudo apt-get update and re-plan.'
  fi
  gt_plan_packages
  FACT[dns.tools_plan]=$(printf '%s\n' "${PLAN[@]}" | sha256sum)
  (( ${#PLAN_BLOCKERS[@]} == 0 ))
}

gt_verify_dns() {
  gt_dns_required || return 0
  PLAN=() PLAN_BLOCKERS=() PLAN_WARNINGS=() PLAN_PACKAGES=()
  gt_domain_network || { gt_core_error 'DNS check: network inventory failed.'; return 2; }
  gt_plan_dns
  gt_report_rows "$(gt_text 'DNS checks' 'DNS-Prüfungen')" "${PLAN[@]}"
  gt_report_rows "$(gt_text Warnings Hinweise)" "${PLAN_WARNINGS[@]}"
  gt_report_rows "$(gt_text Blockers Blocker)" "${PLAN_BLOCKERS[@]}"
  (( ${#PLAN_BLOCKERS[@]} == 0 )) || return 2
}

gt_prepare_dns() {
  local before reply
  gt_dns_required || return 0
  case "$MODE" in --install-core|--install-web) ;; *) return 2 ;; esac
  if ! gt_dns_tool_available; then
    gt_text 'Missing DNS check prerequisite: dig (bind9-dnsutils). Only its prerequisite transaction can proceed.' \
      'Fehlende DNS-Prüfvoraussetzung: dig (bind9-dnsutils). Zunächst ist nur diese Paketinstallation möglich.'
    if ! gt_dns_tools_plan; then gt_plan_report; return 2; fi
    gt_plan_report
    before=${FACT[dns.tools_plan]}
    if [[ "$CORE_CONFIRM" != yes ]]; then
      if [[ -z "$QUESTION_FD" ]]; then
        { exec {QUESTION_FD}<>/dev/tty; } 2>/dev/null || return 2
      fi
      printf '%s: ' "$(gt_text 'Type install-dns-tools to install this prerequisite only' \
        'install-dns-tools eingeben, um nur diese Voraussetzung zu installieren')" >&"$QUESTION_FD"
      IFS= read -r -u "$QUESTION_FD" reply && [[ "$reply" == install-dns-tools ]] || return 130
    fi
    gt_dns_tools_plan || { gt_plan_report; return 2; }
    [[ "$before" == "${FACT[dns.tools_plan]}" ]] || {
      gt_core_error 'DNS prerequisite transaction changed; review a fresh plan.'; return 2;
    }
    gt_core_run env DEBIAN_FRONTEND=noninteractive apt-get -y --no-remove --no-upgrade \
      -o DPkg::Lock::Timeout=600 install bind9-dnsutils || return 2
    gt_dns_tool_available || { gt_core_error 'dig is still unavailable after installing bind9-dnsutils.'; return 2; }
    # Subsequent plan snapshots must include the packages just installed.
    gt_system; gt_packages
  fi
  # Even successful APT does not authorize the domain plan: recollect addresses
  # and resolve DNS before the caller can confirm or execute application changes.
  gt_verify_dns
}
gt_plan_certificate() {
  local cert key permissions public_cert public_key name
  cert=$(gt_path "${ANSWER[TLS_CERT]}"); key=$(gt_path "${ANSWER[TLS_KEY]}")
  permissions=$(stat -Lc %a "$key" 2>/dev/null) || permissions=unknown
  if [[ ! -f "$cert" || ! -r "$cert" || ! -f "$key" || ! -r "$key" || ! "$permissions" =~ ^[0-7]{3,4}$ ]]; then
    gt_plan_block 'Certificate/key missing, unreadable or permissions UNKNOWN.' 'Zertifikat/Schlüssel fehlt, unlesbar oder Rechte UNKNOWN.'; return 0
  fi
  (( (8#$permissions & 077) == 0 )) || gt_plan_block 'Private key is group/world accessible.' 'Privater Schlüssel ist für Gruppe/Andere zugänglich.'
  public_cert=$(gt_probe openssl x509 -in "$cert" -pubkey -noout) || public_cert=''
  # Empty passphrase refuses encrypted keys without prompting or exposing key contents.
  public_key=$(gt_probe openssl pkey -in "$key" -passin pass: -pubout) || public_key=''
  [[ -n "$public_cert" && "$public_cert" == "$public_key" ]] || gt_plan_block 'Certificate and private key do not match or cannot be read.' 'Zertifikat und privater Schlüssel passen nicht zusammen oder sind unlesbar.'
  for name in ${FACT[plan.names]}; do
    gt_certificate_covers "$cert" "$name" || gt_plan_block "Certificate does not cover $name" "Zertifikat gilt nicht für $name"
  done
  if ! gt_probe openssl x509 -in "$cert" -noout -ext subjectAltName | grep -q 'DNS:'; then
    gt_plan_block 'Certificate has no DNS subject alternative names.' 'Zertifikat hat keine DNS-Namen in subjectAltName.'
  fi
  gt_probe openssl x509 -in "$cert" -noout -checkend 0 >/dev/null || gt_plan_block 'Certificate expired or invalid.' 'Zertifikat abgelaufen oder ungültig.'
  gt_probe openssl x509 -in "$cert" -noout -checkend 2592000 >/dev/null || gt_plan_warn 'Certificate expires within 30 days.' 'Zertifikat läuft innerhalb von 30 Tagen ab.'
  gt_probe openssl verify -purpose sslserver -untrusted "$cert" "$cert" >/dev/null || gt_plan_block 'Certificate chain cannot be verified against system trust.' 'Zertifikatskette kann nicht gegen den System-Vertrauensspeicher geprüft werden.'
  if [[ "${1:-existing}" == certbot ]]; then
    gt_plan_row reuse "${ANSWER[TLS_CERT]} / ${ANSWER[TLS_KEY]}" 'Validated Certbot certificate; renewal planned separately.'
  else
    gt_plan_row reuse "${ANSWER[TLS_CERT]} / ${ANSWER[TLS_KEY]}" 'Reference existing files; owner renews and reloads the web server. No renewal hook installed.' \
      'Vorhandene Dateien referenzieren; Eigentümer erneuert und lädt Webserver neu. Kein Erneuerungs-Hook.'
  fi
}

gt_certbot_plan() {
  local name=${ANSWER[LETSENCRYPT_CERT_NAME]:-} renewal digest permissions
  local saved_cert=${ANSWER[TLS_CERT]:-} saved_key=${ANSWER[TLS_KEY]:-}
  if [[ -z "$name" ]]; then name=${STATE[resource.certbot_selection]:-}; fi
  if [[ -z "$name" && "${STATE[resource.acme_certificate]:-}" == intent ]]; then name=-; fi
  [[ -n "$name" ]] || name=$(gt_certbot_default)
  gt_validate_answer LETSENCRYPT_CERT_NAME "$name" || {
    gt_plan_block 'Invalid Certbot lineage name.'; return 0;
  }
  FACT[tls.selection]=$name FACT[tls.renewal_hash]=''
  if [[ -n "${STATE[resource.certbot_selection]:-}" && "$name" != "${STATE[resource.certbot_selection]}" ]]; then
    gt_plan_block 'Certbot lineage selection changed; restore the confirmed selection.'; return 0
  fi
  if [[ "$name" == - ]]; then
    FACT[tls.lineage]="gt-install-${STATE[run_id]:-<installation-id>}" FACT[tls.reuse]=no
  else
    FACT[tls.lineage]=$name FACT[tls.reuse]=yes
  fi
  FACT[tls.cert]="/etc/letsencrypt/live/${FACT[tls.lineage]}/fullchain.pem"
  FACT[tls.key]="/etc/letsencrypt/live/${FACT[tls.lineage]}/privkey.pem"
  [[ "${FACT[tls.reuse]}" == yes ]] || return 0
  renewal=$(gt_path "/etc/letsencrypt/renewal/$name.conf")
  if ! gt_no_symlinks "$renewal" || [[ ! -f "$renewal" || "$(stat -c %u "$renewal")" != 0 ]]; then
    gt_plan_block 'Existing Certbot renewal configuration must be a root-owned regular file.'; return 0
  fi
  permissions=$(stat -c %a "$renewal")
  if (( (8#$permissions & 022) != 0 )); then
    gt_plan_block 'Existing Certbot renewal configuration is writable by group/others.'; return 0
  fi
  digest=$(sha256sum "$renewal"); FACT[tls.renewal_hash]=${digest%% *}
  if [[ -n "${STATE[resource.certbot_renewal_hash]:-}" &&
      "${STATE[resource.certbot_renewal_hash]}" != "${FACT[tls.renewal_hash]}" ]]; then
    gt_plan_block 'Existing Certbot renewal configuration changed; review it before resuming.'
  fi
  ANSWER[TLS_CERT]=${FACT[tls.cert]} ANSWER[TLS_KEY]=${FACT[tls.key]}
  gt_plan_certificate certbot
  ANSWER[TLS_CERT]=$saved_cert ANSWER[TLS_KEY]=$saved_key
  gt_plan_row preserve "$renewal" 'Keep renewal configuration, certificate names and existing renewal schedule.'
  gt_plan_row create 'Certbot deploy hook' 'Additional installer-owned hook, scoped to this lineage; reload selected web server.'
  gt_plan_row verify "certbot renew --cert-name $name --dry-run" 'Test the existing renewal configuration; no duplicate issuance.'
}
gt_plan_tls() {
  local web=${ANSWER[WEBSERVER]}
  case "${ANSWER[TLS_SOURCE]:-lan}" in
    letsencrypt)
      if [[ "$web" == none ]]; then gt_plan_block "Let's Encrypt requires nginx or Apache integration." "Let's Encrypt benötigt nginx- oder Apache-Integration."
      else
        gt_plan_package certbot
        gt_certbot_plan
        if [[ "${FACT[tls.reuse]:-no}" != yes ]]; then
          gt_plan_row issue "certificate:${FACT[plan.names]}" 'certbot HTTP-01, domain HTTPS redirect, enable renewal and verify renew --dry-run during installation' \
          'certbot HTTP-01, HTTPS-Umleitung für Domain, Erneuerung aktivieren und renew --dry-run bei Installation prüfen'
        fi
      fi ;;
    existing) gt_plan_certificate ;;
    proxy)
      gt_plan_row configure proxy "HTTP ${ANSWER[TLS_PROXY_LISTEN]}; allowed source=${ANSWER[TLS_PROXY_FROM]:-any}; preserve Host, X-Forwarded-For, X-Forwarded-Proto"
      [[ -n "${ANSWER[TLS_PROXY_FROM]}" ]] || gt_plan_warn 'Proxy source restriction is empty; all sources could supply forwarded headers.' 'Proxy-Quellbeschränkung ist leer; alle Quellen könnten Forwarded-Header liefern.' ;;
    lan) gt_plan_row skip tls 'LAN-only HTTP, no certificate' 'HTTP nur im LAN, kein Zertifikat' ;;
  esac
  if [[ "${ANSWER[DUCKDNS_UPDATER]:-no}" == yes ]]; then
    if [[ "${FACT[dns.duckdns]}" == yes ]]; then gt_plan_block 'An existing DuckDNS updater must not be duplicated.' 'Ein vorhandener DuckDNS-Updater darf nicht dupliziert werden.'; fi
    gt_plan_file /home/grafioschtrader/duckdns/duck.sh "DuckDNS ${ANSWER[DNS_FAMILY]}; token collected only during installation; mode 700"
    gt_plan_row modify 'crontab:grafioschtrader' 'DuckDNS every five minutes, derived minute offset; preserve existing jobs' \
      'DuckDNS alle fünf Minuten, abgeleiteter Minutenversatz; vorhandene Jobs erhalten'
  fi
}
gt_plan_application() {
  local file webports='80 443'
  gt_plan_row create user:grafioschtrader 'Home /home/grafioschtrader; disabled login password' 'Home /home/grafioschtrader; Anmeldung per Passwort gesperrt'
  for file in /etc/sudoers.d/grafioschtrader /etc/systemd/system/grafioschtrader.service /etc/logrotate.d/grafioschtrader \
      /home/grafioschtrader/gtvar.sh /home/grafioschtrader/grafioschtrader.sh; do
    gt_plan_file "$file" 'GT configuration; validated before activation' 'GT-Konfiguration; vor Aktivierung prüfen'
  done
  gt_plan_row create /var/log/grafioschtrader.log 'Preserve if present; weekly copytruncate, 8 compressed rotations' 'Erhalten falls vorhanden; wöchentlich copytruncate, 8 komprimierte Rotationen'
  gt_plan_file /root/.gt-install/secrets 'Only during installation: application secrets, excluding database root password; directory 700, file 600' \
    'Erst bei Installation: Anwendungsgeheimnisse ohne Datenbank-Root-Passwort; Verzeichnis 700, Datei 600'
  gt_plan_row clone /home/grafioschtrader/build/grafioschtrader "master; planned commit=${FACT[source.commit]}; build as grafioschtrader"
  gt_plan_row configure application.properties 'Database/mail/JWT credentials encrypted with Jasypt; admin, user limit, connector and mail keys' \
    'Datenbank/Mail/JWT-Zugangsdaten mit Jasypt verschlüsseln; Administrator, Benutzerlimit, Connector- und Mail-Schlüssel'
  gt_plan_row configure application-production.properties 'server.address=127.0.0.1; Apache also server.port; survives gtupdate' \
    'server.address=127.0.0.1; Apache zusätzlich server.port; bleibt bei gtupdate erhalten'
  if [[ "${ANSWER[TIMEZONE]}" != "${FACT[timezone]}" ]]; then gt_plan_row modify /etc/localtime "${ANSWER[TIMEZONE]}; before first cron setup"; fi
  gt_plan_row build /home/grafioschtrader/gtupdate.sh "backend from source, frontend=${FACT[frontend.mode]}; verify built commit and requirements"
  gt_plan_row enable grafioschtrader.service 'After=mariadb.service; first start runs Flyway; verify /api/gtinfo and schema collations' \
    'After=mariadb.service; erster Start führt Flyway aus; /api/gtinfo und Schema-Kollationen prüfen'
  if [[ "${ANSWER[SMTP_CONFIGURE]}" == yes ]]; then
    gt_plan_row configure mail "${ANSWER[SMTP_HOST]}:${ANSWER[SMTP_PORT]}; auth=${ANSWER[SMTP_AUTH]}; security=${ANSWER[SMTP_SECURITY]}; sender=${ANSWER[SMTP_USER]}; test=${ANSWER[SMTP_TEST]}; no message sent"
    if [[ "${ANSWER[SMTP_AUTH]}:${ANSWER[SMTP_SECURITY]}" == yes:none ]]; then
      gt_plan_block 'Authenticated SMTP requires STARTTLS or TLS.' 'SMTP mit Anmeldung benötigt STARTTLS oder TLS.'
    fi
  else gt_plan_warn 'Mail skipped: nobody can complete registration or become administrator; result would be incomplete.' \
    'Mail übersprungen: Niemand kann eine Registrierung abschließen oder Administrator werden; Ergebnis wäre unvollständig.'; fi
  if [[ "${ANSWER[FIREWALL_ALLOW]:-no}" == yes ]]; then
    [[ "${ANSWER[TLS_SOURCE]:-}" != proxy ]] || webports=${ANSWER[TLS_PROXY_LISTEN]}
    [[ -n "${ANSWER[DOMAIN]}" ]] || webports=80
    gt_plan_row modify ufw "allow TCP 22 $webports; existing rules retained"
  fi
  gt_plan_row create /var/lib/gt-install/state 'Execution only: atomic progress, planned/built commits, owned resources; re-inventory before execution' \
    'Erst bei Ausführung: atomarer Fortschritt, geplante/gebaute Commits, eigene Ressourcen; Bestand vorher erneut prüfen'
}
# Immutable answers must describe a route supported by every later stage. This
# contract contains no host-class gate, credentials or mutations, so it also
# applies to an owned installation resumed after its first application start.
gt_stage_contract() {
  local key port row label directive value name before=${#PLAN_BLOCKERS[@]} web=${ANSWER[WEBSERVER]:-}
  local -A used=()
  for key in DUCKDNS_UPDATER SWAP FIREWALL_ALLOW VHOST_INCLUDE; do
    [[ "${ANSWER[$key]:-no}" != yes ]] || gt_plan_block \
      "$key=yes is not implemented; select no before starting installation." \
      "$key=yes ist noch nicht implementiert; vor Installationsbeginn no wählen."
  done
  [[ "${ANSWER[WEBSERVER]:-}" != none ]] || gt_plan_block \
    'WEBSERVER=none is not implemented; select nginx or apache2.' \
    'WEBSERVER=none ist noch nicht implementiert; nginx oder apache2 wählen.'
  for key in BACKEND_PORT BACKEND_HTTP_PORT TLS_PROXY_LISTEN; do
    [[ "$key" != TLS_PROXY_LISTEN || "${ANSWER[TLS_SOURCE]:-}" == proxy ]] || continue
    port=${ANSWER[$key]:-}; [[ -n "$port" ]] || continue
    if [[ -n "${used[$port]:-}" ]]; then gt_plan_block "$key duplicates ${used[$port]} on port $port."; fi
    used[$port]=$key
    [[ "$port" != 80 && "$port" != 443 ]] || gt_plan_block "$key=$port overlaps the web listeners; select another port."
  done
  # A separate LAN site still needs port 80 even behind an upstream TLS proxy.
  # Later stages refresh and verify owned listeners in their own preflights.
  if [[ -n "${FACT[listeners]+set}" && "$web" != none ]]; then
    for port in 80 443; do
      [[ "$port" != 443 || -n "${ANSWER[DOMAIN]:-}" && "${ANSWER[TLS_SOURCE]:-}" != proxy ]] || continue
      if ! gt_port_free "$port" && ! awk -v port="$port" -v owner="$web" \
          '$4 ~ (":" port "$") && owner != "" && index($0,owner) {found=1} END {exit !found}' \
          <<< "${FACT[listeners]}"; then
        gt_plan_block "Web port $port belongs to another process or is UNKNOWN; co-resident proxy integration is not implemented."
      fi
    done
  fi
  # The web executor supports owned sites only. Do not persist an include choice
  # merely because the static planner can describe it.
  for row in "${WEB[@]}"; do
    read -r label directive value <<< "$row"
    case "$directive" in server_name|ServerName|ServerAlias)
      if [[ -n "${STATE[resource.web_link]:-}${STATE[resource.web_names]:-}" ]]; then
        case "${label%#*}" in
          /etc/nginx/sites-enabled/grafioschtrader|/etc/nginx/sites-enabled/grafioschtrader-domain|\
          /etc/nginx/sites-enabled/grafioschtrader-http|/etc/apache2/sites-enabled/grafioschtrader.conf|\
          /etc/apache2/sites-enabled/grafioschtrader-domain.conf|/etc/apache2/sites-enabled/grafioschtrader-http.conf)
            continue ;;
        esac
      fi
      for name in ${value//\"/}; do
        if [[ -n "${ANSWER[DOMAIN]:-}" && "$name" == "${ANSWER[DOMAIN]}" ||
              -n "${FACT[network.lan_ipv4]:-}" && "$name" == "${FACT[network.lan_ipv4]}" ]]; then
          gt_plan_block "Selected name $name belongs to a foreign vhost; snippet integration is not implemented."
        fi
      done ;;
    esac
  done
  if [[ "${ANSWER[TLS_SOURCE]:-}" == proxy ]]; then
    gt_plan_warn 'The upstream proxy must overwrite client-supplied forwarding headers and set the public protocol.' \
      'Der vorgeschaltete Proxy muss vom Client gelieferte Forwarding-Header ersetzen und das öffentliche Protokoll setzen.'
    [[ -n "${ANSWER[TLS_PROXY_FROM]:-}" ]] || gt_plan_warn \
      'TLS_PROXY_FROM is empty: login lockout cannot reliably attribute clients behind an unconfigured upstream proxy.' \
      'TLS_PROXY_FROM ist leer: Die Login-Sperre kann Clients hinter einem unkonfigurierten Proxy nicht zuverlässig zuordnen.'
  fi
  [[ "${ANSWER[SMTP_CONFIGURE]:-}:${ANSWER[SMTP_AUTH]:-}:${ANSWER[SMTP_SECURITY]:-}" != yes:yes:none ]] ||
    gt_plan_block 'Authenticated SMTP requires encryption.'
  (( ${#PLAN_BLOCKERS[@]} == before ))
}

gt_stage_preflight() {
  PLAN_BLOCKERS=()
  gt_stage_contract && return 0
  gt_report_rows "$(gt_text Blockers Blocker)" "${PLAN_BLOCKERS[@]}"
  return 2
}

gt_plan() {
  local key
  PLAN=() PLAN_BLOCKERS=() PLAN_WARNINGS=() PLAN_PACKAGES=()
  case "${FACT[host.class]}" in
    classic|completed|docker)
      gt_plan_row reuse "${FACT[host.class]}" 'Existing installation: no bootstrap actions; use its updater.' 'Vorhandene Installation: keine Bootstrap-Aktionen; zugehörigen Updater verwenden.'; return 0 ;;
    fresh) ;;
    *) gt_plan_block 'Host is not fresh; resolve existing state or installation pieces first.' 'Host ist nicht neu; vorhandenen Zustand oder Installationsteile zuerst klären.'; return 2 ;;
  esac
  gt_question_model
  for key in "${QUESTIONS[@]}"; do
    if gt_question_applies "$key" && [[ "${Q_TYPE[$key]}" != secret ]]; then
      gt_validate_answer "$key" "${ANSWER[$key]:-}" || gt_plan_block "Invalid/missing answer: $key" "Ungültige/fehlende Antwort: $key"
    elif [[ -n "${ANSWER[$key]:-}" ]]; then
      gt_plan_block "Inactive or secret answer must not enter dry-run: $key" "Inaktive oder geheime Antwort darf nicht in den Dry-run gelangen: $key"
    fi
  done
  (( ${#PLAN_BLOCKERS[@]} == 0 )) || return 2
  for key in "${!ACTION[@]}"; do
    [[ "$key" == disk || "${ACTION[$key]}" != block ]] || gt_plan_block "$key: ${REASON[$key]}"
  done
  [[ "${FACT[source.requirements]}" == remote ]] || gt_plan_block 'Source requirements are provisional; no executable plan until source lookup succeeds.' \
    'Quellcode-Anforderungen sind vorläufig; kein ausführbarer Plan ohne erfolgreiche Quellcode-Abfrage.'
  [[ "${FACT[dpkg.lock]}" == free ]] || gt_plan_block 'Package lock is held or UNKNOWN.' 'Paketsperre ist belegt oder UNKNOWN.'
  if [[ "${FACT[apt.age_hours]}" == unknown ]] || (( ${FACT[apt.age_hours]} > 24 )); then
    gt_plan_block 'APT metadata is absent/stale; refresh and re-plan before installation.' 'APT-Metadaten fehlen/sind veraltet; vor Installation aktualisieren und neu planen.'
  fi
  gt_stage_contract || true
  gt_plan_toolchains; gt_plan_database; gt_plan_ports; gt_plan_dns; gt_plan_web; gt_plan_storage; gt_plan_tls; gt_plan_application; gt_plan_packages
  (( ${#PLAN_BLOCKERS[@]} == 0 )) || return 2
}
gt_plan_report() {
  local key row
  gt_text 'Installation plan — no installation changes made' 'Installationsplan — keine Installationsänderungen vorgenommen'
  for key in "${QUESTIONS[@]}"; do
    [[ "${Q_TYPE[$key]}" != secret && -n "${ANSWER[$key]+present}" ]] || continue
    printf '%s=%s\n' "$key" "$(gt_safe "${ANSWER[$key]}")"
  done
  if [[ "${FACT[host.class]}" == fresh ]]; then
    gt_text 'Required secrets (values omitted)' 'Erforderliche Geheimnisse (Werte ausgeblendet)'
    for key in "${QUESTIONS[@]}"; do
      [[ "${Q_TYPE[$key]}" == secret ]] || continue
      gt_question_applies "$key" || continue
      printf '%s | %s | %s\n' "$key" "$(gt_text "${Q_EN[$key]}" "${Q_DE[$key]}")" "${SECRET_STATUS[$key]:-required}"
    done
    printf 'JWT_SECRET | g.jwt.secret | %s\n' "${SECRET_STATUS[JWT_SECRET]:-automatic during preparation}"
  fi
  gt_report_rows "$(gt_text 'Planned actions (subject to blockers)' 'Geplante Aktionen (abhängig von Blockern)')" "${PLAN[@]}"
  gt_report_rows "$(gt_text 'Disk requirements' 'Speicherplatzbedarf')" "${DISKS[@]}"
  gt_report_rows "$(gt_text Warnings Hinweise)" "${PLAN_WARNINGS[@]}"
  gt_report_rows "$(gt_text Blockers Blocker)" "${PLAN_BLOCKERS[@]}"
  printf '%s: %s\n' "$(gt_text 'Blocking findings' 'Blockierende Befunde')" "${#PLAN_BLOCKERS[@]}"
  gt_text 'No installation was executed. Credentials and live host state must be verified again before execution.' \
    'Keine Installation ausgeführt. Zugangsdaten und aktueller Host-Zustand müssen vor Ausführung erneut geprüft werden.'
}
gt_dry_run() {
  local status=0
  gt_completed || status=$?
  (( status == 3 )) || return "$status"
  status=0
  gt_inventory; gt_compatibility; gt_report
  if [[ "${FACT[host.class]}" == fresh ]]; then
    if ! { exec {QUESTION_FD}<>/dev/tty; } 2>/dev/null; then
      gt_text 'Dry-run requires a terminal for questions; use --check for unattended inventory.' \
        'Dry-run benötigt ein Terminal für Fragen; --check für unbeaufsichtigte Bestandsaufnahme verwenden.' >&2
      return 2
    fi
    QUESTION_OUTPUT=$QUESTION_FD
    gt_questions || return $?
  fi
  gt_plan || status=$?
  gt_plan_report
  return "$status"
}

gt_prepare() {
  local status=0
  gt_completed || status=$?
  (( status == 3 )) || return "$status"
  status=0
  gt_inventory; gt_compatibility; gt_report
  gt_question_model
  if [[ "${FACT[host.class]}" == fresh ]]; then
    if [[ -n "$ANSWERS_FILE" ]]; then
      gt_answers_file "$ANSWERS_FILE" || return $?
    else
      if ! { exec {QUESTION_FD}<>/dev/tty; } 2>/dev/null; then
        gt_text 'Preparation needs a terminal or --answers FILE.' 'Vorbereitung benötigt ein Terminal oder --answers DATEI.' >&2
        return 2
      fi
      QUESTION_OUTPUT=$QUESTION_FD
      gt_text 'Preparation only: secrets are discarded on exit; nothing will be installed.' \
        'Nur Vorbereitung: Geheimnisse werden beim Beenden verworfen; es wird nichts installiert.' >&"$QUESTION_OUTPUT"
    fi
    gt_prepare_root || return $?
    if [[ -n "$ANSWERS_FILE" ]]; then gt_file_questions || return $?
    else gt_questions || return $?; fi
    gt_prepare_secrets || return $?
  fi
  gt_plan || status=$?
  gt_plan_report
  gt_text 'Preparation ends here. Collected/generated secrets are discarded; the supplied answers file is unchanged.' \
    'Vorbereitung endet hier. Erfasste/erzeugte Geheimnisse werden verworfen; die übergebene Antwortdatei bleibt unverändert.'
  return "$status"
}
gt_core_error() {
  printf '%s: %s\n' "$(gt_text 'Installation core stopped' 'Installationskern angehalten')" "$1" >&2
  return 2
}

# Every parent is checked before creating state or following a managed path. State never
# grants permission to adopt a symlink or a file edited after the last journal entry.
gt_no_symlinks() {
  local path=$1
  while [[ "$path" != / && -n "$path" ]]; do
    [[ ! -L "$path" ]] || return 1
    path=${path%/*}
  done
}

gt_private_dir() {
  local path=$1
  gt_no_symlinks "$path" || return 2
  if [[ ! -e "$path" ]]; then mkdir -m 700 -- "$path" || return 2; fi
  [[ -d "$path" && "$(stat -c '%u:%a' "$path")" == "$EUID:700" ]]
}

gt_private_read() {
  # Read once from the checked descriptor. NUL is an error, not a silently removed byte.
  local file=$1 fd before after
  PRIVATE_CONTENT=''
  gt_no_symlinks "$file" && [[ -f "$file" ]] || return 2
  before=$(stat -c '%u:%a:%d:%i' "$file") || return 2
  [[ "$before" == "$EUID:600:"* ]] || return 2
  exec {fd}<"$file" || return 2
  after=$(stat -Lc '%u:%a:%d:%i' "/dev/fd/$fd")
  if [[ "$before" != "$after" ]] || IFS= read -r -d '' PRIVATE_CONTENT <&"$fd"; then
    exec {fd}<&-; PRIVATE_CONTENT=''; return 2
  fi
  exec {fd}<&-
}

gt_atomic_map() {
  local file=$1 name=$2 temporary key
  local -n values=$name
  gt_no_symlinks "$file" || return 2
  temporary=$(umask 077; mktemp "${file}.XXXXXX") || return 2
  PRIVATE_FILES+=("$temporary")
  for key in "${!values[@]}"; do
    if [[ "$key" == *[$'\001'-$'\037'$'\177']* || "${values[$key]}" == *[$'\001'-$'\037'$'\177']* ]]; then
      rm -f -- "$temporary"; return 2
    fi
    printf '%s=%s\n' "$key" "${values[$key]}" >> "$temporary" || { rm -f -- "$temporary"; return 2; }
  done
  # A completed write-ahead entry must survive a host/VM power loss. Rename is
  # atomic for readers but does not itself flush either file data or directory metadata.
  if ! chmod 600 "$temporary" || ! sync -f "$temporary" || ! mv -T -- "$temporary" "$file"; then
    rm -f -- "$temporary"; return 2
  fi
  sync -f "${file%/*}"
}

gt_state_save() {
  gt_result_remember_warnings || return 1
  gt_atomic_map "$(gt_path /var/lib/gt-install/state)" STATE
}

gt_state_load() {
  local line key value
  STATE=() ANSWER=()
  [[ "$(stat -c '%u:%a' "$(gt_path /var/lib/gt-install)" 2>/dev/null)" == "$EUID:700" ]] || return 2
  gt_private_read "$(gt_path /var/lib/gt-install/state)" || return 2
  while IFS= read -r line; do
    [[ -n "$line" ]] || continue
    key=${line%%=*}; value=${line#*=}
    [[ "$line" == *=* && "$key" =~ ^[a-zA-Z0-9_.+-]+$ && -z "${STATE[$key]+set}" && "$value" != *[$'\001'-$'\037'$'\177']* ]] || return 2
    case "$key" in
      schema|status|scope|run_id|planned_commit|java_home|maven|new_database_server|database_before|account_before|root_auth|step.*|resource.*|file.*) ;;
      built_commit) [[ "$value" =~ ^[a-f0-9]{40}$ ]] || return 2 ;;
      installer_sha256) [[ "$value" =~ ^[a-f0-9]{64}$ ]] || return 2 ;;
      completed_at) [[ "$value" =~ ^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}Z$ ]] || return 2 ;;
      toolchain.java.package) [[ "$value" == none || "$value" =~ ^openjdk-[0-9]+-jdk-headless$ ]] || return 2 ;;
      toolchain.maven.package) [[ "$value" == none || "$value" == maven ]] || return 2 ;;
      toolchain.java.version|toolchain.maven.version) [[ "$value" =~ ^[a-zA-Z0-9.+:~_-]+$ ]] || return 2 ;;
      toolchain.alternatives) [[ "$value" == saved ]] || return 2 ;;
      alternative.*) [[ "${key#alternative.}" =~ ^[a-zA-Z0-9_.+-]+$ && "$value" == /* ]] || return 2 ;;
      build.*) gt_build_field "${key#build.}" "$value" || return 2 ;;
      answer.*) gt_validate_answer "${key#answer.}" "$value" || return 2; ANSWER[${key#answer.}]=$value ;;
      *) return 2 ;;
    esac
    STATE[$key]=$value
  done <<< "$PRIVATE_CONTENT"
  PRIVATE_CONTENT=''
  [[ "${STATE[schema]:-}:${STATE[scope]:-}" == 1:core &&
      "${STATE[status]:-}" =~ ^(running|complete)$ &&
      "${STATE[run_id]:-}" =~ ^[a-f0-9]{32}$ && "${STATE[planned_commit]:-}" =~ ^[a-f0-9]{40}$ ]] || return 2
  for key in java_home maven; do
    if [[ "${STATE[$key]:-}" == pending ]]; then
      [[ "${STATE[step.toolchains]:-}" == pending || "${STATE[step.toolchains]:-}" == running ]] || return 2
    else gt_valid_path "${STATE[$key]:-}" || return 2; fi
  done
  if [[ -n "${STATE[step.toolchains]:-}" ]]; then
    [[ "${STATE[step.toolchains]}" =~ ^(pending|running|complete)$ ]] || return 2
    for key in java maven; do
      [[ -n "${STATE[toolchain.$key.package]:-}" && -n "${STATE[toolchain.$key.version]:-}" ]] || return 2
    done
  fi
  for key in new_database_server database_before account_before; do
    [[ "${STATE[$key]:-}" == yes || "${STATE[$key]:-}" == no ]] || return 2
  done
  if [[ "${STATE[status]}" == complete ]]; then
    gt_completion_valid || return 2
  else
    [[ -z "${STATE[completed_at]:-}" ]] || return 2
  fi
}

# The local map is consumed by gt_atomic_map through its nameref.
# shellcheck disable=SC2034
gt_secrets_save() {
  local key
  local -A persisted=([INSTALL_ID]="${STATE[run_id]}")
  for key in DB_PASSWORD JASYPT_PASSWORD JWT_SECRET SMTP_PASSWORD DUCKDNS_TOKEN; do
    [[ -z "${SECRET[$key]+set}" ]] || persisted[$key]=${SECRET[$key]}
  done
  gt_atomic_map "$(gt_path /root/.gt-install/secrets)" persisted
}

gt_secrets_load() {
  local line key value id=''
  local -A loaded=()
  [[ "$(stat -c '%u:%a' "$(gt_path /root/.gt-install)" 2>/dev/null)" == "$EUID:700" ]] || return 2
  gt_private_read "$(gt_path /root/.gt-install/secrets)" || return 2
  while IFS= read -r line; do
    [[ -n "$line" ]] || continue
    key=${line%%=*}; value=${line#*=}
    [[ "$line" == *=* ]] || return 2
    case "$key" in
      INSTALL_ID) [[ -z "$id" ]] || return 2; id=$value; continue ;;
      DB_PASSWORD|JASYPT_PASSWORD|JWT_SECRET|SMTP_PASSWORD|DUCKDNS_TOKEN) ;;
      *) return 2 ;;
    esac
    [[ -z "${loaded[$key]+set}" ]] && gt_valid_secret "$value" || return 2
    loaded[$key]=$value
  done <<< "$PRIVATE_CONTENT"
  PRIVATE_CONTENT=''
  [[ "$id" == "${STATE[run_id]}" && "${loaded[JWT_SECRET]:-}" =~ ^[a-zA-Z0-9]{48}$ ]] || return 2
  for key in DB_PASSWORD JASYPT_PASSWORD SMTP_PASSWORD DUCKDNS_TOKEN; do
    if gt_question_applies "$key"; then gt_valid_secret "${loaded[$key]:-}" || return 2
    else [[ -z "${loaded[$key]+set}" ]] || return 2; fi
  done
  SECRET=()
  for key in "${!loaded[@]}"; do SECRET[$key]=${loaded[$key]}; done
}
gt_core_begin() {
  local key
  gt_private_dir "$(gt_path /var/lib/gt-install)" && gt_private_dir "$(gt_path /root/.gt-install)" || return 2
  [[ ! -e "$(gt_path /root/.gt-install/secrets)" && ! -e "$(gt_path /var/lib/gt-install/state)" ]] || return 2
  STATE=([schema]=1 [status]=running [scope]=core [planned_commit]="${FACT[source.commit]}"
    [java_home]="${FACT[toolchain.java.path]:-${FACT[java.suitable]}}" [maven]="${FACT[toolchain.maven.path]:-${FACT[maven.path]}}"
    [new_database_server]=no [database_before]=no [account_before]=no)
  STATE[run_id]=$(openssl rand -hex 16) || return 2
  [[ "${FACT[database.vendor]}" != absent ]] || STATE[new_database_server]=yes
  [[ "${FACT[database.gt_tables]}" != 0 ]] || STATE[database_before]=yes
  [[ "${FACT[database.gt_user]}" != present ]] || STATE[account_before]=yes
  if [[ -n "${FACT[toolchain.java.path]:-}" ]]; then
    STATE[step.toolchains]=pending
    for key in java maven; do
      STATE[toolchain.$key.package]=${FACT[toolchain.$key.package]}
      STATE[toolchain.$key.version]=${FACT[toolchain.$key.version]}
    done
  fi
  for key in "${!ANSWER[@]}"; do STATE[answer.$key]=${ANSWER[$key]}; done
  # A crash between these writes leaves a journal with missing secrets: recovery must stop,
  # never invent new passwords for resources which could already depend on them.
  gt_state_save && gt_secrets_save
}

gt_core_mark() { STATE[$1]=$2; gt_state_save; }

gt_core_run() {
  # Only non-secret commands use this channel. SQL and Maven output use private captures.
  "$@"
}

gt_core_base_packages() {
  local package transaction line
  local -a base_missing=()
  gt_packages
  [[ "${FACT[packages]}" == known ]] || {
    gt_core_error 'Base package inventory failed; no APT transaction started.'; return 2;
  }
  while IFS= read -r package; do
    [[ -n "${PACKAGE[$package]:-}" ]] || base_missing+=("$package")
  done < <(gt_base_package_names)
  if (( ${#base_missing[@]} )); then
    [[ "${STATE[step.base_packages]:-}" != complete ]] || {
      gt_core_error 'Previously verified base packages are missing; restore them before resuming.'; return 2;
    }
    transaction=$(gt_probe env LC_ALL=C apt-get --simulate \
      -o Dir::Cache::pkgcache= -o Dir::Cache::srcpkgcache= install "${base_missing[@]}") || return 2
    while IFS= read -r line; do
      if [[ "$line" == 'Remv '* || "$line" =~ ^Inst\ [^\ ]+\ \[ ]]; then
        gt_core_error 'Base package transaction would remove or upgrade existing packages.'; return 2
      fi
    done <<< "$transaction"
    gt_core_mark step.base_packages running || return 2
    gt_core_run env DEBIAN_FRONTEND=noninteractive apt-get -y --no-remove --no-upgrade \
      -o DPkg::Lock::Timeout=600 install "${base_missing[@]}" || return 2
    gt_packages
    [[ "${FACT[packages]}" == known ]] || return 2
    for package in "${base_missing[@]}"; do
      [[ -n "${PACKAGE[$package]:-}" ]] || {
        gt_core_error "Base package still missing after APT: $package"; return 2;
      }
    done
  fi
  gt_core_mark step.base_packages complete
}

gt_as_app() {
  local build_path=''
  [[ -z "${STATE[build.node_home]:-}" ]] || build_path="${STATE[build.node_home]}/bin:${STATE[build.prefix]}/bin:"
  runuser -u grafioschtrader -- env -u JAVA_TOOL_OPTIONS -u JDK_JAVA_OPTIONS -u _JAVA_OPTIONS \
    -u MAVEN_OPTS -u MAVEN_ARGS -u NODE_OPTIONS -u NODE_PATH HOME="$CORE_HOME" MAVEN_SKIP_RC=1 GIT_TERMINAL_PROMPT=0 \
    NG_CLI_ANALYTICS=false npm_config_prefix="${STATE[build.prefix]:-/usr/local}" \
    JAVA_HOME="${STATE[java_home]}" PATH="${build_path}${STATE[java_home]}/bin:${STATE[maven]%/*}:/usr/local/bin:/usr/bin:/bin" "$@"
}

gt_core_user() {
  local entry _name _password uid _gid description home shell
  if entry=$(getent passwd grafioschtrader); then
    IFS=: read -r _name _password uid _gid description home shell <<< "$entry"
    [[ "${STATE[resource.user]:-}" == intent || "${STATE[resource.user]:-}" == owned ]] || return 2
    [[ "$description" == "GT installer ${STATE[run_id]}" && "$home" == "$CORE_HOME" && "$uid" != 0 && "$shell" == /bin/bash ]] || return 2
  else
    [[ "${STATE[resource.user]:-}" != owned ]] || return 2
    [[ ! -e "$CORE_HOME" && ! -L "$CORE_HOME" ]] && ! getent group grafioschtrader >/dev/null || return 2
    gt_core_mark resource.user intent || return 2
    gt_core_run useradd --create-home --user-group --shell /bin/bash --comment "GT installer ${STATE[run_id]}" grafioschtrader || return 2
  fi
  gt_no_symlinks "$CORE_HOME" || return 2
  [[ "$(stat -c %U "$CORE_HOME")" == grafioschtrader ]] || return 2
  [[ "$(passwd -S grafioschtrader | awk '{print $2}')" == L ]] || return 2
  gt_core_mark resource.user owned
}

gt_core_clone() {
  local stage="$CORE_HOME/build/.gt-source-${STATE[run_id]}" remote commit
  gt_no_symlinks "$CORE_REPO" && gt_no_symlinks "$stage" || return 2
  if [[ -e "$CORE_REPO" ]]; then
    [[ "${STATE[resource.clone]:-}" == intent || "${STATE[resource.clone]:-}" == owned ]] || return 2
  else
    gt_core_mark resource.clone intent || return 2
    gt_as_app mkdir -p "$CORE_HOME/build" || return 2
    if [[ ! -e "$stage" ]]; then gt_as_app git init -q "$stage" || return 2; fi
    remote=$(gt_as_app git -C "$stage" remote get-url origin 2>/dev/null) || remote=''
    if [[ -z "$remote" ]]; then gt_as_app git -C "$stage" remote add origin "$CORE_REMOTE" || return 2
    else [[ "$remote" == "$CORE_REMOTE" ]] || return 2; fi
    gt_as_app git -C "$stage" fetch -q --depth=1 origin "${STATE[planned_commit]}" || return 2
    if gt_as_app git -C "$stage" show-ref --verify --quiet refs/heads/master; then
      [[ "$(gt_as_app git -C "$stage" rev-parse HEAD)" == "${STATE[planned_commit]}" ]] || return 2
    else gt_as_app git -C "$stage" checkout -q -b master FETCH_HEAD || return 2; fi
    gt_as_app mv -T "$stage" "$CORE_REPO" || return 2
  fi
  remote=$(gt_as_app git -C "$CORE_REPO" remote get-url origin) || return 2
  commit=$(gt_as_app git -C "$CORE_REPO" rev-parse HEAD) || return 2
  [[ "$remote" == "$CORE_REMOTE" && "$commit" == "${STATE[planned_commit]}" ]] || return 2
  gt_core_mark resource.clone owned
}

gt_properties_escape() {
  local value=$1
  value=${value//\\/\\\\}; value=${value// /\\ }
  printf '%s' "$value"
}

gt_properties_render() {
  local input=$1 output=$2 allow_new=${3:-no} line key
  local -A seen=()
  : > "$output" || return 2
  while IFS= read -r line || [[ -n "$line" ]]; do
    line=${line%$'\r'}
    if [[ "$line" =~ ^[[:space:]]*([#!][[:space:]]*)?([^=]+)= ]]; then
      key=${BASH_REMATCH[2]}; key="${key#"${key%%[![:space:]]*}"}"; key="${key%"${key##*[![:space:]]}"}"
      if [[ -n "${PROPERTIES[$key]+set}" ]]; then
        [[ "$line" != *'!'* && -z "${seen[$key]:-}" ]] || return 2
        seen[$key]=yes
        printf '%s=%s\n' "$key" "$(gt_properties_escape "${PROPERTIES[$key]}")" >> "$output"
        continue
      fi
    fi
    printf '%s\n' "$line" >> "$output"
  done < "$input"
  for key in "${!PROPERTIES[@]}"; do
    [[ -z "${seen[$key]:-}" ]] || continue
    [[ "$allow_new" == yes ]] || return 2
    printf '%s=%s\n' "$key" "$(gt_properties_escape "${PROPERTIES[$key]}")" >> "$output"
  done
}

gt_core_publish() {
  local id=$1 input=$2 target=$3 mode=$4 original=${5:-absent} digest current temporary
  gt_no_symlinks "$target" || return 2
  digest=$(sha256sum "$input"); digest=${digest%% *}
  if [[ -e "$target" ]]; then
    [[ -f "$target" ]] || return 2
    current=$(sha256sum "$target"); current=${current%% *}
    [[ "$current" == "${STATE[file.$id]:-$original}" || "$current" == "${STATE[file.$id.previous]:-$original}" ]] || return 2
    if [[ "$current" == "$digest" && "${STATE[file.$id]:-}" == "$digest" && "$(stat -c '%U:%a' "$target")" == "grafioschtrader:$mode" ]]; then
      return 0
    fi
  fi
  STATE[file.$id.previous]=${current:-absent}
  gt_core_mark "file.$id" "$digest" || return 2
  temporary=$(mktemp "${target}.gt-install.XXXXXX") || return 2
  PRIVATE_FILES+=("$temporary")
  cat "$input" > "$temporary" && chmod "$mode" "$temporary" && chown grafioschtrader:grafioschtrader "$temporary" &&
    mv -T "$temporary" "$target"
}

gt_sql_literal() {
  # All mutating batches explicitly select NO_BACKSLASH_ESCAPES. Only quotes need doubling.
  local value=${1//\'/\'\'}
  printf "'%s'" "$value"
}

gt_core_sql() {
  local client options status=0
  client=$(command -v mariadb) || return 2
  options=$(gt_db_options DB_ROOT_PASSWORD root) || return 2
  # Caller supplies stdin. Neither SQL nor client errors can enter public logs or argv.
  "$client" "--defaults-file=$options" --protocol=SOCKET --user=root --batch --skip-column-names \
    --connect-timeout=4 2>/dev/null || status=$?
  rm -f -- "$options"
  return "$status"
}

gt_core_login() {
  local key=$1 user=$2 protocol=$3 identity=${4:-root} file dir value status=0
  local -a command=(mariadb)
  if [[ "$identity" == app ]]; then
    dir=$(mktemp -d /tmp/gt-dbcheck.XXXXXX) || return 2
    PRIVATE_DIRS+=("$dir")
    file=$(gt_db_options "$key" "$user") || return 2
    mv "$file" "$dir/client.cnf" && chown -R grafioschtrader:grafioschtrader "$dir" || return 2
    file="$dir/client.cnf"; command=(runuser -u grafioschtrader -- mariadb)
  else file=$(gt_db_options "$key" "$user") || return 2; fi
  command+=("--defaults-file=$file" "--protocol=$protocol" "--user=$user" --batch --skip-column-names --connect-timeout=4)
  [[ "$protocol" != TCP ]] || command+=(--host=127.0.0.1 --port=3306)
  value=$(printf 'SELECT CURRENT_USER();\n' | "${command[@]}" 2>/dev/null) || status=$?
  rm -f -- "$file"
  [[ -z "${dir:-}" ]] || rmdir "$dir"
  (( status == 0 )) && [[ "$value" == "$user@localhost" ]]
}

gt_core_packages() {
  local transaction line
  [[ "${STATE[new_database_server]}" == yes ]] || return 0
  if dpkg-query -W -f='${db:Status-Status}' mariadb-server 2>/dev/null | grep -qx installed; then
    [[ "${STATE[resource.mariadb]:-}" == intent || "${STATE[resource.mariadb]:-}" == owned ]] || return 2
  else
    [[ "${STATE[resource.mariadb]:-}" != owned ]] || return 2
    transaction=$(LC_ALL=C apt-get --simulate install mariadb-server mariadb-client 2>/dev/null) || return 2
    while IFS= read -r line; do
      [[ "$line" != 'Remv '* && ! "$line" =~ ^Inst\ [^\ ]+\ \[ ]] || return 2
    done <<< "$transaction"
    gt_core_mark resource.mariadb intent || return 2
    # A failed transaction stays resumable; do not automatically upgrade/remove existing packages.
    gt_core_run env DEBIAN_FRONTEND=noninteractive apt-get -y --no-remove --no-upgrade \
      -o DPkg::Lock::Timeout=600 install mariadb-server mariadb-client || return 2
  fi
  gt_core_mark resource.mariadb owned || return 2
  gt_core_run systemctl start mariadb.service
}

gt_core_root_auth() {
  local mode wrong saved
  [[ "${STATE[new_database_server]}" == yes ]] || return 0
  # Authenticate under the fresh, disabled-login service identity: Linux root's socket
  # privilege must not make an incorrect password look valid.
  if ! gt_core_login DB_ROOT_PASSWORD root SOCKET app; then
    [[ "${STATE[root_auth]:-}" != verified ]] || return 2
    mode=$(gt_core_sql <<'SQL'
SELECT CASE
 WHEN JSON_VALUE(Priv,'$.plugin')='mysql_native_password'
  AND JSON_VALUE(Priv,'$.authentication_string')='invalid'
  AND JSON_SEARCH(Priv,'one','unix_socket') IS NOT NULL THEN 'dual-unset'
 WHEN JSON_VALUE(Priv,'$.plugin')='unix_socket' AND JSON_EXTRACT(Priv,'$.auth_or') IS NULL THEN 'socket-only'
 ELSE 'configured' END FROM mysql.global_priv WHERE User='root' AND Host='localhost';
SQL
    ) || return 2
    [[ "$mode" == dual-unset || "$mode" == socket-only ]] || return 2
    gt_core_mark root_auth intent || return 2
    if [[ "$mode" == dual-unset ]]; then
      { printf "SET SESSION sql_mode='NO_BACKSLASH_ESCAPES';\nSET PASSWORD FOR 'root'@'localhost'=PASSWORD("
        gt_sql_literal "${SECRET[DB_ROOT_PASSWORD]}"; printf ');\n'; } | gt_core_sql >/dev/null || return 2
    else
      { printf "SET SESSION sql_mode='NO_BACKSLASH_ESCAPES';\nALTER USER 'root'@'localhost' IDENTIFIED VIA unix_socket OR mysql_native_password USING PASSWORD("
        gt_sql_literal "${SECRET[DB_ROOT_PASSWORD]}"; printf ');\n'; } | gt_core_sql >/dev/null || return 2
    fi
    gt_core_login DB_ROOT_PASSWORD root SOCKET app || return 2
  fi
  saved=${SECRET[DB_ROOT_PASSWORD]}
  wrong=$(openssl rand -hex 32) || return 2
  SECRET[DB_ROOT_PASSWORD]=$wrong
  if gt_core_login DB_ROOT_PASSWORD root SOCKET app; then SECRET[DB_ROOT_PASSWORD]=$saved; return 2; fi
  SECRET[DB_ROOT_PASSWORD]=''
  if ! gt_core_login DB_ROOT_PASSWORD root SOCKET; then SECRET[DB_ROOT_PASSWORD]=$saved; return 2; fi
  SECRET[DB_ROOT_PASSWORD]=$saved
  gt_core_mark root_auth verified
}

gt_core_database() {
  local result accounts host pool=384M mem=${FACT[memory.MemTotal]:-0} file
  gt_core_packages || return 2
  gt_core_root_auth || return 2
  result=$(printf "SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA='grafioschtrader';\n" | gt_core_sql) || return 2
  [[ "$result" == 0 ]] || return 2 # Never modify or adopt nonempty data, even on resumption.
  result=$(printf "SELECT DEFAULT_CHARACTER_SET_NAME,DEFAULT_COLLATION_NAME FROM information_schema.SCHEMATA WHERE SCHEMA_NAME='grafioschtrader';\n" | gt_core_sql) || return 2
  if [[ -n "$result" ]]; then
    [[ "$result" == $'utf8mb4\tutf8mb4_general_ci' ]] || return 2
    [[ "${STATE[database_before]}" == yes && "${ANSWER[DB_REUSE_EMPTY]:-}" == yes || "${STATE[resource.database]:-}" == intent || "${STATE[resource.database]:-}" == owned ]] || return 2
  else
    [[ "${STATE[database_before]}" == no && "${STATE[resource.database]:-}" != owned ]] || return 2
    gt_core_mark resource.database intent || return 2
    printf 'CREATE DATABASE grafioschtrader CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;\n' | gt_core_sql >/dev/null || return 2
  fi
  if [[ "${STATE[database_before]}" == no ]]; then gt_core_mark resource.database owned || return 2; fi
  result=$(printf "SELECT COUNT(*) FROM mysql.user WHERE User='grafioschtrader' AND Host='localhost';\n" | gt_core_sql) || return 2
  if [[ "$result" == 1 ]]; then
    [[ "${STATE[account_before]}" == yes || "${STATE[resource.account]:-}" == intent || "${STATE[resource.account]:-}" == owned ]] || return 2
    gt_core_login DB_PASSWORD grafioschtrader TCP || return 2
  elif [[ "$result" == 0 ]]; then
    [[ "${STATE[account_before]}" == no && "${STATE[resource.account]:-}" != owned ]] || return 2
    gt_core_mark resource.account intent || return 2
    { printf "SET SESSION sql_mode='NO_BACKSLASH_ESCAPES';\nCREATE USER 'grafioschtrader'@'localhost' IDENTIFIED BY "
      gt_sql_literal "${SECRET[DB_PASSWORD]}"; printf ';\n'; } | gt_core_sql >/dev/null || return 2
  else return 2; fi
  if [[ "${STATE[account_before]}" == no ]]; then
    printf "GRANT ALL PRIVILEGES ON grafioschtrader.* TO 'grafioschtrader'@'localhost';\n" | gt_core_sql >/dev/null || return 2
    gt_core_mark resource.account owned || return 2
  fi
  gt_core_login DB_PASSWORD grafioschtrader TCP || return 2
  result=$(printf "SHOW GRANTS FOR 'grafioschtrader'@'localhost';\n" | gt_core_sql) || return 2
  # shellcheck disable=SC2016
  [[ "$result" == *'GRANT ALL PRIVILEGES ON `grafioschtrader`.* TO '* ]] || return 2
  if [[ "${STATE[new_database_server]}" == yes ]]; then
    accounts=$(printf "SELECT Host FROM mysql.user WHERE User='';\n" | gt_core_sql) || return 2
    result=$(printf "SELECT COUNT(*) FROM information_schema.SCHEMATA WHERE SCHEMA_NAME='test';\n" | gt_core_sql) || return 2
    if [[ "${STATE[step.hardening]:-}" == complete ]]; then
      [[ -z "$accounts" && "$result" == 0 ]] || return 2
    else
    while IFS= read -r host; do
      [[ -n "$host" ]] || continue
      { printf "SET SESSION sql_mode='NO_BACKSLASH_ESCAPES';\nDROP USER ''@"; gt_sql_literal "$host"; printf ';\n'; } | gt_core_sql >/dev/null || return 2
    done <<< "$accounts"
    printf 'DROP DATABASE IF EXISTS test;\n' | gt_core_sql >/dev/null || return 2
    gt_core_mark step.hardening complete || return 2
    fi
  fi
  if [[ "${ANSWER[BUFFER_POOL]:-no}" == yes ]]; then
    if (( mem >= 6000 )); then pool=2G; elif (( mem >= 3000 )); then pool=1G; fi
    file=/etc/mysql/mariadb.conf.d/60-grafioschtrader.cnf
    gt_no_symlinks "$file" || return 2
    printf '[mysqld]\ninnodb_buffer_pool_size=%s\n' "$pool" > "$SCRATCH/buffer.cnf"
    result=$(sha256sum "$SCRATCH/buffer.cnf"); result=${result%% *}
    if [[ -e "$file" ]]; then
      [[ "${STATE[file.buffer]:-}" == "$result" ]] && cmp -s "$file" "$SCRATCH/buffer.cnf" || return 2
    else
      gt_core_mark file.buffer "$result" || return 2
      install -m 644 "$SCRATCH/buffer.cnf" "$file" || return 2
    fi
    result=$(printf 'SELECT @@innodb_buffer_pool_size;\n' | gt_core_sql) || return 2
    case "$pool" in 2G) mem=2147483648 ;; 1G) mem=1073741824 ;; *) mem=402653184 ;; esac
    [[ "$result" == "$mem" ]] || gt_core_run systemctl restart mariadb.service || return 2
    gt_core_login DB_PASSWORD grafioschtrader TCP || return 2
  fi
  gt_core_mark step.database complete
}

gt_jasypt_call() (
  set +vx
  local goal=$1 directory=$2 marker=$3
  # File goals process literal bytes; Maven's value parameter can interpolate ${...}.
  # Only the key enters this child's environment; no plaintext enters command arguments.
  export JASYPT_ENCRYPTOR_PASSWORD="${SECRET[JASYPT_PASSWORD]}"
  # shellcheck disable=SC2016
  gt_as_app bash -c 'cd "$1" && shift && exec "$@"' gt-jasypt \
    "$CORE_REPO/backend/grafioschtrader-server" "${STATE[maven]}" -B -ntp \
    -Dstyle.color=never "-Djasypt.plugin.path=file:$directory/value.properties" \
    "-Djasypt.plugin.decrypt.prefix=${marker}_BEGIN" "-Djasypt.plugin.decrypt.suffix=${marker}_END" "jasypt:$goal"
)

gt_encrypt_secret() {
  local key=$1 directory output marker encrypted
  directory=$(mktemp -d /tmp/gt-crypto.XXXXXX) || return 2
  PRIVATE_DIRS+=("$directory")
  marker=$(openssl rand -hex 24) || return 2
  [[ "${SECRET[$key]}" != *"$marker"* ]] || return 2
  printf '%s_BEGIN%s%s_END\n' "$marker" "${SECRET[$key]}" "$marker" > "$directory/value.properties"
  chmod 600 "$directory/value.properties" && chown -R grafioschtrader:grafioschtrader "$directory" || return 2
  # Capture all diagnostics privately, including plaintext the plugin may emit on error/debug.
  output=$(gt_jasypt_call encrypt "$directory" "$marker" 2>&1) || { gt_core_error "Jasypt encryption failed ($key); plugin output suppressed."; return 2; }
  encrypted=$(cat "$directory/value.properties")
  [[ "$encrypted" =~ ^ENC\([A-Za-z0-9+/=]+\)$ ]] || { gt_core_error "Jasypt returned no unique ciphertext ($key)."; return 2; }
  output=$(gt_jasypt_call decrypt "$directory" "$marker" 2>&1) || { gt_core_error "Jasypt decryption failed ($key); plugin output suppressed."; return 2; }
  # decrypt reports the result on stdout and deliberately leaves the encrypted file intact.
  [[ "$output" == *"${marker}_BEGIN${SECRET[$key]}${marker}_END"* ]] || {
    gt_core_error "Jasypt literal round-trip failed ($key)."; return 2;
  }
  rm -rf -- "$directory"
  ENCRYPTED=$encrypted
}

gt_core_config_valid() {
  local id target digest mode
  for id in properties production launcher variables; do
    case "$id" in
      properties) target="$CORE_REPO/backend/grafioschtrader-server/src/main/resources/application.properties"; mode=600 ;;
      production) target="$CORE_REPO/backend/grafioschtrader-server/src/main/resources/application-production.properties"; mode=600 ;;
      launcher) target="$CORE_HOME/grafioschtrader.sh"; mode=700 ;;
      variables) target="$CORE_HOME/gtvar.sh"; mode=600 ;;
    esac
    gt_no_symlinks "$target" && [[ -f "$target" ]] || return 2
    digest=$(sha256sum "$target"); digest=${digest%% *}
    [[ "$digest" == "${STATE[file.$id]:-}" || "$id" == properties && "${STATE[step.app_cron]:-}" == running &&
      "$digest" == "${STATE[file.properties.previous]:-}" ]] || return 2
    [[ "$(stat -c '%U:%a' "$target")" == "grafioschtrader:$mode" ]] || return 2
  done
}

gt_core_configure() {
  local template="$SCRATCH/application.template" production="$SCRATCH/production.template" original target key auth=false starttls=false tls=false
  if [[ "${STATE[step.configuration]:-}" == complete ]]; then
    gt_core_config_valid || return 2
    [[ -z "${STATE[build.mode]:-}" ]] || gt_core_variables || return 2
    return 0
  fi
  target=backend/grafioschtrader-server/src/main/resources
  gt_as_app git -C "$CORE_REPO" show "${STATE[planned_commit]}:$target/application.properties" > "$template" || return 2
  if ! gt_as_app git -C "$CORE_REPO" show "${STATE[planned_commit]}:$target/application-production.properties" > "$production" 2>/dev/null; then
    : > "$production"
  fi
  # Only the environment placeholder is allowed; application startup must not use a template key.
  # shellcheck disable=SC2016
  grep -Fxq 'jasypt.encryptor.password=${JASYPT_ENCRYPTOR_PASSWORD:}' "$template" || return 2
  PROPERTIES=([g.main.user.admin.mail]="${ANSWER[ADMIN_EMAIL]}" [g.allowed.users]="${ANSWER[ALLOWED_USERS]}"
    [spring.mail.host]='' [spring.mail.port]=587 [spring.mail.username]='' [spring.mail.password]=''
    [gt.connector.ajp.enabled]=false [gt.connector.ajp.port]="${ANSWER[BACKEND_PORT]}"
    [gt.connector.http.enabled]=true [gt.connector.http.port]="${ANSWER[BACKEND_PORT]}")
  if [[ "${ANSWER[WEBSERVER]}" == apache2 ]]; then
    PROPERTIES[gt.connector.ajp.enabled]=true PROPERTIES[gt.connector.http.enabled]=false
  fi
  gt_encrypt_secret DB_PASSWORD || return 2
  PROPERTIES[spring.datasource.password]=$ENCRYPTED
  gt_encrypt_secret JWT_SECRET || return 2
  PROPERTIES[g.jwt.secret]=$ENCRYPTED
  if [[ "${ANSWER[SMTP_CONFIGURE]}" == yes ]]; then
    PROPERTIES[spring.mail.host]=${ANSWER[SMTP_HOST]} PROPERTIES[spring.mail.port]=${ANSWER[SMTP_PORT]}
    PROPERTIES[spring.mail.username]=${ANSWER[SMTP_USER]}
    if [[ "${ANSWER[SMTP_AUTH]}" == yes ]]; then
      auth=true; gt_encrypt_secret SMTP_PASSWORD || return 2
      PROPERTIES[spring.mail.password]=$ENCRYPTED
    fi
    case "${ANSWER[SMTP_SECURITY]}" in starttls) starttls=true ;; tls) tls=true ;; esac
  fi
  PROPERTIES[spring.mail.properties.mail.smtp.auth]=$auth
  PROPERTIES[spring.mail.properties.mail.smtp.starttls.enable]=$starttls
  PROPERTIES[spring.mail.properties.mail.smtp.ssl.enable]=$tls
  gt_properties_render "$template" "$SCRATCH/application.config" || return 2
  original=$(sha256sum "$template"); original=${original%% *}
  gt_core_publish properties "$SCRATCH/application.config" "$CORE_REPO/$target/application.properties" 600 "$original" || return 2
  PROPERTIES=([server.address]=127.0.0.1 [spring.mail.properties.mail.smtp.starttls.required]="$starttls")
  PROPERTIES[server.forward-headers-strategy]=none
  PROPERTIES[g.security.login.trusted-proxies]='127.0.0.1,::1'
  if [[ "${ANSWER[TLS_SOURCE]:-}" == proxy && -n "${ANSWER[TLS_PROXY_FROM]:-}" ]]; then
    PROPERTIES[g.security.login.trusted-proxies]+=",${ANSWER[TLS_PROXY_FROM]}"
  fi
  if [[ "${ANSWER[WEBSERVER]}" == apache2 ]]; then PROPERTIES[server.port]=${ANSWER[BACKEND_HTTP_PORT]}; fi
  gt_properties_render "$production" "$SCRATCH/production.config" yes || return 2
  original=$(sha256sum "$production"); original=${original%% *}
  gt_core_publish production "$SCRATCH/production.config" "$CORE_REPO/$target/application-production.properties" 600 "$original" || return 2
  # printf %q is Bash syntax; use a Bash shebang for every generated launcher.
  {
    printf '#!/bin/bash\nexport JASYPT_ENCRYPTOR_PASSWORD=%q\n' "${SECRET[JASYPT_PASSWORD]}"
    printf 'exec %q %s -Duser.language=en -jar /home/grafioschtrader/grafioschtrader-server-*.jar >> /var/log/grafioschtrader.log 2>&1\n' \
      "${STATE[java_home]}/bin/java" "${ANSWER[JAVA_HEAP]}"
  } > "$SCRATCH/launcher"
  bash -n "$SCRATCH/launcher" || return 2
  gt_core_publish launcher "$SCRATCH/launcher" "$CORE_HOME/grafioschtrader.sh" 700 || return 2
  gt_core_variables || return 2
  gt_core_config_valid && gt_core_mark step.configuration complete
}

gt_core_variables() {
  {
    printf 'export docroot=%q\nexport builddir=%q\nexport basehref=grafioschtrader/\nexport NG_CLI_ANALYTICS=false\n' "${ANSWER[DOCROOT]}" "$CORE_HOME/build"
    # shellcheck disable=SC2016
    printf 'export JAVA_HOME=%q\nexport PATH="$JAVA_HOME/bin:%s:$PATH"\n' "${STATE[java_home]}" "${STATE[maven]%/*}"
    if [[ -n "${STATE[build.node_home]:-}" ]]; then
      printf 'export npm_config_prefix=%q\nunset NODE_OPTIONS NODE_PATH\n' "${STATE[build.prefix]}"
      # shellcheck disable=SC2016
      printf 'export PATH="%s/bin:%s/bin:$PATH"\n' "${STATE[build.node_home]}" "${STATE[build.prefix]}"
    fi
  } > "$SCRATCH/variables"
  bash -n "$SCRATCH/variables" || return 2
  gt_core_publish variables "$SCRATCH/variables" "$CORE_HOME/gtvar.sh" 600 || return 2
}

# Guidance is display data. No download, repository enrollment or command evaluation occurs here.
gt_toolchain_guidance() {
  local architecture archive
  if [[ "${ACTION[java]:-reuse}" != reuse ]]; then
    printf '\n'; gt_text 'Java installation choices' 'Java-Installationswege'
    printf '  apt-cache policy openjdk-%s-jdk-headless\n' "$JAVA_REQUIRED"
    gt_text 'A suitable APT candidate is installed by --install-core after confirmation. Refresh missing/stale lists with sudo apt-get update, then repeat the installer.' \
      'Einen passenden APT-Kandidaten installiert --install-core nach Bestätigung. Fehlende/veraltete Listen mit sudo apt-get update erneuern und den Installer wiederholen.'
    architecture=${FACT[architecture]:-unknown}
    case "$architecture" in amd64) archive=amd64 ;; arm64) archive=aarch64 ;; armhf) archive=arm32-vfp-hflt ;; *) archive=unknown ;; esac
    printf '  Liberica JDK %s: Linux %s (%s), tar.gz\n' "$JAVA_REQUIRED" "$archive" "$architecture"
    gt_text 'Without a suitable APT candidate: select the current matching JDK archive, verify its vendor checksum, unpack into a new /usr/local/jdk-25 directory and verify bin/java --version and bin/javac --version. Keep the system Java selection; the installer detects this directory.' \
      'Ohne passenden APT-Kandidaten: aktuelles passendes JDK-Archiv wählen, Herstellerprüfsumme prüfen, in ein neues Verzeichnis /usr/local/jdk-25 entpacken und bin/java --version sowie bin/javac --version prüfen. System-Java beibehalten; der Installer erkennt dieses Verzeichnis.'
    printf '  https://github.com/grafioschtrader/grafioschtrader/wiki/Install-Java\n  https://bell-sw.com/pages/downloads/\n'
  fi
  if [[ "${ACTION[maven]:-reuse}" != reuse ]]; then
    printf '\n'; gt_text 'Maven installation choices' 'Maven-Installationswege'
    printf '  apt-cache policy maven\n'
    gt_text 'APT Maven >= 3.8 is installed after confirmation. Otherwise download a current stable Maven 3 binary tar.gz plus its SHA-512 from Apache, verify it, and unpack into a new /opt/apache-maven-<version> directory. No global PATH or /opt/maven symlink change is needed; the installer detects the versioned directory and supplies its selected JAVA_HOME.' \
      'APT-Maven >= 3.8 wird nach Bestätigung installiert. Andernfalls ein aktuelles stabiles Maven-3-Binärarchiv tar.gz und dessen SHA-512 von Apache laden, prüfen und in ein neues /opt/apache-maven-<Version> entpacken. Weder globaler PATH noch /opt/maven-Symlink müssen geändert werden; der Installer erkennt das Versionsverzeichnis und setzt sein gewähltes JAVA_HOME.'
    printf '  https://github.com/grafioschtrader/grafioschtrader/wiki/Installing-the-Latest-Release-of-Apache-Maven\n  https://maven.apache.org/download.cgi\n'
  fi
}

# Choose only candidates from already configured APT sources; alternative installation is guided explicitly.
gt_core_toolchain_plan() {
  local tool package candidate installed home key value
  FACT[toolchain.java.package]=none FACT[toolchain.maven.package]=none
  FACT[toolchain.java.version]=none FACT[toolchain.maven.version]=none
  FACT[toolchain.java.path]=${FACT[java.suitable]} FACT[toolchain.maven.path]=${FACT[maven.path]}
  for tool in java maven; do
    if [[ "$tool" == java ]]; then package=openjdk-$JAVA_REQUIRED-jdk-headless; home=${FACT[java.suitable]}
    else package=maven; home=${FACT[maven.path]}; fi
    if [[ -n "${STATE[scope]:-}" && "${STATE[step.toolchains]:-complete}" == complete ]]; then
      [[ "$tool" == java ]] && key=java_home || key=maven
      [[ "$home" == "${STATE[$key]}" ]] || gt_plan_block "Selected $tool path changed; restore ${STATE[$key]}."
      gt_plan_row reuse "$tool" "${STATE[$key]}"
      continue
    fi
    if [[ -n "${STATE[toolchain.$tool.package]:-}" ]]; then
      package=${STATE[toolchain.$tool.package]}
      candidate=${STATE[toolchain.$tool.version]}
      if [[ "$package" == none ]]; then
        [[ "$tool" == java ]] && key=java_home || key=maven
        [[ "$home" == "${STATE[$key]}" ]] || gt_plan_block "Selected $tool path changed; restore ${STATE[$key]}."
        continue
      fi
    elif [[ "${ACTION[$tool]}" == reuse ]]; then
      gt_plan_row reuse "$tool" "$home"
      continue
    else
      candidate=${CANDIDATE[$package]:-unknown}
      installed=${PACKAGE[$package]:-absent}
      # Maven can be installed but unable to start until the new JDK exists.
      if [[ "$tool" == maven && "${FACT[java.suitable]}" == absent ]] &&
          gt_version_at_least "${installed%%-*}" 3.8 && [[ -x "$(gt_path /usr/bin/mvn)" ]]; then
        FACT[toolchain.maven.path]=$(gt_path /usr/bin/mvn)
        gt_plan_row reuse maven 'Installed APT Maven; verify using the selected JDK after Java installation'
        continue
      fi
      value=${candidate#*:}; value=${value%%-*}
      if [[ ! "$candidate" =~ ^[a-zA-Z0-9.+:~_-]+$ || "$candidate" == unknown ]] ||
          { [[ "$tool" == maven ]] && ! gt_version_at_least "$value" 3.8; } ||
          { [[ "$tool" == java ]] && [[ ! "$value" =~ ^$JAVA_REQUIRED([.+~-]|$) ]]; }; then
        gt_plan_block "No suitable APT $tool candidate. Follow the alternative installation instructions above, then rerun --install-core." \
          "Kein passender APT-Kandidat für $tool. Alternative Installationsanleitung oben ausführen, danach --install-core wiederholen."
        continue
      fi
      if [[ -n "${PACKAGE[$package]:-}" ]]; then
        gt_plan_block "$package is installed but unusable; repair it or use the documented alternative. Automatic upgrades are not authorized."
        continue
      fi
    fi
    FACT[toolchain.$tool.package]=$package FACT[toolchain.$tool.version]=$candidate
    FACT[toolchain.$tool.path]=pending
    if [[ "${PACKAGE[$package]:-}" != "$candidate" ]]; then
      [[ "${CANDIDATE[$package]:-}" == "$candidate" ]] || gt_plan_block "Recorded candidate $package=$candidate is unavailable; restore its APT source before resuming."
      gt_plan_package "$package=$candidate"
    fi
    gt_plan_row install "$tool" "$package=$candidate; verify executables before creating the application user"
  done
  if [[ "${FACT[toolchain.java.package]}:${FACT[toolchain.maven.package]}" != none:none ]]; then
    command -v update-alternatives >/dev/null || gt_plan_block 'update-alternatives is required before toolchain installation.'
    gt_plan_row preserve java-alternatives 'Restore previous selections after APT, including failed transactions; changed automatic selections become manual.' \
      'Bisherige Auswahl nach APT wiederherstellen, auch bei Fehlern; geänderte automatische Auswahlen werden manuell.'
  fi
}

gt_toolchain_verify() {
  local home=$1 maven=$2 value major javac version
  [[ -x "$home/bin/java" && -x "$home/bin/javac" && -x "$maven" ]] || return 2
  value=$(gt_probe env -u JAVA_TOOL_OPTIONS -u JDK_JAVA_OPTIONS -u _JAVA_OPTIONS "$home/bin/java" --version) || return 2
  major=$(sed -nE 's/^(openjdk|java) ([0-9]+)([. ].*|$)/\2/p' <<< "$value" | head -n 1)
  javac=$(gt_probe env -u JAVA_TOOL_OPTIONS -u JDK_JAVA_OPTIONS -u _JAVA_OPTIONS "$home/bin/javac" -version) || return 2
  [[ "$major" =~ ^[0-9]+$ && "$javac" =~ javac[[:space:]]+$major([.]|$) ]] && (( major >= JAVA_REQUIRED )) || return 2
  value=$(gt_maven_probe "$maven" "$home") || return 2
  version=$(gt_maven_version "$value")
  gt_version_at_least "$version" 3.8 && [[ "$value" =~ Java[[:space:]]version:[[:space:]]$major([,.]|$) ]]
}

gt_alternatives_save() {
  local selections name mode path
  [[ "${STATE[toolchain.alternatives]:-}" != saved ]] || return 0
  selections=$(LC_ALL=C update-alternatives --get-selections) || return 2
  while read -r name mode path; do
    [[ -n "$name" ]] || continue
    [[ "$name" =~ ^[a-zA-Z0-9_.+-]+$ && "$mode" =~ ^(auto|manual)$ && "$path" == /* && "$path" != *[$'\001'-$'\037'$'\177']* ]] || return 2
    STATE[alternative.$name]=$path
  done <<< "$selections"
  STATE[toolchain.alternatives]=saved
  gt_state_save
}

gt_alternatives_restore() {
  local key name current failed=0
  [[ "${STATE[toolchain.alternatives]:-}" == saved ]] || return 0
  for key in "${!STATE[@]}"; do
    [[ "$key" == alternative.* ]] || continue
    name=${key#alternative.}
    current=$(LC_ALL=C update-alternatives --query "$name") || { failed=1; continue; }
    current=$(sed -n 's/^Value: //p' <<< "$current")
    if [[ "$current" != "${STATE[$key]}" ]]; then
      gt_core_run update-alternatives --set "$name" "${STATE[$key]}" || failed=1
    fi
  done
  (( failed == 0 )) || { gt_core_error 'Could not restore original alternatives; resolve this before resuming.'; return 2; }
}

gt_core_toolchains() {
  local tool package version transaction line failed=0
  local -a requested=()
  if [[ "${STATE[step.toolchains]:-complete}" == complete ]]; then
    gt_toolchain_verify "${STATE[java_home]}" "${STATE[maven]}"
    return $?
  fi
  for tool in java maven; do
    package=${STATE[toolchain.$tool.package]}; version=${STATE[toolchain.$tool.version]}
    [[ "$package" == none ]] || requested+=("$package=$version")
  done
  if (( ${#requested[@]} )); then
    # Restore a selection changed by an interrupted previous transaction before doing more work.
    gt_alternatives_restore || return 2
    transaction=$(LC_ALL=C apt-get --simulate install "${requested[@]}" 2>/dev/null) || return 2
    while IFS= read -r line; do
      [[ "$line" != 'Remv '* && ! "$line" =~ ^Inst\ [^\ ]+\ \[ ]] || return 2
    done <<< "$transaction"
    gt_alternatives_save || return 2
    gt_core_mark step.toolchains running || return 2
    gt_core_run env DEBIAN_FRONTEND=noninteractive apt-get -y --no-remove --no-upgrade \
      -o DPkg::Lock::Timeout=600 install "${requested[@]}" || failed=1
    gt_alternatives_restore || return 2
    (( failed == 0 )) || return 2
  fi
  gt_java; gt_runtimes
  gt_toolchain_verify "${FACT[java.suitable]}" "${FACT[maven.path]}" || {
    gt_core_error 'Java, javac and Maven must run successfully with the selected JDK.'; return 2;
  }
  [[ "${STATE[java_home]}" == pending || "${STATE[java_home]}" == "${FACT[java.suitable]}" ]] || return 2
  [[ "${STATE[maven]}" == pending || "${STATE[maven]}" == "${FACT[maven.path]}" ]] || return 2
  STATE[java_home]=${FACT[java.suitable]} STATE[maven]=${FACT[maven.path]}
  gt_core_mark step.toolchains complete
}

# Build metadata is literal data: never derive executable shell fragments from registry responses.
gt_build_field() {
  case "$1" in
    mode) [[ "$2" == reuse || "$2" == archive ]] ;;
    node_version|cli_version|semver_version) [[ "$2" =~ ^[0-9]+\.[0-9]+\.[0-9]+$ ]] ;;
    node_home|npm) gt_valid_path "$2" ;;
    prefix) [[ "$2" == /opt/gt-build-tools ]] ;;
    node_file) [[ "$2" == none || "$2" =~ ^node-v[0-9]+\.[0-9]+\.[0-9]+-linux-(x64|arm64|armv7l)\.tar\.xz$ ]] ;;
    node_sha) [[ "$2" == none || "$2" =~ ^[a-f0-9]{64}$ ]] ;;
    cli_integrity|semver_integrity) [[ "$2" =~ ^sha512-[A-Za-z0-9+/]{86}==$ ]] ;;
    *) return 2 ;;
  esac
}

gt_build_valid() {
  local key
  for key in mode node_version node_home npm prefix node_file node_sha cli_version cli_integrity semver_version semver_integrity; do
    gt_build_field "$key" "${BUILD[$key]:-}" || return 2
  done
  gt_node_satisfies "${BUILD[node_version]}" "$NODE_REQUIRED" || return 2
  [[ "${BUILD[cli_version]%%.*}" == "$CLI_REQUIRED" ]] || return 2
  if [[ "${BUILD[mode]}" == archive ]]; then
    [[ "${BUILD[node_home]}" == /opt/nodejs-gt && "${BUILD[npm]}" == /opt/nodejs-gt/bin/npm &&
      "${BUILD[node_file]}" == node-v"${BUILD[node_version]}"-linux-*.tar.xz && "${BUILD[node_sha]}" != none ]] || return 2
  else
    [[ "${BUILD[node_file]}:${BUILD[node_sha]}" == none:none && "${BUILD[npm]}" == "${BUILD[node_home]}/bin/npm" ]] || return 2
    case "${BUILD[node_home]}" in /usr|/usr/local|/opt/*) ;; *) return 2 ;; esac
  fi
}

gt_build_metadata() {
  local package=$1 major=$2 output=$3
  gt_probe curl --proto '=https' --tlsv1.2 -fsSL --connect-timeout 5 --max-time 30 \
    -H 'Accept: application/vnd.npm.install-v1+json' "https://registry.npmjs.org/$package" -o "$output" || return 2
  python3 - "$output" "$major" <<'PY'
import json, re, sys
with open(sys.argv[1], encoding='utf-8') as source:
    data = json.load(source)
versions = [v for v in data['versions'] if re.fullmatch(r'\d+\.\d+\.\d+', v)
            and (sys.argv[2] == 'any' or v.split('.')[0] == sys.argv[2])]
v = max(versions, key=lambda v: tuple(map(int, v.split('.'))))
print(v, data['versions'][v]['dist']['integrity'], sep='\t')
PY
}

gt_build_resolve() {
  local arch line checksum filename extra metadata key
  BUILD=()
  if [[ -n "${STATE[build.mode]:-}" ]]; then
    for key in "${!STATE[@]}"; do [[ "$key" != build.* ]] || BUILD[${key#build.}]=${STATE[$key]}; done
    gt_build_valid
    return $?
  fi
  BUILD[prefix]=/opt/gt-build-tools
  if gt_node_satisfies "${FACT[node.version]:-absent}" "$NODE_REQUIRED" &&
      [[ "${FACT[node.path]:-}" == /usr/bin/node || "${FACT[node.path]:-}" == /usr/local/bin/node || "${FACT[node.path]:-}" == /opt/*/bin/node ]] &&
      [[ -x "${FACT[node.path]%/node}/npm" ]]; then
    BUILD[mode]=reuse BUILD[node_home]=${FACT[node.path]%/bin/node} BUILD[npm]=${FACT[node.path]%/node}/npm
    BUILD[node_version]=${FACT[node.version]} BUILD[node_file]=none BUILD[node_sha]=none
  else
    line=24
    case "${FACT[architecture]}" in amd64) arch=x64 ;; arm64) arch=arm64 ;; armhf) arch=armv7l; line=22 ;; *) return 2 ;; esac
    [[ "$arch" != armv7l || "$(date -u +%F)" < 2027-04-30 ]] || return 2
    gt_probe curl --proto '=https' --tlsv1.2 -fsSL --connect-timeout 5 --max-time 30 \
      "https://nodejs.org/dist/latest-v$line.x/SHASUMS256.txt" -o "$SCRATCH/node-sums" || return 2
    while read -r checksum filename extra; do
      [[ "$filename" =~ ^node-v$line\.[0-9]+\.[0-9]+-linux-$arch\.tar\.xz$ && "$checksum" =~ ^[a-f0-9]{64}$ && -z "$extra" ]] || continue
      [[ -z "${BUILD[node_file]:-}" ]] || return 2
      BUILD[node_file]=$filename BUILD[node_sha]=$checksum
      BUILD[node_version]=${filename#node-v}; BUILD[node_version]=${BUILD[node_version]%%-linux-*}
    done < "$SCRATCH/node-sums"
    BUILD[mode]=archive BUILD[node_home]=/opt/nodejs-gt BUILD[npm]=/opt/nodejs-gt/bin/npm
  fi
  metadata=$(gt_build_metadata '@angular%2fcli' "$CLI_REQUIRED" "$SCRATCH/cli-metadata") || return 2
  IFS=$'\t' read -r 'BUILD[cli_version]' 'BUILD[cli_integrity]' <<< "$metadata"
  metadata=$(gt_build_metadata semver any "$SCRATCH/semver-metadata") || return 2
  IFS=$'\t' read -r 'BUILD[semver_version]' 'BUILD[semver_integrity]' <<< "$metadata"
  gt_build_valid
}

gt_core_build_plan() {
  local command target
  for command in python3 tar xz; do
    command -v "$command" >/dev/null || { gt_plan_block "Build tool preparation requires $command; install python3 and xz-utils, then rerun."; return 0; }
  done
  [[ "${ANSWER[NODE_REPLACE]:-no}" != yes ]] || gt_plan_block 'Shared Node replacement is not supported by this core; select isolation (NODE_REPLACE=no).'
  if ! gt_build_resolve; then
    gt_plan_block 'Could not resolve compatible Node/Angular CLI/semver versions and checksums from official sources.'
    return 0
  fi
  target=${BUILD[prefix]}
  if [[ ( -e "$target" || -L "$target" ) && -z "${STATE[resource.buildtools]:-}" ]]; then gt_plan_block "Foreign build-tool prefix exists: $target"; fi
  if [[ "${BUILD[mode]}" == archive ]]; then
    target=${BUILD[node_home]}
    if [[ ( -e "$target" || -L "$target" ) && -z "${STATE[resource.node]:-}" ]]; then gt_plan_block "Foreign Node destination exists: $target"; fi
    gt_plan_row isolate "$target" "${BUILD[node_file]}; SHA-256 ${BUILD[node_sha]}; system Node unchanged"
  else gt_plan_row reuse node "${BUILD[node_home]}/bin/node; ${BUILD[node_version]}"; fi
  gt_plan_row install "${BUILD[prefix]}" "@angular/cli@${BUILD[cli_version]}, semver@${BUILD[semver_version]}; private global npm prefix, lifecycle scripts disabled"
  gt_plan_row verify npm "${BUILD[cli_integrity]}; ${BUILD[semver_integrity]}"
  gt_plan_row configure gtvar.sh 'Selected Node/npm and build-tool prefix; disable Angular analytics; verify as grafioschtrader'
}

gt_build_record() {
  local key
  gt_build_valid || return 2
  if [[ -z "${STATE[build.mode]:-}" ]]; then
    for key in "${!BUILD[@]}"; do STATE[build.$key]=${BUILD[$key]}; done
    STATE[step.buildtools]=pending
    gt_state_save || return 2
  fi
}

# Hash contents, permissions and link destinations with relative names so publication by rename is resumable.
gt_build_digest() {
  python3 - "$1" <<'PY'
import hashlib, os, stat, sys
from pathlib import Path
root = Path(sys.argv[1]); digest = hashlib.sha256()
info = root.lstat()
if not stat.S_ISDIR(info.st_mode) or info.st_uid != os.geteuid() or stat.S_IMODE(info.st_mode) != 0o755:
    raise SystemExit('Build tool root must be installer-owned with mode 755')
for p in sorted(root.rglob('*')):
    info = p.lstat()
    if info.st_uid != os.geteuid() or (not stat.S_ISLNK(info.st_mode) and info.st_mode & 0o022):
        raise SystemExit('Build tool files must be installer-owned and not writable by other users')
    digest.update((str(p.relative_to(root)) + ':' + str(stat.S_IMODE(info.st_mode)) + ':').encode())
    if p.is_symlink(): digest.update(os.readlink(p).encode())
    elif p.is_file(): digest.update(hashlib.sha256(p.read_bytes()).digest())
    elif not p.is_dir(): raise SystemExit('Unsupported build tool file')
print(digest.hexdigest())
PY
}

gt_build_publish() {
  local id=$1 stage=$2 destination=$3 digest current
  gt_no_symlinks "$destination" || return 2
  if [[ -e "$destination" ]]; then
    [[ "${STATE[resource.$id]:-}" == intent || "${STATE[resource.$id]:-}" == owned ]] || return 2
    current=$(gt_build_digest "$destination") || return 2
    [[ "$current" == "${STATE[file.$id]:-}" ]] || return 2
  else
    [[ "${STATE[resource.$id]:-}" == intent ]] || return 2
    digest=$(gt_build_digest "$stage") || return 2
    STATE[file.$id]=$digest
    gt_state_save || return 2
    mv -T -- "$stage" "$destination" || return 2
  fi
  gt_core_mark "resource.$id" owned
}

gt_build_stage() {
  local id=$1 stage=$2
  gt_no_symlinks "$stage" || return 2
  [[ "${STATE[resource.$id]:-}" != owned ]] || return 2
  if [[ -e "$stage" ]]; then
    [[ "${STATE[resource.$id]:-}" == intent && ( "$(stat -c '%u:%a' "$stage")" == "$EUID:700" || "$(stat -c '%u:%a' "$stage")" == "$EUID:755" ) ]] || return 2
    rm -rf -- "$stage" || return 2
  fi
  gt_core_mark "resource.$id" intent || return 2
  mkdir -m 700 -- "$stage"
}

gt_build_archive_safe() {
  python3 - "$1" "$2" <<'PY'
import posixpath, sys, tarfile
with tarfile.open(sys.argv[1], 'r:xz') as archive:
    members = archive.getmembers(); links = {m.name.rstrip('/') for m in members if m.issym()}
    root = sys.argv[2]
    for m in members:
        name = m.name.rstrip('/')
        if name != root and not name.startswith(root + '/'): raise SystemExit('Unexpected archive root')
        if '..' in name.split('/') or name.startswith('/') or not (m.isfile() or m.isdir() or m.issym()):
            raise SystemExit('Unsafe archive member')
        parent = posixpath.dirname(name)
        while parent:
            if parent in links: raise SystemExit('Archive writes through a symlink')
            parent = posixpath.dirname(parent)
        if m.issym():
            target = posixpath.normpath(posixpath.join(posixpath.dirname(name), m.linkname))
            if m.linkname.startswith('/') or not target.startswith(root + '/'):
                raise SystemExit('Archive link escapes destination')
PY
}

gt_build_download() {
  # Execution downloads may take longer than inventory probes. All URLs are constructed from validated metadata.
  curl --proto '=https' --proto-redir '=https' --tlsv1.2 -fsSL --connect-timeout 10 --max-time 600 --retry 2 "$1" -o "$2"
}

gt_build_npm() {
  local prefix=$1
  shift
  mkdir -p "$SCRATCH/npm-home" "$SCRATCH/build-cache" || return 2
  : > "$SCRATCH/npm-user-config"; : > "$SCRATCH/npm-global-config"
  (cd "$SCRATCH" && env -i HOME="$SCRATCH/npm-home" PATH="${STATE[build.node_home]}/bin:/usr/bin:/bin" \
    NG_CLI_ANALYTICS=false CI=true npm_config_userconfig="$SCRATCH/npm-user-config" npm_config_globalconfig="$SCRATCH/npm-global-config" \
    npm_config_prefix="$prefix" npm_config_cache="$SCRATCH/build-cache" npm_config_registry=https://registry.npmjs.org/ \
    npm_config_update_notifier=false npm_config_audit=false npm_config_fund=false npm_config_logs_max=0 \
    "${STATE[build.npm]}" "$@")
}

gt_build_verify() {
  local value prefix=${STATE[build.prefix]} node=${STATE[build.node_home]}/bin/node
  value=$(gt_probe env NODE_OPTIONS= "$node" --version) || return 2
  [[ "$value" == "v${STATE[build.node_version]}" ]] && gt_node_satisfies "$value" "$NODE_REQUIRED" || return 2
  gt_build_npm "$prefix" --version >/dev/null || return 2
  value=$(gt_build_npm "$prefix" ls -g --depth=0 --json) || return 2
  python3 -c 'import json,sys; d=json.load(sys.stdin)["dependencies"]; assert d["@angular/cli"]["version"]==sys.argv[1] and d["semver"]["version"]==sys.argv[2]' \
    "${STATE[build.cli_version]}" "${STATE[build.semver_version]}" <<< "$value" || return 2
  value=$(gt_as_app "$prefix/bin/semver" "${STATE[build.node_version]}" -r "$NODE_REQUIRED") || return 2
  [[ "$value" == "${STATE[build.node_version]}" ]] || return 2
  value=$(cd /tmp && gt_as_app "$prefix/bin/ng" version) || return 2
  value=$(sed -nE 's/^Angular CLI[[:space:]]*:[[:space:]]*([0-9]+\.[0-9]+\.[0-9]+).*/\1/p' <<< "$value")
  [[ "$value" == "${STATE[build.cli_version]}" ]]
}

gt_core_buildtools() {
  local stage archive checksum package version integrity url value key target
  [[ -n "${STATE[build.mode]:-}" ]] || return 2
  if [[ "${STATE[build.mode]}" == archive ]]; then
    target=${STATE[build.node_home]}; stage="/opt/.gt-node-${STATE[run_id]}"
    if [[ ! -e "$target" && ! -L "$target" ]]; then
      gt_build_stage node "$stage" || return 2
      archive="$SCRATCH/${STATE[build.node_file]}"
      gt_build_download "https://nodejs.org/dist/v${STATE[build.node_version]}/${STATE[build.node_file]}" "$archive" || return 2
      checksum=$(sha256sum "$archive"); [[ "${checksum%% *}" == "${STATE[build.node_sha]}" ]] || return 2
      gt_build_archive_safe "$archive" "${STATE[build.node_file]%.tar.xz}" || return 2
      tar --extract --xz --file "$archive" --directory "$stage" --strip-components=1 --no-same-owner --no-same-permissions || return 2
      chmod -R a+rX,go-w "$stage" || return 2
      chmod 755 "$stage" || return 2
    fi
    gt_build_publish node "$stage" "$target" || return 2
  fi
  value=$(gt_probe env NODE_OPTIONS= "${STATE[build.node_home]}/bin/node" --version) || return 2
  [[ "$value" == "v${STATE[build.node_version]}" ]] || return 2
  target=${STATE[build.prefix]}; stage="/opt/.gt-build-${STATE[run_id]}"
  if [[ ! -e "$target" && ! -L "$target" ]]; then
    gt_build_stage buildtools "$stage" || return 2
    for key in cli semver; do
      version=${STATE[build.${key}_version]}; integrity=${STATE[build.${key}_integrity]}
      [[ "$key" == cli ]] && package=@angular/cli || package=semver
      url="https://registry.npmjs.org/$package/-/${key}-$version.tgz"
      archive="$SCRATCH/$key.tgz"
      gt_build_download "$url" "$archive" || return 2
      value="sha512-$(openssl dgst -sha512 -binary "$archive" | openssl base64 -A)"
      [[ "$value" == "$integrity" ]] || return 2
    done
    gt_build_npm "$stage" install --global --ignore-scripts --engine-strict --no-audit --no-fund "$SCRATCH/cli.tgz" "$SCRATCH/semver.tgz" || return 2
    chmod -R a+rX,go-w "$stage" || return 2
    chmod 755 "$stage" || return 2
  fi
  gt_build_publish buildtools "$stage" "$target" || return 2
  gt_build_verify || return 2
  gt_core_mark step.buildtools complete
}

gt_core_plan() {
  local key database_check
  PLAN=() PLAN_BLOCKERS=() PLAN_WARNINGS=() PLAN_PACKAGES=()
  gt_stage_contract || true
  for key in platform architecture mariadb database disk; do
    if [[ "$key" == database && "${STATE[new_database_server]:-}" == yes && "${STATE[resource.mariadb]:-}" == owned && "${FACT[database.active]:-}" == no ]]; then
      continue # The execution step may start its own stopped server, then recheck every object.
    fi
    [[ "${ACTION[$key]:-block}" != block ]] || gt_plan_block "$key: ${REASON[$key]:-unknown}"
  done
  [[ "${FACT[init]}" == systemd ]] || gt_plan_block 'Core installation requires systemd.'
  gt_plan_base_packages
  gt_core_toolchain_plan
  gt_core_build_plan
  [[ "${FACT[source.requirements]}" == remote ]] || gt_plan_block 'Pinned source requirements must be available.'
  for key in runuser useradd passwd git curl openssl flock sha256sum; do
    command -v "$key" >/dev/null || gt_plan_block "Missing prerequisite: $key"
  done
  [[ "${FACT[host.class]}" == fresh || "${FACT[host.class]}" == unfinished && "${STATE[scope]:-}" == core ]] || gt_plan_block 'Only fresh hosts and this core journal can be used.'
  for key in "${QUESTIONS[@]}"; do
    [[ "${Q_TYPE[$key]}" != secret ]] || continue
    [[ "$key" != DB_REUSE_EMPTY || "${STATE[database_before]:-}" != no ]] || continue
    if gt_question_applies "$key"; then
      gt_validate_answer "$key" "${ANSWER[$key]:-}" || gt_plan_block "Invalid/missing answer: $key"
    fi
  done
  if [[ "${FACT[database.gt_tables]}" == 0 && "${STATE[database_before]:-}" != no && "${ANSWER[DB_REUSE_EMPTY]:-}" != yes ]]; then
    gt_plan_block 'Reuse of the existing empty database requires consent.'
  fi
  if [[ "${FACT[database.active]:-}" == yes && "${FACT[database.query]}" == ok ]]; then
    if [[ "${FACT[database.gt_user]}" == present ]]; then
      gt_core_login DB_PASSWORD grafioschtrader TCP || gt_plan_block 'Existing database credentials no longer authenticate.'
    fi
    if [[ "${FACT[database.gt_tables]}" == 0 ]]; then
      database_check=$(printf "SELECT DEFAULT_CHARACTER_SET_NAME,DEFAULT_COLLATION_NAME FROM information_schema.SCHEMATA WHERE SCHEMA_NAME='grafioschtrader';\n" | gt_core_sql) || database_check=unknown
      [[ "$database_check" == $'utf8mb4\tutf8mb4_general_ci' ]] || gt_plan_block 'Existing empty database must use utf8mb4 / utf8mb4_general_ci.'
    fi
    if [[ "${FACT[database.gt_user]}" == present && -z "${STATE[resource.account]:-}" ]]; then
      database_check=$(printf "SHOW GRANTS FOR 'grafioschtrader'@'localhost';\n" | gt_core_sql) || database_check=unknown
      # shellcheck disable=SC2016
      [[ "$database_check" == *'GRANT ALL PRIVILEGES ON `grafioschtrader`.* TO '* ]] || gt_plan_block 'Existing account lacks required schema privileges; it will not be altered.'
    fi
  fi
  gt_plan_row configure core 'This scope stops after database and encrypted configuration; no build, backend service, web server or TLS changes.' \
    'Diese Stufe endet nach Datenbank und verschlüsselter Konfiguration; kein Build, Backend-Dienst, Webserver oder TLS.'
  gt_plan_row create /var/lib/gt-install 'Root-only lock and atomic resumption journal (700/600)'
  gt_plan_row create /root/.gt-install/secrets 'Application secrets only (600); no database root password'
  gt_plan_row create user:grafioschtrader 'Disabled password; owned home and source checkout'
  gt_plan_row clone "$CORE_REPO" "${FACT[source.commit]}"
  if [[ "${FACT[database.vendor]}" == absent ]]; then
    gt_plan_package mariadb-server; gt_plan_package mariadb-client
    gt_plan_row install 'mariadb-server mariadb-client' 'Distribution packages; no removals/upgrades; root password plus unix_socket; remove default anonymous accounts and test schema'
  fi
  gt_plan_packages
  if gt_plan_needs_apt; then
    [[ "${FACT[dpkg.lock]}" == free && "${FACT[apt.age_hours]}" != unknown ]] || gt_plan_block 'Package lock/metadata unavailable; install psmisc and run sudo apt-get update, then re-plan.'
    if [[ "${FACT[apt.age_hours]}" != unknown ]] && (( ${FACT[apt.age_hours]} > 24 )); then gt_plan_block 'APT metadata is stale; run sudo apt-get update and re-plan.'; fi
  fi
  if [[ "${STATE[new_database_server]:-}" == yes && "${FACT[database.active]:-}" == no ]]; then
    gt_plan_row start mariadb.service 'Resume the installer-owned database server, then verify original credentials and empty schema before any SQL changes'
  fi
  gt_plan_row configure database:grafioschtrader 'Empty utf8mb4/general_ci schema; existing account unchanged; TCP verification'
  [[ "${ANSWER[BUFFER_POOL]:-no}" != yes ]] || gt_plan_row configure mariadb 'Buffer pool drop-in and restart; affects all databases on this server'
  gt_plan_row configure "$CORE_REPO/backend/grafioschtrader-server/src/main/resources" 'Encrypted application.properties and production override; encryption/decryption verified'
  gt_plan_row create "$CORE_HOME/gtvar.sh, grafioschtrader.sh" 'Selected Java, heap and protected encryption key; service not installed or started'
  FACT[core.plan]=$(printf '%s\n' "${PLAN[@]}" | sha256sum)
  (( ${#PLAN_BLOCKERS[@]} == 0 ))
}

gt_core_snapshot() {
  local key
  for key in "${!FACT[@]}"; do
    case "$key" in
      dns.status|plan.names|network.public_ipv4|network.global_ipv6|core.plan|host.*|source.*|os.*|architecture|init|java.suitable|java.alternatives|javac.alternatives|maven.path|node.path|node.version|node.origin|toolchain.*|apt.candidate.*|database.vendor|database.version|database.gt_tables|database.gt_user|database.users|database.schemas|database.buffer_pool_config|packages|dpkg.lock)
        printf '%s=%s\n' "$key" "${FACT[$key]}" ;;
    esac
  done
  for key in "${!PACKAGE[@]}"; do printf 'package:%s=%s\n' "$key" "${PACKAGE[$key]}"; done
}

gt_core_execute() {
  local step
  for step in base_packages toolchains user buildtools clone database configure; do
    printf '%s: %s\n' "$(gt_text 'Core step' 'Kernschritt')" "$step"
    "gt_core_$step" || { gt_core_error "$step; resume with --install-core after resolving the cause. No automatic rollback."; return 2; }
  done
  gt_core_mark step.core complete || return 2
  gt_text 'Core prepared. Installation remains unfinished: build, service, web/TLS and application checks are pending.' \
    'Installationskern eingerichtet. Installation bleibt unvollständig: Build, Dienst, Web/TLS und Anwendungsprüfungen stehen aus.'
  return 10
}
# Privileged configuration has a separate publisher: app-owned helpers must never
# determine the ownership or contents of sudoers, units or logrotate configuration.
gt_app_root_file() {
  local id=$1 input=$2 target=$3 mode=$4 digest current temporary
  gt_no_symlinks "$target" || return 2
  digest=$(sha256sum "$input"); digest=${digest%% *}
  if [[ -e "$target" ]]; then
    [[ -f "$target" && "$(stat -c '%u:%a' "$target")" == "0:$mode" ]] || return 2
    current=$(sha256sum "$target"); current=${current%% *}
    [[ "$current" == "${STATE[file.$id]:-}" && "$current" == "$digest" ]] || return 2
    return 0
  fi
  [[ -z "${STATE[file.$id]:-}" || "${STATE[file.$id]}" == "$digest" ]] || return 2
  gt_core_mark "file.$id" "$digest" || return 2
  temporary=$(mktemp "${target}.gt-install.XXXXXX") || return 2
  PRIVATE_FILES+=("$temporary")
  install -o root -g root -m "$mode" "$input" "$temporary" && mv -T "$temporary" "$target"
}

gt_app_sql() {
  local file result=0
  file=$(gt_db_options DB_PASSWORD grafioschtrader) || return 2
  mariadb "--defaults-file=$file" --protocol=TCP --host=127.0.0.1 --port=3306 \
    --user=grafioschtrader --database=grafioschtrader --batch --skip-column-names \
    --connect-timeout=4 2>/dev/null || result=$?
  rm -f -- "$file"
  return "$result"
}

gt_app_database() {
  local count failed
  gt_core_login DB_PASSWORD grafioschtrader TCP || return 2
  count=$(printf "SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA='grafioschtrader';\n" | gt_app_sql) || return 2
  [[ "$count" =~ ^[0-9]+$ ]] || return 2
  if [[ -z "${STATE[step.app_start]:-}" ]]; then
    [[ "$count" == 0 ]] || { gt_core_error 'Database is no longer empty before the first authorized start.'; return 2; }
  elif (( count > 0 )); then
    # Only a journaled first start may resume a populated schema. Failed migrations
    # require diagnosis; never automatically drop, repair or baseline anything.
    failed=$(printf 'SELECT COUNT(*) FROM flyway_schema_history WHERE success=0;\n' | gt_app_sql) || return 2
    [[ "$failed" == 0 ]] || { gt_core_error 'Failed Flyway migration; inspect the application log before resuming.'; return 2; }
  fi
}

gt_app_preflight() {
  local command file path entry commit changed digest mode
  gt_stage_preflight || return 2
  [[ "${STATE[step.core]:-}:${STATE[step.database]:-}:${STATE[step.configuration]:-}" == complete:complete:complete &&
    "${STATE[step.buildtools]:-}" == complete ]] || { gt_core_error 'Complete --install-core first.'; return 2; }
  [[ "$(cat "$(gt_path /proc/1/comm)")" == systemd ]] || return 2
  for command in systemctl systemd-analyze visudo logrotate sudo wget curl python3 flock mariadb ss; do
    command -v "$command" >/dev/null || { gt_core_error "Missing prerequisite: $command"; return 2; }
  done
  gt_core_config_valid || { gt_core_error 'Managed application configuration changed.'; return 2; }
  for file in DOCROOT TIMEZONE BACKEND_PORT WEBSERVER; do
    gt_validate_answer "$file" "${ANSWER[$file]:-}" || return 2
  done
  entry=$(getent passwd grafioschtrader) || return 2
  [[ "$entry" == *":GT installer ${STATE[run_id]}:$CORE_HOME:/bin/bash" ]] || return 2
  [[ "$(passwd -S grafioschtrader | awk '{print $2}')" == L ]] || return 2
  gt_no_symlinks "$CORE_REPO" || return 2
  commit=$(gt_as_app git -C "$CORE_REPO" rev-parse HEAD) || return 2
  [[ "$commit" == "${STATE[planned_commit]}" &&
    "$(gt_as_app git -C "$CORE_REPO" remote get-url origin)" == "$CORE_REMOTE" ]] || return 2
  changed=$(gt_as_app git -C "$CORE_REPO" diff HEAD --name-only) || return 2
  while IFS= read -r file; do
    case "$file" in ''|backend/grafioschtrader-server/src/main/resources/application.properties|backend/grafioschtrader-server/src/main/resources/application-production.properties) ;;
      *) gt_core_error "Source changed: $file"; return 2 ;;
    esac
  done <<< "$changed"
  for file in gtupbackend.sh gtupfrontend.sh; do
    gt_as_app git -C "$CORE_REPO" show "${STATE[planned_commit]}:util/shellscripts/$file" > "$SCRATCH/$file" || return 2
    grep -q GT_INSTALL_BUILD_ONLY "$SCRATCH/$file" || { gt_core_error 'Pinned source lacks the installer build-only contract.'; return 2; }
  done
  for file in node buildtools; do
    [[ "$file" != node || "${STATE[build.mode]}" == archive ]] || continue
    path=${STATE[build.prefix]}
    [[ "$file" != node ]] || path=${STATE[build.node_home]}
    gt_no_symlinks "$path" || return 2
    digest=$(gt_build_digest "$path") || return 2
    [[ "$digest" == "${STATE[file.$file]:-}" ]] || return 2
  done
  # Do not mask a distribution unit or any foreign override, including runtime units.
  for path in /run/systemd/system /usr/lib/systemd/system /lib/systemd/system /etc/systemd/system; do
    [[ ! -e "$(gt_path "$path/grafioschtrader.service.d")" && ! -L "$(gt_path "$path/grafioschtrader.service.d")" ]] || return 2
    [[ "$path" == /etc/systemd/system ]] && continue
    [[ ! -e "$(gt_path "$path/grafioschtrader.service")" && ! -L "$(gt_path "$path/grafioschtrader.service")" ]] || return 2
  done
  for entry in 'unit:/etc/systemd/system/grafioschtrader.service' 'sudoers:/etc/sudoers.d/grafioschtrader' 'logrotate:/etc/logrotate.d/grafioschtrader'; do
    file=${entry#*:}; path=$(gt_path "$file")
    gt_no_symlinks "$path" || return 2
    [[ ! -e "$path" || -n "${STATE[file.app_${entry%%:*}]:-}" ]] || { gt_core_error "Foreign file: $file"; return 2; }
    if [[ -e "$path" ]]; then
      digest=$(sha256sum "$path"); digest=${digest%% *}
      mode=644; [[ "${entry%%:*}" != sudoers ]] || mode=440
      [[ "$digest" == "${STATE[file.app_${entry%%:*}]}" && "$(stat -c '%u:%a' "$path")" == "0:$mode" ]] || return 2
    fi
  done
  path=$(gt_path "${ANSWER[DOCROOT]}/grafioschtrader")
  gt_no_symlinks "$path" || return 2
  [[ ! -e "$path" || "${STATE[resource.app_frontend]:-}" == intent || "${STATE[resource.app_frontend]:-}" == owned ]] || return 2
  path=$(gt_path /var/log/grafioschtrader.log)
  gt_no_symlinks "$path" || return 2
  [[ ! -e "$path" || -n "${STATE[resource.app_log]:-}" ]] || return 2
  if [[ -z "${STATE[step.app_build]:-}" ]]; then
    [[ -z "$(find "$CORE_HOME" -maxdepth 1 -name 'grafioschtrader*.jar' -print -quit)" ]] || return 2
  fi
  if [[ -z "${STATE[step.app_start]:-}" ]]; then
    changed=$(ss -Htln) || return 2
    if awk -v p="${ANSWER[BACKEND_PORT]}" -v q="${ANSWER[BACKEND_HTTP_PORT]:-0}" \
      '$4 ~ (":" p "$") || $4 ~ (":" q "$") {found=1} END {exit !found}' <<< "$changed"; then
      gt_core_error 'Selected backend port is occupied.'; return 2
    fi
  fi
  gt_app_database
}

gt_app_scripts() {
  local file
  for file in gtupdate.sh gtupbackend.sh gtupfrontend.sh gtupfrontback.sh checkversion.sh merger.sh gt_to_g_rename.sh gtcronrandom.sh; do
    gt_as_app git -C "$CORE_REPO" show "${STATE[planned_commit]}:util/shellscripts/$file" > "$SCRATCH/$file" || return 2
    bash -n "$SCRATCH/$file" || return 2
    gt_core_publish "app_$file" "$SCRATCH/$file" "$CORE_HOME/$file" 700 || return 2
  done
  gt_as_app bash "$CORE_HOME/checkversion.sh" > "$SCRATCH/app-versions.log" 2>&1 || {
    gt_core_error 'Selected toolchain does not satisfy the pinned checkversion.sh.'; return 2;
  }
}

gt_app_resources() {
  local path current
  path=$(gt_path "${ANSWER[DOCROOT]}")
  gt_no_symlinks "$path" || return 2
  if [[ ! -e "$path" ]]; then
    gt_core_mark resource.app_docroot intent || return 2
    (umask 022; mkdir -p "$path") || return 2
    gt_core_mark resource.app_docroot owned || return 2
  fi
  [[ -d "$path" ]] || return 2
  path+=/grafioschtrader
  if [[ ! -e "$path" ]]; then
    gt_core_mark resource.app_frontend intent || return 2
    install -d -o grafioschtrader -g grafioschtrader -m 755 "$path" || return 2
  fi
  gt_no_symlinks "$path" && [[ -d "$path" && "$(stat -c %U "$path")" == grafioschtrader ]] || return 2
  gt_core_mark resource.app_frontend owned || return 2
  path=$(gt_path /var/log/grafioschtrader.log)
  if [[ ! -e "$path" ]]; then
    gt_core_mark resource.app_log intent || return 2
    install -o grafioschtrader -g grafioschtrader -m 640 /dev/null "$path" || return 2
  fi
  [[ -f "$path" && "$(stat -c '%U:%a' "$path")" == grafioschtrader:640 ]] || return 2
  gt_core_mark resource.app_log owned || return 2
  current=$(gt_core_run timedatectl show --property=Timezone --value) || return 2
  if [[ "$current" != "${ANSWER[TIMEZONE]}" ]]; then
    [[ -z "${STATE[resource.app_timezone]:-}" || "$current" == "${STATE[resource.app_timezone]}" ]] || return 2
    gt_core_mark resource.app_timezone "$current" || return 2
    gt_core_run timedatectl set-timezone "${ANSWER[TIMEZONE]}" || return 2
  fi
  gt_core_mark resource.app_timezone "${ANSWER[TIMEZONE]}"
}

gt_app_service() {
  local systemctl_path
  systemctl_path=$(command -v systemctl) || return 2
  [[ "$systemctl_path" == /usr/bin/systemctl || "$systemctl_path" == /bin/systemctl ]] || return 2
  printf 'grafioschtrader ALL=(root) NOPASSWD: %s stop grafioschtrader.service, %s start grafioschtrader.service\n' \
    "$systemctl_path" "$systemctl_path" > "$SCRATCH/sudoers"
  visudo -cf "$SCRATCH/sudoers" >/dev/null || return 2
  cat > "$SCRATCH/grafioschtrader.service" <<'UNIT'
[Unit]
Description=Grafioschtrader
After=network.target mariadb.service

[Service]
User=grafioschtrader
WorkingDirectory=/home/grafioschtrader
ExecStart=/home/grafioschtrader/grafioschtrader.sh
Type=simple
UMask=0077

[Install]
WantedBy=multi-user.target
UNIT
  systemd-analyze verify "$SCRATCH/grafioschtrader.service" || return 2
  cat > "$SCRATCH/logrotate" <<'ROTATE'
/var/log/grafioschtrader.log {
    weekly
    rotate 8
    compress
    missingok
    notifempty
    copytruncate
    su grafioschtrader grafioschtrader
}
ROTATE
  logrotate --debug "$SCRATCH/logrotate" > "$SCRATCH/logrotate-check" 2>&1 || return 2
  gt_app_root_file app_sudoers "$SCRATCH/sudoers" "$(gt_path /etc/sudoers.d/grafioschtrader)" 440 &&
    gt_app_root_file app_unit "$SCRATCH/grafioschtrader.service" "$(gt_path /etc/systemd/system/grafioschtrader.service)" 644 &&
    gt_app_root_file app_logrotate "$SCRATCH/logrotate" "$(gt_path /etc/logrotate.d/grafioschtrader)" 644 || return 2
  gt_core_run systemctl daemon-reload
}

gt_app_cron() {
  local saved temporary target
  saved="$(gt_path /var/lib/gt-install)/cron.properties"
  [[ "${STATE[step.app_cron]:-}" != complete ]] || return 0
  target="$CORE_REPO/backend/grafioschtrader-server/src/main/resources/application.properties"
  gt_no_symlinks "$saved" || return 2
  if [[ ! -e "$saved" ]]; then
    gt_core_mark step.app_cron running || return 2
    temporary=$(gt_as_app mktemp "$CORE_HOME/.gt-cron.XXXXXX") || return 2
    PRIVATE_FILES+=("$temporary")
    gt_as_app cp "$target" "$temporary" &&
      gt_as_app env TZ="${ANSWER[TIMEZONE]}" GT_CRON_RANDOMIZE=on bash "$CORE_HOME/gtcronrandom.sh" --file "$temporary" > "$SCRATCH/cron.log" 2>&1 || return 2
    install -o root -g root -m 600 "$temporary" "$saved.pending" && mv -T "$saved.pending" "$saved" || return 2
  fi
  [[ "${STATE[step.app_cron]:-}" == running ]] && gt_private_read "$saved" || return 2
  PRIVATE_CONTENT=''
  gt_core_publish properties "$saved" "$target" 600 || return 2
  gt_core_mark step.app_cron complete
}

gt_app_artifacts() {
  local digest file
  local -a jars=()
  while IFS= read -r -d '' file; do jars+=("$file"); done < <(find "$CORE_HOME" -maxdepth 1 -name 'grafioschtrader-server-*.jar' -print0)
  (( ${#jars[@]} == 1 )) || return 2
  for file in "${jars[0]}" "$(gt_path "${ANSWER[DOCROOT]}/grafioschtrader/index.html")"; do
    gt_no_symlinks "$file" && [[ -s "$file" && -f "$file" && "$(stat -c %U "$file")" == grafioschtrader ]] || return 2
    digest=$(sha256sum "$file"); digest=${digest%% *}
    if [[ "${STATE[step.app_build]:-}" == complete ]]; then
      [[ "$digest" == "${STATE[file.app_artifact_${file##*/}]:-}" ]] || return 2
    else STATE[file.app_artifact_${file##*/}]=$digest; fi
  done
}

gt_app_build() {
  local log commit
  log="$(gt_path /var/lib/gt-install)/app-build.log"
  if [[ "${STATE[step.app_build]:-}" == complete ]]; then gt_app_artifacts; return $?; fi
  [[ -z "${STATE[step.app_start]:-}" ]] || return 2
  gt_core_run systemctl is-active --quiet grafioschtrader.service && return 2
  gt_core_mark step.app_build running || return 2
  gt_no_symlinks "$log" || return 2
  # Keep output private: dependency tools can echo configuration on failure.
  (umask 077; touch "$log") && chmod 600 "$log" || return 2
  printf '%s\n' "Build log: $log"
  # Use the approved checkout; gtupdate.sh is reserved for later updates to master.
  # Cron slots have already been journaled; builds must not modify configuration.
  gt_as_app env GT_INSTALL_BUILD_ONLY=1 GT_CRON_RANDOMIZE=off bash "$CORE_HOME/gtupfrontend.sh" >> "$log" 2>&1 &&
    gt_as_app env GT_INSTALL_BUILD_ONLY=1 GT_CRON_RANDOMIZE=off bash "$CORE_HOME/gtupbackend.sh" >> "$log" 2>&1 || return 2
  gt_core_config_valid && gt_app_artifacts || return 2
  commit=$(gt_as_app git -C "$CORE_REPO" rev-parse HEAD) || return 2
  [[ "$commit" == "${STATE[planned_commit]}" ]] || return 2
  gt_core_mark built_commit "$commit" || return 2
  gt_core_mark step.app_build complete
}

gt_app_verify() {
  local port=${ANSWER[BACKEND_PORT]} response count pid listeners expected
  [[ "${ANSWER[WEBSERVER]}" != apache2 ]] || port=${ANSWER[BACKEND_HTTP_PORT]}
  response=$(curl --noproxy '*' --fail --silent --max-time 5 "http://127.0.0.1:$port/api/gtinfo") || return 1
  printf '%s' "$response" | python3 -c 'import json,sys; d=json.load(sys.stdin); sys.exit(not isinstance(d,dict) or d.get("databaseName") != "grafioschtrader" or d.get("activeProfile") not in ("", "production"))' 2>/dev/null || return 1
  gt_core_run systemctl is-active --quiet grafioschtrader.service || return 2
  pid=$(gt_core_run systemctl show --property=MainPID --value grafioschtrader.service) || return 2
  [[ "$pid" =~ ^[1-9][0-9]*$ ]] || return 2
  # Java's dual-stack sockets may expose an IPv4 bind as an IPv4-mapped IPv6
  # address. Compare its actual address, retaining rejection of wildcard binds.
  listeners=$(set -o pipefail; ss -Htlnp | awk -v pid="$pid" 'index($0,"pid=" pid ",") {print $4}' | python3 -c '
import ipaddress, sys
for line in sys.stdin:
    address, port = line.strip().rsplit(":", 1)
    try:
        value = ipaddress.ip_address(address.strip("[]"))
        if isinstance(value, ipaddress.IPv6Address) and value.ipv4_mapped:
            address = str(value.ipv4_mapped)
    except ValueError:
        pass
    print(address + ":" + port)
' | LC_ALL=C sort) || return 2
  expected="127.0.0.1:$port"
  [[ "${ANSWER[WEBSERVER]}" != apache2 ]] || expected=$(printf '%s\n127.0.0.1:%s\n' "$expected" "${ANSWER[BACKEND_PORT]}" | LC_ALL=C sort)
  [[ "$listeners" == "$expected" ]] || return 2
  count=$(printf 'SELECT COUNT(*) FROM flyway_schema_history WHERE success=1;\n' | gt_app_sql) || return 2
  [[ "$count" =~ ^[1-9][0-9]*$ ]] || return 2
  count=$(printf "SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA='grafioschtrader' AND COLLATION_NAME LIKE '%%uca1400%%';\n" | gt_app_sql) || return 2
  [[ "$count" == 0 ]] || return 2
  gt_app_database
}

gt_app_start() {
  local deadline=$((SECONDS+900)) status active
  gt_app_database && gt_app_artifacts || return 2
  if [[ -z "${STATE[step.app_start]:-}" ]]; then gt_core_mark step.app_start intent || return 2; fi
  # The write-ahead entry is the sole permission to resume a populated GT schema.
  gt_core_run systemctl start grafioschtrader.service || return 2
  while (( SECONDS < deadline )); do
    gt_app_verify; status=$?
    if (( status == 0 )); then
      gt_core_run systemctl enable grafioschtrader.service || return 2
      gt_core_mark step.app_start complete
      return $?
    fi
    (( status != 2 )) || return 2
    active=$(gt_core_run systemctl show --property=ActiveState --value grafioschtrader.service) || return 2
    [[ "$active" == active || "$active" == activating ]] || return 2
    printf '%s\n' 'Waiting for /api/gtinfo; diagnostics: /var/log/grafioschtrader.log'
    sleep 5
  done
  return 2
}

gt_install_app() {
  local reply step before after state_dir
  local completed_status
  completed_status=0
  gt_completed || completed_status=$?
  (( completed_status == 3 )) || return "$completed_status"
  state_dir=$(gt_path /var/lib/gt-install)
  gt_question_model
  if ! gt_state_load || ! gt_secrets_load; then gt_core_error 'Valid core journal and original secrets required.'; return 2; fi
  gt_no_symlinks "$state_dir/lock" || return 2
  if [[ -z "$LOCK_FD" ]]; then exec {LOCK_FD}<"$state_dir/lock" || return 2; fi
  flock -n "$LOCK_FD" || return 2
  gt_app_preflight || { gt_core_error 'Application preflight failed; no application changes made.'; return 2; }
  before=$(sha256sum "$state_dir/state")
  gt_text 'Application stage: install update scripts, sudoers (start/stop only), systemd and logrotate; build the pinned commit, start migrations, verify loopback HTTP and enable the service. Web/TLS remain pending.' \
    'Anwendungsstufe: Update-Skripte, sudoers (nur Start/Stopp), systemd und Logrotation; bestätigten Commit bauen, Migrationen starten, Loopback-HTTP prüfen und Dienst aktivieren. Web/TLS bleiben offen.'
  printf 'Commit: %s\nDocument root: %s/grafioschtrader\nTimezone: %s\n' "${STATE[planned_commit]}" "${ANSWER[DOCROOT]}" "${ANSWER[TIMEZONE]}"
  if [[ "$CORE_CONFIRM" != yes ]]; then
    { exec {QUESTION_FD}<>/dev/tty; } 2>/dev/null || return 2
    printf 'install-app: ' >&"$QUESTION_FD"
    IFS= read -r -u "$QUESTION_FD" reply && [[ "$reply" == install-app ]] || return 130
  fi
  after=$(sha256sum "$state_dir/state")
  [[ "$before" == "$after" ]] && gt_app_preflight || return 2
  gt_core_mark step.app running || return 2
  for step in scripts resources service cron build start; do
    printf 'Application step: %s\n' "$step"
    "gt_app_$step" || { gt_core_error "$step; inspect /var/lib/gt-install/app-build.log and /var/log/grafioschtrader.log, then resume --install-app. No automatic database rollback."; return 2; }
  done
  gt_core_mark step.app complete || return 2
  gt_text 'Application running; installation remains unfinished (web/TLS/mail verification pending).' \
    'Anwendung läuft; Installation bleibt unvollständig (Web/TLS/Mail-Prüfung offen).'
  return 10
}

# The LAN stage owns one server file and its enablement link. Foreign configurations
# are inspected but never rewritten; unsupported topologies fail before publication.
gt_nginx_inventory() {
  local lan=$1
  python3 - "$ROOT" "$lan" "$SCRATCH" "${FACT[web.names]:-}" <<'PY'
import glob, hashlib, ipaddress, pathlib, re, shlex, sys
root, lan, scratch, selected_names = sys.argv[1:]
files, servers = {}, []
own = '/etc/nginx/sites-enabled/grafioschtrader'
enabled = False
def parse(path, parents=()):
    global enabled
    if path in parents or len(parents) > 32:
        raise ValueError('recursive nginx include')
    data = pathlib.Path(root + path).read_text()
    files[path] = data
    lexer = shlex.shlex(data, posix=True, punctuation_chars='{};')
    lexer.whitespace_split = True
    tokens = []
    for token in lexer:
        tokens.extend(list(token) if re.fullmatch(r'[{};]+', token) else [token])
    def block(index, nested=False):
        nonlocal tokens
        global enabled
        nodes, words = [], []
        while index < len(tokens):
            token = tokens[index]; index += 1
            if token == '}':
                if words or not nested: raise ValueError('ambiguous nginx block')
                return nodes, index
            if token == '{':
                if not words: raise ValueError('missing block directive')
                children, index = block(index, True)
                nodes.append((words, children, path)); words = []
            elif token == ';':
                if not words: raise ValueError('empty directive')
                if words[0] == 'include':
                    if len(words) != 2 or '$' in words[1]: raise ValueError('dynamic include')
                    pattern = words[1] if words[1].startswith('/') else '/etc/nginx/' + words[1]
                    if pattern == '/etc/nginx/sites-enabled/*': enabled = True
                    for match in sorted(glob.glob(root + pattern)):
                        nodes.extend(parse(match[len(root):] if root else match, parents + (path,)))
                else: nodes.append((words, None, path))
                words = []
            else: words.append(token)
        if words or nested: raise ValueError('unterminated nginx directive')
        return nodes, index
    return block(0)[0]
try:
    tree = parse('/etc/nginx/nginx.conf')
    http = [children for words, children, _ in tree if words == ['http']]
    if len(http) != 1 or not enabled: raise ValueError('standard http sites-enabled include required')
    endpoints, has80, default80 = set(), False, False
    for words, children, source in http[0]:
        if words != ['server']: continue
        if source == own or (selected_names and source in (own+'-http', own+'-domain')): continue
        names, listens = [], []
        for directive, nested, _ in children:
            if directive[0] == 'server_name': names.extend(directive[1:])
            if directive[0] == 'listen': listens.append(directive[1:])
        if lan in names: raise ValueError('LAN address already belongs to another vhost')
        if set(names).intersection(selected_names.split()): raise ValueError('Domain already belongs to another vhost')
        if not names: names = ['gt-install-default.invalid']
        if any(not re.fullmatch(r'[a-zA-Z0-9_.-]+', name) for name in names):
            raise ValueError('wildcard, regex or dynamic server_name needs manual integration')
        for listen in listens or [['80']]:
            address = listen[0]
            if address.isdigit(): address = '0.0.0.0:' + address
            host, port = address.rsplit(':', 1)
            host = host.strip('[]')
            if host == '*': host = '0.0.0.0'
            ip = ipaddress.ip_address(host)
            if not port.isdigit() or not 1 <= int(port) <= 65535: raise ValueError('invalid port')
            if any(x not in ('default_server', 'ssl', 'http2', 'ipv6only=on') for x in listen[1:]):
                raise ValueError('unsupported listen options')
            if ip.version == 4 and port == '80':
                if host != '0.0.0.0': raise ValueError('address-specific port 80 needs manual integration')
                has80 = True
                default80 |= 'default_server' in listen
            connect = (lan if ip.version == 4 else '::1') if ip.is_unspecified else host
            scheme = 'https' if 'ssl' in listen else 'http'
            for name in names: endpoints.add((connect, port, scheme, name))
            if 'default_server' in listen:
                endpoints.add((connect, port, scheme, 'gt-install-default.invalid'))
    if has80 and not default80: raise ValueError('existing port 80 needs an explicit default_server')
    pathlib.Path(scratch, 'web-endpoints').write_text(''.join('\t'.join(e)+'\n' for e in sorted(endpoints)))
    digest = hashlib.sha256()
    for path, data in sorted(files.items()): digest.update((path+'\0'+data+'\0').encode())
    print(digest.hexdigest())
except (ValueError, OSError) as error:
    print('nginx inventory: '+str(error), file=sys.stderr)
    sys.exit(2)
PY
}

gt_nginx_test() {
  # nginx returns zero for some ignored/conflicting server names; warnings block too.
  gt_core_run nginx -t > "$SCRATCH/nginx-test.log" 2>&1 &&
    ! grep -Eq '\[(warn|emerg|alert|crit|error)\]' "$SCRATCH/nginx-test.log"
}

gt_nginx_statuses() {
  local address port scheme name status
  while IFS=$'\t' read -r address port scheme name; do
    [[ -n "$address" ]] || continue
    [[ "$address" != *:* ]] || address="[$address]"
    # Certificate ownership/validity is outside this LAN stage; compare existing
    # HTTPS sites using their real Host/SNI without requiring a public CA chain.
    status=$(curl --disable --noproxy '*' --silent --show-error --insecure --max-time 5 \
      --resolve "$name:$port:$address" -o /dev/null -w '%{http_code}' "$scheme://$name:$port/") || return 2
    [[ "$status" =~ ^[1-5][0-9][0-9]$ ]] || return 2
    printf '%s\t%s\t%s\t%s\t%s\n' "$address" "$port" "$scheme" "$name" "$status"
  done < "$SCRATCH/web-endpoints"
}

gt_nginx_render() {
  local route target
  cat <<EOF
# Managed by gt-install; LAN HTTP. Update through a reviewed installer stage.
server {
    listen 80;
    server_name ${FACT[web.lan]};
    root ${ANSWER[DOCROOT]};
    index index.html;
    client_max_body_size 50m;
    gzip on;
    gzip_types text/plain text/css text/xml application/javascript application/json application/wasm application/xml image/svg+xml;
    location = / { return 302 /grafioschtrader/; }
    location = /grafioschtrader { return 301 /grafioschtrader/; }
    location /grafioschtrader/ {
        try_files \$uri \$uri/ /grafioschtrader/index.html;
    }
    location / { return 404; }
EOF
  for route in /api /m2m /socket/websocket /ws; do
    target=$route; [[ "$route" != /socket/websocket ]] || target=/socket
    cat <<EOF
    location $route {
        proxy_pass http://127.0.0.1:${ANSWER[BACKEND_PORT]}$target;
        proxy_set_header Host \$host;
        proxy_set_header X-Real-IP \$remote_addr;
        proxy_set_header X-Forwarded-For \$remote_addr;
        proxy_set_header X-Forwarded-Proto \$scheme;
EOF
    if [[ "$route" == /ws || "$route" == /socket/websocket ]]; then
      cat <<'EOF'
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
EOF
    fi
    printf '    }\n'
  done
  printf '}\n'
}

gt_nginx_owned() {
  local target link digest
  target=$(gt_path /etc/nginx/sites-available/grafioschtrader)
  link=$(gt_path /etc/nginx/sites-enabled/grafioschtrader)
  gt_no_symlinks "$target" && gt_no_symlinks "${link%/*}" || return 2
  if [[ -e "$target" ]]; then
    digest=$(sha256sum "$target"); digest=${digest%% *}
    [[ -f "$target" && "$digest" == "${STATE[file.web_nginx]:-}" && "$(stat -c '%u:%a' "$target")" == 0:644 ]] || return 2
  fi
  if [[ -e "$link" || -L "$link" ]]; then
    [[ -L "$link" && "$(readlink "$link")" == "$target" && "${STATE[resource.web_link]:-}" == intent && -f "$target" ]] || return 2
  fi
}

gt_nginx_package_plan() {
  local transaction line
  transaction=$(LC_ALL=C apt-get --simulate --no-remove --no-upgrade install nginx 2>/dev/null) || return 2
  while IFS= read -r line; do
    [[ "$line" != 'Remv '* && ! "$line" =~ ^Inst\ [^\ ]+\ \[ ]] || return 2
  done <<< "$transaction"
  printf '%s\n' "$transaction" | sha256sum
}

gt_web_preflight() {
  local command address listeners line
  [[ "${STATE[step.app]:-}" == complete && "${ANSWER[WEBSERVER]:-}" == nginx && -z "${ANSWER[DOMAIN]:-}" ]] || {
    gt_core_error 'Complete --install-app first; --install-web currently requires nginx and LAN-only answers.'; return 2;
  }
  for command in nginx curl python3 ip ss systemctl; do
    [[ "$command" != nginx ]] || continue
    command -v "$command" >/dev/null || return 2
  done
  [[ "$(cat "$(gt_path /proc/1/comm)")" == systemd ]] || return 2
  gt_core_config_valid && gt_app_artifacts && gt_app_verify || return 2
  gt_validate_answer DOCROOT "${ANSWER[DOCROOT]}" && gt_validate_answer BACKEND_PORT "${ANSWER[BACKEND_PORT]}" || return 2
  address=$(ip -4 route get 1.1.1.1) || return 2
  address=$(awk '{for(i=1;i<NF;i++) if($i=="src") {print $(i+1); exit}}' <<< "$address")
  [[ "$address" == *.* && "$address" != 127.* && "$address" != 0.* ]] && gt_valid_address "$address" || return 2
  [[ -z "${STATE[resource.web_lan]:-}" || "${STATE[resource.web_lan]}" == "$address" ]] || {
    gt_core_error 'LAN address changed; review the owned vhost before continuing.'; return 2;
  }
  FACT[web.lan]=$address
  gt_nginx_owned || { gt_core_error 'Foreign or changed nginx target/link.'; return 2; }
  listeners=$(ss -Htlnp) || return 2
  while IFS= read -r line; do
    [[ "$line" == *'"nginx"'* ]] || { gt_core_error 'Port 80 belongs to another process.'; return 2; }
  done < <(awk '$4 ~ /:80$/ {print}' <<< "$listeners")
  if command -v nginx >/dev/null; then
    # Use the distribution service/configuration contract, not a custom nginx prefix.
    nginx -V 2>&1 | grep -q -- '--conf-path=/etc/nginx/nginx.conf' || return 2
    gt_nginx_test || { gt_core_error 'nginx -t failed or warned; inspect nginx configuration.'; return 2; }
    FACT[web.snapshot]=$(gt_nginx_inventory "$address") || return 2
    gt_core_run systemctl is-active --quiet nginx.service || {
      gt_core_error 'Existing nginx must be running before shared-site comparisons.'; return 2;
    }
    gt_nginx_statuses > "$SCRATCH/web-before" || return 2
    FACT[web.package]=present
  else
    [[ ! -e "$(gt_path /etc/nginx)" ]] || return 2
    FACT[web.package]=$(gt_nginx_package_plan) || return 2
    FACT[web.snapshot]=absent
  fi
}

gt_web_verify() {
  local base=${1:-http://${FACT[web.lan]}} asset type
  local -a resolve=()
  [[ -z "${2:-}" ]] || resolve=(--resolve "$2")
  if [[ "${ANSWER[TLS_SOURCE]:-}" == proxy && "$base" == "http://${ANSWER[DOMAIN]}:"* ]]; then
    resolve+=(-H 'X-Forwarded-Proto: https')
  fi
  curl --disable --noproxy '*' -fsS --max-time 10 "${resolve[@]}" "$base/api/gtinfo" > "$SCRATCH/web-info" || return 2
  python3 -c 'import json,sys; d=json.load(open(sys.argv[1])); sys.exit(d.get("databaseName") != "grafioschtrader" or d.get("activeProfile") not in ("", "production"))' "$SCRATCH/web-info" || return 2
  curl --disable --noproxy '*' -fsS --max-time 10 "${resolve[@]}" "$base/grafioschtrader/" > "$SCRATCH/web-index" || return 2
  cmp -s "$SCRATCH/web-index" "$(gt_path "${ANSWER[DOCROOT]}/grafioschtrader/index.html")" || return 2
  asset=$(python3 - "$SCRATCH/web-index" <<'PY'
from html.parser import HTMLParser
import re, sys
class Index(HTMLParser):
    base = False
    scripts = []
    def handle_starttag(self, tag, attrs):
        attrs = dict(attrs)
        if tag == 'base': self.base = attrs.get('href') == '/grafioschtrader/'
        if tag == 'script' and attrs.get('src'): self.scripts.append(attrs['src'])
p = Index(); p.feed(open(sys.argv[1]).read())
assets = [s for s in p.scripts if re.fullmatch(r'(?:/grafioschtrader/)?[a-zA-Z0-9_.-]+\.js', s)]
if not p.base or not assets: sys.exit(2)
print(assets[0] if assets[0].startswith('/') else '/grafioschtrader/' + assets[0])
PY
  ) || return 2
  type=$(curl --disable --noproxy '*' -fsS --max-time 10 "${resolve[@]}" -o "$SCRATCH/web-script" -w '%{content_type}' "$base$asset") || return 2
  [[ "$type" == application/javascript* || "$type" == text/javascript* ]] && [[ -s "$SCRATCH/web-script" ]] || return 2
  cmp -s "$SCRATCH/web-script" "$(gt_path "${ANSWER[DOCROOT]}$asset")" || return 2
  curl --disable --noproxy '*' -fsS --max-time 10 "${resolve[@]}" "$base/grafioschtrader/login" > "$SCRATCH/web-nested" || return 2
  cmp -s "$SCRATCH/web-index" "$SCRATCH/web-nested"
}

gt_web_rollback() {
  local link
  gt_nginx_owned || return 2
  link=$(gt_path /etc/nginx/sites-enabled/grafioschtrader)
  [[ ! -L "$link" ]] || rm -- "$link" || return 2
  gt_nginx_test && gt_core_run systemctl reload nginx.service || return 2
  gt_core_mark step.web failed
}

gt_web_activate() {
  local target link attempt baseline endpoints
  target=$(gt_path /etc/nginx/sites-available/grafioschtrader)
  link=$(gt_path /etc/nginx/sites-enabled/grafioschtrader)
  baseline=$(gt_path /var/lib/gt-install/web-before)
  endpoints=$(gt_path /var/lib/gt-install/web-endpoints)
  # Persist the original comparison before enabling the site. A restart must not
  # accept an already changed foreign-site response as its new baseline.
  gt_app_root_file web_endpoints "$SCRATCH/web-endpoints" "$endpoints" 600 || return 2
  if [[ ! -e "$baseline" ]]; then
    gt_app_root_file web_before "$SCRATCH/web-before" "$baseline" 600 || return 2
  else
    gt_app_root_file web_before "$baseline" "$baseline" 600 || return 2
    cp "$baseline" "$SCRATCH/web-before" || return 2
  fi
  gt_core_mark step.web running && gt_core_mark resource.web_lan "${FACT[web.lan]}" || return 2
  gt_nginx_render > "$SCRATCH/nginx-site"
  gt_app_root_file web_nginx "$SCRATCH/nginx-site" "$target" 644 || return 2
  gt_core_mark resource.web_link intent || return 2
  if [[ ! -L "$link" ]]; then ln -s "$target" "$link" || return 2; fi
  if gt_nginx_test && gt_core_run systemctl reload nginx.service; then
    # Reload is asynchronous: wait for new workers before testing the new host.
    for ((attempt=0; attempt<10; attempt++)); do
      if gt_web_verify; then
        if gt_nginx_statuses > "$SCRATCH/web-after" && cmp -s "$SCRATCH/web-before" "$SCRATCH/web-after"; then
          gt_core_run systemctl enable nginx.service && gt_core_mark step.web complete && return 0
        fi
        break
      fi
      sleep 1
    done
  fi
  gt_web_rollback || { gt_core_error 'nginx recovery failed; inspect nginx -t and the owned enablement link.'; return 2; }
  gt_core_error 'Web verification failed; own vhost disabled and previous configuration reloaded. Resume --install-web after diagnosis.'
  return 2
}

gt_install_web() {
  local state_dir before after reply package
  local completed_status
  completed_status=0
  gt_completed || completed_status=$?
  (( completed_status == 3 )) || return "$completed_status"
  state_dir=$(gt_path /var/lib/gt-install)
  gt_question_model
  gt_state_load && gt_secrets_load || return 2
  gt_stage_preflight || return 2
  gt_no_symlinks "$state_dir/lock" || return 2
  if [[ -z "$LOCK_FD" ]]; then exec {LOCK_FD}<"$state_dir/lock" || return 2; fi
  flock -n "$LOCK_FD" || return 2
  if [[ "${ANSWER[WEBSERVER]:-}" == apache2 || -n "${ANSWER[DOMAIN]:-}" ]]; then
    gt_install_extended_web; return $?
  fi
  gt_web_preflight || { gt_core_error 'Web preflight failed; no web changes made.'; return 2; }
  before="$(sha256sum "$state_dir/state"):${FACT[web.snapshot]}:${FACT[web.package]}:${FACT[web.lan]}"
  gt_text 'LAN stage: install nginx if absent; add an owned HTTP vhost, verify frontend/API and existing sites, enable nginx at boot. Firewall unchanged.' \
    'LAN-Stufe: nginx bei Bedarf installieren; eigenen HTTP-Vhost ergänzen, Frontend/API und bestehende Sites prüfen, nginx beim Boot aktivieren. Firewall unverändert.'
  printf 'URL: http://%s/grafioschtrader/\nDocument root: %s\n' "${FACT[web.lan]}" "${ANSWER[DOCROOT]}"
  if [[ "$CORE_CONFIRM" != yes ]]; then
    { exec {QUESTION_FD}<>/dev/tty; } 2>/dev/null || return 2
    printf 'install-web: ' >&"$QUESTION_FD"
    IFS= read -r -u "$QUESTION_FD" reply && [[ "$reply" == install-web ]] || return 130
  fi
  gt_web_preflight || return 2
  after="$(sha256sum "$state_dir/state"):${FACT[web.snapshot]}:${FACT[web.package]}:${FACT[web.lan]}"
  [[ "$before" == "$after" ]] || { gt_core_error 'Web inventory changed; review a fresh plan.'; return 2; }
  if [[ "${FACT[web.package]}" != present ]]; then
    package=$(gt_nginx_package_plan) || return 2
    [[ "$package" == "${FACT[web.package]}" ]] || return 2
    gt_core_mark resource.web_package intent || return 2
    gt_core_run env DEBIAN_FRONTEND=noninteractive apt-get -y --no-remove --no-upgrade \
      -o DPkg::Lock::Timeout=600 install nginx || return 2
    gt_core_run systemctl start nginx.service || return 2
    gt_web_preflight || return 2
  fi
  if [[ "${STATE[step.web]:-}" == complete ]]; then
    [[ -L "$(gt_path /etc/nginx/sites-enabled/grafioschtrader)" ]] && gt_web_verify || return 2
    gt_core_run systemctl is-enabled --quiet nginx.service || return 2
  else gt_web_activate || return 2; fi
  gt_text 'LAN web access verified. Installation remains unfinished: mail verification and final hand-over are pending.' \
    'LAN-Webzugriff geprüft. Installation bleibt unvollständig: Mail-Prüfung und abschließende Übergabe stehen aus.'
  return 10
}
gt_site_path() {
  local suffix='' extension=''
  [[ "$1" == lan ]] || suffix="-$1"
  [[ "${ANSWER[WEBSERVER]}" != apache2 ]] || extension=.conf
  gt_path "/etc/${ANSWER[WEBSERVER]}/sites-available/grafioschtrader$suffix$extension"
}

gt_site_owned() {
  local id target link digest
  for id in lan http domain; do
    target=$(gt_site_path "$id"); link=${target/sites-available/sites-enabled}
    gt_no_symlinks "$target" && gt_no_symlinks "${link%/*}" || return 2
    if [[ -e "$target" ]]; then
      digest=$(sha256sum "$target"); digest=${digest%% *}
      [[ -f "$target" && "$digest" == "${STATE[file.site_$id]:-}" && "$(stat -c '%u:%a' "$target")" == 0:644 ]] || return 2
    fi
    if [[ -e "$link" || -L "$link" ]]; then
      [[ -L "$link" && "$(readlink "$link")" == "$target" && "${STATE[resource.site_$id]:-}" == intent && -f "$target" ]] || return 2
    fi
  done
  if [[ "${ANSWER[WEBSERVER]}" == apache2 ]]; then
    target=$(gt_path /etc/apache2/conf-enabled/grafioschtrader-listen.conf)
    gt_no_symlinks "$target" || return 2
    if [[ -e "$target" ]]; then
      digest=$(sha256sum "$target"); digest=${digest%% *}
      [[ -f "$target" && "$digest" == "${STATE[file.apache_listen]:-}" && "$(stat -c '%u:%a' "$target")" == 0:644 ]] || return 2
    fi
  fi
}

gt_site_link() {
  local target link
  target=$(gt_site_path "$1"); link=${target/sites-available/sites-enabled}
  gt_site_owned || return 2
  if [[ "$2" == on ]]; then
    gt_core_mark "resource.site_$1" intent || return 2
    [[ -L "$link" ]] || ln -s "$target" "$link" || return 2
  elif [[ -L "$link" ]]; then rm -- "$link" || return 2; fi
  sync -f "${link%/*}"
}

gt_site_test() {
  if [[ "${ANSWER[WEBSERVER]}" == nginx ]]; then gt_nginx_test
  else gt_core_run apache2ctl configtest > "$SCRATCH/apache-test.log" 2>&1; fi
}

gt_apache_inventory() {
  gt_core_run apache2ctl -t -D DUMP_VHOSTS > "$SCRATCH/apache-vhosts" 2> "$SCRATCH/apache-dump.log" || return 2
  # Apache itself resolves conditional/includes. DUMP_INCLUDES provides the files
  # actually consumed, so the approval snapshot includes configurations outside /etc.
  gt_core_run apache2ctl -t -D DUMP_INCLUDES > "$SCRATCH/apache-includes" 2>> "$SCRATCH/apache-dump.log" || return 2
  python3 - "$SCRATCH" "${FACT[web.lan]}" "${FACT[web.names]:-}" <<'PY'
import hashlib, ipaddress, pathlib, re, subprocess, sys
scratch, lan, names = sys.argv[1:]
selected = {lan, *names.split()}
owned = {'/etc/apache2/sites-enabled/grafioschtrader'+s+'.conf' for s in ('', '-http', '-domain')}
endpoints, binding, current = set(), None, None
stock_marker = pathlib.Path(scratch, 'apache-stock-default')
stock_marker.unlink(missing_ok=True)
def endpoint(bind, name, source, default=False):
    if source in owned: return
    stock = False
    try: implicit_address = bool(ipaddress.ip_address(name))
    except ValueError: implicit_address = False
    if implicit_address and source == '/etc/apache2/sites-enabled/000-default.conf':
        path = pathlib.Path(source).resolve()
        data = path.read_bytes()
        conffiles = subprocess.check_output(['dpkg-query', '-W', '-f=${Conffiles}', 'apache2'], text=True)
        stock = (str(path)+' '+hashlib.md5(data).hexdigest()) in conffiles and not re.search(rb'(?mi)^\s*Server(?:Name|Alias)\b', data)
        foreign = {str(p) for p in pathlib.Path('/etc/apache2/sites-enabled').glob('*.conf')} - owned
        stock = stock and foreign == {source}
        if stock:
            stock_marker.write_text('stock\n')
            return
    if name in selected and not stock: raise ValueError('Selected name already belongs to an Apache vhost')
    if not re.fullmatch(r'[a-zA-Z0-9_.-]+', name): raise ValueError('Unsupported Apache server name')
    host, port = bind.rsplit(':', 1)
    if host not in ('*', '0.0.0.0', '[::]'): raise ValueError('Address-specific Apache vhost requires manual integration')
    if not port.isdigit(): raise ValueError('Unsupported Apache port')
    # The stage supports the conventional HTTP/HTTPS ports on foreign sites.
    if port not in ('80', '443'): raise ValueError('Foreign nonstandard Apache port requires manual integration')
    scheme = 'https' if port == '443' else 'http'
    if not stock: endpoints.add((lan, port, scheme, name))
    if default: endpoints.add((lan, port, scheme, 'gt-install-default.invalid'))
try:
    for line in pathlib.Path(scratch, 'apache-vhosts').read_text().splitlines():
        match = re.match(r'^(\S+:\d+)\s+is a NameVirtualHost', line)
        if match: binding = match[1]; continue
        match = re.match(r'^\s*(?:(\S+:\d+)\s+|(?:port (\d+) namevhost|default server)\s+)(\S+)\s+\((/[^()]+):(\d+)\)', line)
        if match:
            bind = match[1] or binding
            if not bind: raise ValueError('Missing Apache binding')
            name, source = match.group(3), match.group(4); current = (bind, source)
            endpoint(bind, name, source, 'default server' in line or bool(match[1]))
            continue
        match = re.match(r'^\s+alias (\S+)', line)
        if match:
            if not current: raise ValueError('Unassigned Apache alias')
            endpoint(current[0], match[1], current[1]); continue
        if line.strip() and line.strip() != 'VirtualHost configuration:':
            raise ValueError('Unrecognized Apache vhost dump')
    paths = []
    for line in pathlib.Path(scratch, 'apache-includes').read_text().splitlines():
        match = re.match(r'^\s*\([^)]*\)\s+(/.+)$', line)
        if match: paths.append(match[1])
        elif line.strip() != 'Included configuration files:': raise ValueError('Unrecognized Apache include dump')
    if '/etc/apache2/apache2.conf' not in paths: raise ValueError('Distribution Apache configuration required')
    digest = hashlib.sha256()
    for path in sorted(set(paths)):
        digest.update(path.encode()+b'\0'+pathlib.Path(path).read_bytes()+b'\0')
    pathlib.Path(scratch, 'web-endpoints').write_text(''.join('\t'.join(e)+'\n' for e in sorted(endpoints)))
    print(digest.hexdigest())
except (OSError, ValueError) as error:
    print('Apache inventory: '+str(error), file=sys.stderr); sys.exit(2)
PY
}

gt_site_inventory() {
  if [[ "${ANSWER[WEBSERVER]}" == nginx ]]; then gt_nginx_inventory "${FACT[web.lan]}"
  else gt_apache_inventory; fi
}

gt_apache_routes() {
  local scheme=${1:-http} port=${ANSWER[BACKEND_PORT]} http=${ANSWER[BACKEND_HTTP_PORT]}
  cat <<EOF
    DocumentRoot ${ANSWER[DOCROOT]}
    ProxyRequests Off
    ProxyPreserveHost On
    ProxyAddHeaders On
    LimitRequestBody 52428800
    RequestHeader set X-Real-IP "expr=%{REMOTE_ADDR}"
EOF
  [[ "$scheme" == proxy ]] || printf '    RequestHeader set X-Forwarded-For "expr=%%{REMOTE_ADDR}"\n'
  [[ "$scheme" == proxy ]] || printf '    RequestHeader set X-Forwarded-Proto "%s"\n' "$scheme"
  cat <<EOF
    ProxyPass /socket/websocket ws://127.0.0.1:$http/socket
    ProxyPass /ws ws://127.0.0.1:$http/ws
    ProxyPass /api ajp://127.0.0.1:$port/api
    ProxyPass /m2m ajp://127.0.0.1:$port/m2m
    RedirectMatch 302 ^/$ /grafioschtrader/
    RedirectMatch 301 ^/grafioschtrader$ /grafioschtrader/
    <Directory ${ANSWER[DOCROOT]}>
        Options -Indexes
        AllowOverride None
        Require all denied
    </Directory>
    <Directory ${ANSWER[DOCROOT]}/grafioschtrader>
        Require all granted
        DirectoryIndex index.html
        FallbackResource /grafioschtrader/index.html
        AddOutputFilterByType DEFLATE text/plain text/html text/css text/xml application/javascript application/json application/wasm application/xml image/svg+xml
    </Directory>
EOF
}

# nginx variables and Apache regex backreferences are emitted literally.
# shellcheck disable=SC2016
gt_domain_render() {
  local phase=$1 names=${FACT[web.names]} name=${ANSWER[DOMAIN]} port=80 route target proto='$scheme'
  local cert=${FACT[tls.cert]:-} key=${FACT[tls.key]:-} web=${ANSWER[WEBSERVER]}
  if [[ "$phase" == proxy ]]; then port=${ANSWER[TLS_PROXY_LISTEN]}; proto='$http_x_forwarded_proto'; fi
  if [[ "$web" == nginx ]]; then
    if [[ "$phase" == tls ]]; then
      printf 'server { listen 80; server_name %s;\n' "$names"
      [[ "${ANSWER[DNS_FAMILY]}" == ipv4 ]] || printf '    listen [::]:80;\n'
      printf '    location /.well-known/acme-challenge/ { root /var/lib/gt-install-acme; }\n'
      printf '    location / { return 301 https://%s$request_uri; }\n}\n' "$name"
      port=443
    fi
    printf 'server {\n    listen %s%s;\n    server_name %s;\n' "$port" "$([[ "$phase" != tls ]] || printf ' ssl')" "$names"
    [[ "${ANSWER[DNS_FAMILY]:-ipv4}" == ipv4 || "$phase" == proxy ]] || printf '    listen [::]:%s%s;\n' "$port" "$([[ "$phase" != tls ]] || printf ' ssl')"
    [[ "$phase" != tls ]] || printf '    ssl_certificate %s;\n    ssl_certificate_key %s;\n    ssl_protocols TLSv1.2 TLSv1.3;\n' "$cert" "$key"
    if [[ "$phase" == proxy && -n "${ANSWER[TLS_PROXY_FROM]:-}" ]]; then
      printf '    allow 127.0.0.1;\n    allow %s;\n    deny all;\n' "${ANSWER[TLS_PROXY_FROM]}"
    fi
    printf '    root %s;\n    index index.html;\n    client_max_body_size 50m;\n    gzip on;\n' "${ANSWER[DOCROOT]}"
    printf '    gzip_types text/plain text/css text/xml application/javascript application/json application/wasm application/xml image/svg+xml;\n'
    cat <<'EOF'
    location /.well-known/acme-challenge/ { root /var/lib/gt-install-acme; }
    location = / { return 302 /grafioschtrader/; }
    location = /grafioschtrader { return 301 /grafioschtrader/; }
    location /grafioschtrader/ { try_files $uri $uri/ /grafioschtrader/index.html; }
    location / { return 404; }
EOF
    for route in /api /m2m /socket/websocket /ws; do
      target=$route; [[ "$route" != /socket/websocket ]] || target=/socket
      printf '    location %s {\n        proxy_pass http://127.0.0.1:%s%s;\n' "$route" "${ANSWER[BACKEND_PORT]}" "$target"
      printf '        proxy_set_header Host $host;\n        proxy_set_header X-Real-IP $remote_addr;\n'
      if [[ "$phase" == proxy ]]; then
        printf '        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;\n'
      else
        printf '        proxy_set_header X-Forwarded-For $remote_addr;\n'
      fi
      printf '        proxy_set_header X-Forwarded-Proto %s;\n' "$proto"
      if [[ "$route" == /ws || "$route" == /socket/websocket ]]; then
        printf '        proxy_http_version 1.1;\n        proxy_set_header Upgrade $http_upgrade;\n        proxy_set_header Connection "upgrade";\n'
      fi
      printf '    }\n'
    done
    printf '}\n'
  else
    if [[ "$phase" == tls ]]; then
      printf '<VirtualHost *:80>\n    ServerName %s\n' "$name"
      for name in $names; do [[ "$name" == "${ANSWER[DOMAIN]}" ]] || printf '    ServerAlias %s\n' "$name"; done
      printf '    Alias /.well-known/acme-challenge/ /var/lib/gt-install-acme/.well-known/acme-challenge/\n'
      printf '    <Directory /var/lib/gt-install-acme>\n        Require all granted\n    </Directory>\n'
      printf '    RedirectMatch 301 ^/(?!\.well-known/acme-challenge/)(.*)$ https://%s/$1\n</VirtualHost>\n' "${ANSWER[DOMAIN]}"
      port=443
    fi
    printf '<VirtualHost *:%s>\n    ServerName %s\n' "$port" "${ANSWER[DOMAIN]}"
    for name in $names; do [[ "$name" == "${ANSWER[DOMAIN]}" ]] || printf '    ServerAlias %s\n' "$name"; done
    [[ "$phase" != tls ]] || printf '    SSLEngine on\n    SSLCertificateFile %s\n    SSLCertificateKeyFile %s\n    SSLProtocol -all +TLSv1.2 +TLSv1.3\n' "$cert" "$key"
    if [[ "$phase" == proxy && -n "${ANSWER[TLS_PROXY_FROM]:-}" ]]; then
      printf '    <Location />\n        Require ip 127.0.0.1 %s\n    </Location>\n' "${ANSWER[TLS_PROXY_FROM]}"
    fi
    printf '    Alias /.well-known/acme-challenge/ /var/lib/gt-install-acme/.well-known/acme-challenge/\n'
    printf '    <Directory /var/lib/gt-install-acme>\n        Require all granted\n    </Directory>\n'
    proto=http; [[ "$phase" != tls ]] || proto=https; [[ "$phase" != proxy ]] || proto=proxy
    gt_apache_routes "$proto"
    printf '</VirtualHost>\n'
  fi
}

gt_site_render_lan() {
  if [[ "${ANSWER[WEBSERVER]}" == nginx ]]; then gt_nginx_render
  else
    printf '<VirtualHost *:80>\n    ServerName %s\n' "${FACT[web.lan]}"
    gt_apache_routes http
    printf '</VirtualHost>\n'
  fi
}

gt_extended_packages() {
  local line transaction
  local -a packages=()
  read -r -a packages <<< "${FACT[web.packages]}"
  transaction=$(LC_ALL=C apt-get --simulate --no-remove --no-upgrade install "${packages[@]}" 2>/dev/null) || return 2
  while IFS= read -r line; do [[ "$line" != 'Remv '* && ! "$line" =~ ^Inst\ [^\ ]+\ \[ ]] || return 2; done <<< "$transaction"
  printf '%s\n' "$transaction" | sha256sum
}

gt_domain_plan() {
  local field
  PLAN=() PLAN_BLOCKERS=() PLAN_WARNINGS=()
  gt_stage_preflight || return 2
  FACT[web.names]=${ANSWER[DOMAIN]:-}
  [[ -n "${ANSWER[DOMAIN]:-}" ]] || return 0
  for field in DOMAIN DNS_FAMILY TLS_SOURCE; do
    gt_validate_answer "$field" "${ANSWER[$field]:-}" || { gt_core_error "Invalid/missing answer: $field"; return 2; }
  done
  if [[ "${ANSWER[TLS_SOURCE]}" != proxy ]]; then
    gt_domain_network || { gt_core_error 'DNS check: network inventory failed.'; return 2; }
    gt_plan_dns
    FACT[web.names]=${FACT[plan.names]}
  fi
  if [[ -n "${STATE[resource.web_names]:-}" ]]; then
    [[ "${STATE[resource.web_names]}" == "${FACT[web.names]}" ]] || { gt_core_error 'DNS certificate-name set changed; restore the recorded DNS names before resuming.'; return 2; }
  fi
  case "${ANSWER[TLS_SOURCE]}" in
    existing)
      for field in TLS_CERT TLS_KEY; do
        gt_validate_answer "$field" "${ANSWER[$field]:-}" || { gt_core_error "Invalid/missing answer: $field"; return 2; }
      done
      FACT[tls.cert]=${ANSWER[TLS_CERT]} FACT[tls.key]=${ANSWER[TLS_KEY]}
      gt_plan_certificate ;;
    letsencrypt)
      gt_validate_answer LETSENCRYPT_EMAIL "${ANSWER[LETSENCRYPT_EMAIL]:-}" || {
        gt_core_error 'Invalid/missing answer: LETSENCRYPT_EMAIL'; return 2;
      }
      gt_certbot_plan ;;
    proxy)
      for field in TLS_PROXY_LISTEN TLS_PROXY_FROM; do
        gt_validate_answer "$field" "${ANSWER[$field]:-}" || { gt_core_error "Invalid/missing answer: $field"; return 2; }
      done
      ;;
  esac
  gt_report_rows "$(gt_text 'Domain/TLS checks' 'Domain-/TLS-Prüfungen')" "${PLAN[@]}"
  gt_report_rows "$(gt_text Warnings Hinweise)" "${PLAN_WARNINGS[@]}"
  gt_report_rows "$(gt_text Blockers Blocker)" "${PLAN_BLOCKERS[@]}"
  (( ${#PLAN_BLOCKERS[@]} == 0 ))
}

gt_domain_network() {
  local value interface
  value=$(gt_probe curl --disable -4 -fsS --connect-timeout 4 --max-time 8 https://ifconfig.co/ip) || value=unknown
  [[ "$value" =~ ^([0-9]{1,3}\.){3}[0-9]{1,3}$ ]] || value=unknown
  FACT[network.public_ipv4]=$value
  value=$(gt_probe ip -6 route show default) || value=''
  interface=$(awk '{for(i=1;i<NF;i++) if($i=="dev") {print $(i+1); exit}}' <<< "$value")
  FACT[network.global_ipv6]=unknown
  if [[ "$interface" =~ ^[a-zA-Z0-9_.:-]+$ ]]; then
    value=$(gt_probe ip -6 addr show dev "$interface" scope global -temporary -deprecated) || return 2
    FACT[network.global_ipv6]=$(awk '$1=="inet6" && $2!~/^(f[cd]|fe[89ab])/ {sub(/\/.*/,"",$2); print $2}' <<< "$value")
  fi
}

gt_apache_modules() {
  local phase=$1 file before after
  local -a modules=()
  mapfile -t modules < <(gt_apache_module_names "$phase")
  (( ${#modules[@]} )) || return 2
  before=$(gt_path "/var/lib/gt-install/apache-$phase-before")
  after=$(gt_path "/var/lib/gt-install/apache-$phase-after")
  gt_no_symlinks "$(gt_path /etc/apache2/mods-enabled)" || return 2
  find "$(gt_path /etc/apache2/mods-enabled)" -maxdepth 1 -type l -printf '%f\t%l\n' | LC_ALL=C sort > "$SCRATCH/modules"
  if [[ ! -e "$before" ]]; then gt_app_root_file "modules_${phase}_before" "$SCRATCH/modules" "$before" 600 || return 2
  else gt_app_root_file "modules_${phase}_before" "$before" "$before" 600 || return 2; fi
  for file in "${modules[@]}"; do gt_core_run a2enmod "$file" >/dev/null || return 2; done
  find "$(gt_path /etc/apache2/mods-enabled)" -maxdepth 1 -type l -printf '%f\t%l\n' | LC_ALL=C sort > "$SCRATCH/modules"
  gt_app_root_file "modules_${phase}_after" "$SCRATCH/modules" "$after" 600
}

gt_apache_modules_restore() {
  local phase=$1 before after
  before=$(gt_path "/var/lib/gt-install/apache-$phase-before")
  after=$(gt_path "/var/lib/gt-install/apache-$phase-after")
  gt_app_root_file "modules_${phase}_before" "$before" "$before" 600 &&
    gt_app_root_file "modules_${phase}_after" "$after" "$after" 600 || return 2
  python3 - "$(gt_path /etc/apache2/mods-enabled)" "$before" "$after" <<'PY'
import pathlib, sys
directory = pathlib.Path(sys.argv[1])
def read(path): return dict(line.split('\t', 1) for line in pathlib.Path(path).read_text().splitlines())
before, after = read(sys.argv[2]), read(sys.argv[3])
current = {p.name: str(p.readlink()) for p in directory.iterdir() if p.is_symlink()}
if current != after: sys.exit(2)
for name in after.keys() - before.keys():
    if '/' in name or name in ('.', '..'): sys.exit(2)
    (directory / name).unlink()
PY
}

gt_extended_preflight() {
  local command address line ports='80' web=${ANSWER[WEBSERVER]} executable
  executable=$web
  [[ "${STATE[step.app]:-}" == complete && ( "$web" == nginx || "$web" == apache2 ) ]] || return 2
  [[ "$(cat "$(gt_path /proc/1/comm)")" == systemd ]] || return 2
  for command in curl python3 ip ss systemctl openssl; do command -v "$command" >/dev/null || return 2; done
  gt_core_config_valid && gt_app_artifacts && gt_app_verify || return 2
  gt_validate_answer DOCROOT "${ANSWER[DOCROOT]}" && gt_validate_answer BACKEND_PORT "${ANSWER[BACKEND_PORT]}" || return 2
  [[ "$web" != apache2 ]] || gt_validate_answer BACKEND_HTTP_PORT "${ANSWER[BACKEND_HTTP_PORT]:-}" || return 2
  address=$(ip -4 route get 1.1.1.1) || return 2
  address=$(awk '{for(i=1;i<NF;i++) if($i=="src") {print $(i+1); exit}}' <<< "$address")
  [[ "$address" == *.* && "$address" != 127.* && "$address" != 0.* ]] && gt_valid_address "$address" || return 2
  FACT[web.lan]=$address
  [[ -z "${STATE[resource.web_lan]:-}" || "${STATE[resource.web_lan]}" == "$address" ]] || return 2
  gt_domain_plan && gt_site_owned || return 2
  if [[ -n "${ANSWER[DOMAIN]:-}" ]]; then
    if [[ "${ANSWER[TLS_SOURCE]}" == proxy ]]; then ports+=" ${ANSWER[TLS_PROXY_LISTEN]}"; else ports+=' 443'; fi
  fi
  address=$(ss -Htlnp) || return 2
  while IFS= read -r line; do [[ "$line" == *"\"$web\""* ]] || { gt_core_error 'A required web port belongs to another process.'; return 2; }; done < <(
    awk -v ports="$ports" 'BEGIN {split(ports,p," ")} {for(i in p) if($4 ~ (":" p[i] "$")) print}' <<< "$address")
  [[ "$web" != apache2 ]] || executable=apache2ctl
  FACT[web.packages]=$(gt_web_package_names | paste -sd ' ')
  FACT[web.transaction]=$(gt_extended_packages) || return 2
  if command -v "$executable" >/dev/null; then
    gt_site_test || return 2
    FACT[web.snapshot]=$(gt_site_inventory) || return 2
    gt_core_run systemctl is-active --quiet "$web.service" || { gt_core_error 'Existing web server must be running for shared-site checks.'; return 2; }
    gt_nginx_statuses > "$SCRATCH/web-before" || return 2
  else
    [[ ! -e "$(gt_path "/etc/$web")" ]] || return 2
    FACT[web.snapshot]=absent
  fi
}

# Save shared-site evidence once per installation, before any link is enabled.
gt_site_baseline() {
  local file target
  for file in web-endpoints web-before; do
    target=$(gt_path "/var/lib/gt-install/extended-$file")
    if [[ -e "$target" ]]; then
      gt_app_root_file "extended_$file" "$target" "$target" 600 || return 2
      [[ "$file" != web-endpoints ]] || cmp -s "$target" "$SCRATCH/$file" || return 2
      cp "$target" "$SCRATCH/$file" || return 2
    else gt_app_root_file "extended_$file" "$SCRATCH/$file" "$target" 600 || return 2; fi
  done
}

gt_site_compare() {
  local snapshot
  cp "$SCRATCH/web-endpoints" "$SCRATCH/expected-endpoints" || return 2
  snapshot=$(gt_site_inventory) || return 2
  [[ -n "$snapshot" ]] && cmp -s "$SCRATCH/expected-endpoints" "$SCRATCH/web-endpoints" || return 2
  gt_nginx_statuses > "$SCRATCH/web-after" && cmp -s "$SCRATCH/web-before" "$SCRATCH/web-after"
}

gt_site_activate() {
  local id=$1 base=$2 host_resolution=${3:-} target link attempt old_http=no
  target=$(gt_site_path "$id")
  gt_app_root_file "site_$id" "$SCRATCH/site-$id" "$target" 644 || return 2
  gt_core_mark "step.site_$id" running || return 2
  if [[ "$id" == domain ]]; then
    link=$(gt_site_path http); link=${link/sites-available/sites-enabled}
    [[ ! -L "$link" ]] || old_http=yes
    # Persist the restoration choice before removing the HTTP bootstrap link.
    [[ -n "${STATE[resource.domain_previous_http]:-}" ]] || gt_core_mark resource.domain_previous_http "$old_http" || return 2
    gt_site_link http off || return 2
  fi
  gt_site_link "$id" on || return 2
  if gt_site_test && gt_core_run systemctl reload "${ANSWER[WEBSERVER]}.service"; then
    for ((attempt=0; attempt<10; attempt++)); do
      if gt_web_verify "$base" "$host_resolution"; then
        if gt_site_compare; then gt_core_mark "step.site_$id" complete; return $?; fi
        break
      fi
      sleep 1
    done
  fi
  gt_site_link "$id" off || return 2
  if [[ "$id" == domain && "${STATE[resource.domain_previous_http]:-}" == yes ]]; then gt_site_link http on || return 2; fi
  if ! gt_site_test || ! gt_core_run systemctl reload "${ANSWER[WEBSERVER]}.service"; then
    gt_core_error 'Web rollback reload failed; inspect the web server log.'; return 2
  fi
  gt_core_mark "step.site_$id" failed || return 2
  gt_core_error "Site $id failed verification; previous site links restored. Resume --install-web."
  return 2
}

gt_tls_certbot() { gt_core_run certbot "$@"; }

gt_tls_issue() {
  local path name cert_name="gt-install-${STATE[run_id]}" log
  local -a names=()
  if [[ "${FACT[tls.reuse]:-no}" == yes ]]; then
    gt_core_mark step.tls reused
    return $?
  fi
  for name in ${FACT[web.names]}; do names+=(-d "$name"); done
  path=$(gt_path /var/lib/gt-install-acme)
  gt_no_symlinks "$path" || return 2
  if [[ -e "$path" ]]; then [[ "${STATE[resource.acme_root]:-}" == intent && "$(stat -c '%u:%a' "$path")" == 0:755 ]] || return 2
  else
    gt_core_mark resource.acme_root intent || return 2
    install -d -o root -g root -m 755 "$path" || return 2
  fi
  if [[ -e "/etc/letsencrypt/renewal/$cert_name.conf" && "${STATE[resource.acme_certificate]:-}" != intent ]]; then return 2; fi
  gt_core_mark resource.acme_certificate intent || return 2
  log=$(gt_path /var/lib/gt-install/tls.log)
  gt_no_symlinks "$log" || return 2
  (umask 077; touch "$log") && chmod 600 "$log" || return 2
  # Webroot HTTP-01 keeps certbot from rewriting any owned or foreign vhost.
  gt_tls_certbot certonly --non-interactive --agree-tos --email "${ANSWER[LETSENCRYPT_EMAIL]}" \
    --webroot -w "$path" --cert-name "$cert_name" "${names[@]}" --keep-until-expiring \
    --deploy-hook "systemctl reload ${ANSWER[WEBSERVER]}.service" >> "$log" 2>&1 || {
    gt_core_mark step.tls failed || return 2
    gt_core_error "Certificate request failed; HTTP remains available. See $log and rerun --install-web after DNS/router repair."; return 2;
  }
  local saved_cert=${ANSWER[TLS_CERT]:-} saved_key=${ANSWER[TLS_KEY]:-}
  ANSWER[TLS_CERT]=${FACT[tls.cert]} ANSWER[TLS_KEY]=${FACT[tls.key]}
  PLAN_BLOCKERS=(); gt_plan_certificate certbot
  ANSWER[TLS_CERT]=$saved_cert ANSWER[TLS_KEY]=$saved_key
  (( ${#PLAN_BLOCKERS[@]} == 0 )) || return 2
  gt_core_mark step.tls issued
}

gt_tls_reuse_hook() {
  local target
  [[ "${FACT[tls.reuse]:-no}" == yes ]] || return 0
  target=$(gt_path "/etc/letsencrypt/renewal-hooks/deploy/gt-install-${STATE[run_id]}")
  gt_no_symlinks "${target%/*}" || return 2
  [[ -d "${target%/*}" ]] || install -d -o root -g root -m 755 "${target%/*}" || return 2
  {
    printf '#!/bin/sh\n'
    # shellcheck disable=SC2016
    printf '[ "${RENEWED_LINEAGE:-}" = "/etc/letsencrypt/live/%s" ] || exit 0\n' "${FACT[tls.lineage]}"
    printf 'systemctl reload %s.service\n' "${ANSWER[WEBSERVER]}"
  } > "$SCRATCH/certbot-hook"
  gt_app_root_file certbot_hook "$SCRATCH/certbot-hook" "$target" 755
}

gt_tls_snapshot() {
  printf '%s:%s:%s' "${FACT[tls.selection]:-}" "${FACT[tls.lineage]:-}" "${FACT[tls.renewal_hash]:-}"
}

gt_tls_renew() {
  local log digest
  log=$(gt_path /var/lib/gt-install/tls.log)
  gt_no_symlinks "$log" || return 2
  (umask 077; touch "$log") && chmod 600 "$log" || return 2
  gt_tls_certbot renew --cert-name "${FACT[tls.lineage]}" --dry-run --non-interactive \
    --no-random-sleep-on-renew >> "$log" 2>&1 || return 2
  if [[ "${FACT[tls.reuse]:-no}" == yes ]]; then
    digest=$(sha256sum "$(gt_path "/etc/letsencrypt/renewal/${FACT[tls.lineage]}.conf")") || return 2
    [[ "${digest%% *}" == "${FACT[tls.renewal_hash]}" ]] || {
      gt_core_error 'Certbot renewal configuration changed during verification; inspect it before resuming.'; return 2;
    }
  fi
  gt_core_mark step.tls_renewal complete
}

gt_tls_verify() {
  local name served expected
  for name in ${FACT[web.names]}; do
    gt_web_verify "https://$name" "$name:443:127.0.0.1" || return 2
    served=$(timeout 10 openssl s_client -connect 127.0.0.1:443 -servername "$name" </dev/null 2>/dev/null |
      openssl x509 -noout -fingerprint -sha256) || return 2
    expected=$(openssl x509 -in "${FACT[tls.cert]}" -noout -fingerprint -sha256) || return 2
    [[ "$served" == "$expected" ]] || return 2
  done
}

gt_install_extended_web() {
  local before after reply id port name web=${ANSWER[WEBSERVER]} package missing=no link
  local -a packages=()
  gt_stage_preflight || return 2
  [[ "${STATE[step.app]:-}" == complete ]] && gt_core_config_valid && gt_app_artifacts && gt_app_verify || return 2
  gt_prepare_dns || return $?
  gt_extended_preflight || { gt_core_error 'Domain/Apache preflight failed; no web changes made.'; return 2; }
  PLAN=() PLAN_PACKAGES=()
  gt_packages
  [[ "${FACT[packages]}" == known ]] || { gt_core_error 'Web package inventory failed.'; return 2; }
  gt_plan_web_runtime
  gt_plan_packages
  gt_report_rows "$(gt_text 'Web packages and modules' 'Web-Pakete und Module')" "${PLAN[@]}"
  gt_report_rows "$(gt_text Blockers Blocker)" "${PLAN_BLOCKERS[@]}"
  (( ${#PLAN_BLOCKERS[@]} == 0 )) || return 2
  before="${FACT[web.snapshot]}:${FACT[web.transaction]}:${FACT[web.names]}:${FACT[web.lan]}:$(gt_tls_snapshot):$(sha256sum "$(gt_path /var/lib/gt-install/state)")"
  printf 'Web: %s; LAN: http://%s/grafioschtrader/; domain: %s; TLS: %s\n' "$web" "${FACT[web.lan]}" "${ANSWER[DOMAIN]:-none}" "${ANSWER[TLS_SOURCE]:-none}"
  gt_text 'Install required web packages, own sites and Apache modules; verify routes and shared sites. Certbot uses HTTP-01 and a scoped renewal test. Firewall unchanged.' \
    'Benötigte Web-Pakete, eigene Sites und Apache-Module installieren; Routen und bestehende Sites prüfen. Certbot nutzt HTTP-01 und einen begrenzten Erneuerungstest. Firewall unverändert.'
  if [[ "${ANSWER[TLS_SOURCE]:-}" == letsencrypt && "${FACT[tls.reuse]:-no}" != yes ]]; then
    gt_text "Confirmation also accepts the Let's Encrypt terms: https://letsencrypt.org/repository/" \
      "Die Bestätigung akzeptiert auch die Bedingungen von Let's Encrypt: https://letsencrypt.org/repository/"
  fi
  if [[ "$CORE_CONFIRM" != yes ]]; then
    { exec {QUESTION_FD}<>/dev/tty; } 2>/dev/null || return 2
    printf 'install-web: ' >&"$QUESTION_FD"
    IFS= read -r -u "$QUESTION_FD" reply && [[ "$reply" == install-web ]] || return 130
  fi
  gt_extended_preflight || return 2
  after="${FACT[web.snapshot]}:${FACT[web.transaction]}:${FACT[web.names]}:${FACT[web.lan]}:$(gt_tls_snapshot):$(sha256sum "$(gt_path /var/lib/gt-install/state)")"
  [[ "$before" == "$after" ]] || { gt_core_error 'Web plan changed; run again.'; return 2; }
  gt_core_mark resource.web_lan "${FACT[web.lan]}" && gt_core_mark resource.web_names "${FACT[web.names]}" || return 2
  if [[ "${ANSWER[TLS_SOURCE]:-}" == letsencrypt ]]; then
    gt_core_mark resource.certbot_selection "${FACT[tls.selection]}" || return 2
    if [[ "${FACT[tls.reuse]}" == yes ]]; then
      gt_core_mark resource.certbot_renewal_hash "${FACT[tls.renewal_hash]}" || return 2
    fi
  fi
  read -r -a packages <<< "${FACT[web.packages]}"
  for package in "${packages[@]}"; do
    [[ "$(dpkg-query -W -f='${db:Status-Status}' "$package" 2>/dev/null)" == installed ]] || missing=yes
  done
  if [[ "$missing" == yes ]]; then
    gt_core_run env DEBIAN_FRONTEND=noninteractive apt-get -y --no-remove --no-upgrade \
      -o DPkg::Lock::Timeout=600 install "${packages[@]}" || return 2
  fi
  gt_core_run systemctl start "$web.service" || return 2
  gt_site_test && gt_site_inventory > "$SCRATCH/web-inventory" && gt_nginx_statuses > "$SCRATCH/web-before" && gt_site_baseline || return 2
  if [[ "$web" == apache2 ]]; then
    gt_apache_default_disable || return 2
    if [[ "${STATE[step.site_lan]:-}" != complete ]]; then
      gt_apache_modules lan || return 2
    fi
    if [[ "${ANSWER[TLS_SOURCE]:-}" == proxy ]]; then
      # Additional Listen is installer-owned; ports.conf stays untouched.
      printf 'Listen %s\n' "${ANSWER[TLS_PROXY_LISTEN]}" > "$SCRATCH/apache-listen"
      gt_app_root_file apache_listen "$SCRATCH/apache-listen" "$(gt_path /etc/apache2/conf-enabled/grafioschtrader-listen.conf)" 644 || return 2
    fi
  fi
  gt_site_render_lan > "$SCRATCH/site-lan"
  if [[ "${STATE[step.site_lan]:-}" != complete ]]; then
    if ! gt_site_activate lan "http://${FACT[web.lan]}"; then
      if [[ "$web" == apache2 ]]; then
        gt_apache_default_restore && gt_apache_modules_restore lan && gt_site_test && gt_core_run systemctl reload apache2.service || return 2
      fi
      return 2
    fi
  else
    link=$(gt_site_path lan); [[ -L "${link/sites-available/sites-enabled}" ]] && gt_web_verify || return 2
  fi
  if [[ -n "${ANSWER[DOMAIN]:-}" ]]; then
    if [[ "${ANSWER[TLS_SOURCE]}" == letsencrypt && "${STATE[step.site_domain]:-}" != complete ]]; then
      if [[ "${FACT[tls.reuse]:-no}" != yes && -z "${STATE[file.site_domain]:-}" ]]; then
        gt_domain_render http > "$SCRATCH/site-http"
        gt_site_activate http "http://${ANSWER[DOMAIN]}" "${ANSWER[DOMAIN]}:80:127.0.0.1" || return 2
      fi
      gt_tls_issue || return 2
    fi
    id=tls; port=443
    if [[ "${ANSWER[TLS_SOURCE]}" == proxy ]]; then id=proxy; port=${ANSWER[TLS_PROXY_LISTEN]}; fi
    gt_domain_render "$id" > "$SCRATCH/site-domain"
    name="https://${ANSWER[DOMAIN]}"; [[ "$id" != proxy ]] || name="http://${ANSWER[DOMAIN]}:$port"
    if [[ "${STATE[step.site_domain]:-}" != complete ]]; then
      if [[ "$web" == apache2 && "$id" == tls ]]; then gt_apache_modules tls || return 2; fi
      if ! gt_site_activate domain "$name" "${ANSWER[DOMAIN]}:$port:127.0.0.1"; then
        if [[ "$web" == apache2 && "$id" == tls ]]; then gt_apache_modules_restore tls && gt_site_test && gt_core_run systemctl reload apache2.service || return 2; fi
        return 2
      fi
    else
      link=$(gt_site_path domain)
      [[ -L "${link/sites-available/sites-enabled}" ]] && gt_web_verify "$name" "${ANSWER[DOMAIN]}:$port:127.0.0.1" || return 2
    fi
    if [[ "$id" == tls ]]; then
      gt_tls_verify || return 2
      if [[ "${ANSWER[TLS_SOURCE]}" == letsencrypt ]]; then
        if [[ "${FACT[tls.reuse]:-no}" == yes ]]; then
          gt_tls_reuse_hook || return 2
        else gt_core_run systemctl enable --now certbot.timer || return 2; fi
        if [[ "${STATE[step.tls_renewal]:-}" != complete ]]; then
          gt_tls_renew || return 2
        fi
      fi
      gt_core_mark step.tls complete || return 2
    elif gt_web_verify "https://${ANSWER[DOMAIN]}"; then gt_core_mark step.tls complete || return 2
    else
      gt_core_mark step.tls unverified || return 2
      gt_text 'External proxy HTTPS not verified from this host; verify from outside the LAN.' 'HTTPS am vorgeschalteten Proxy hier nicht verifiziert; von außerhalb des LAN prüfen.'
    fi
  else gt_core_mark step.tls skipped || return 2; fi
  gt_web_verify && gt_site_compare && gt_core_run systemctl enable "$web.service" && gt_core_mark step.web complete || return 2
  gt_text 'Web routes verified. Run --check-mail for the mail milestone; final hand-over remains pending.' 'Web-Routen geprüft. --check-mail führt die Mail-Prüfung aus; abschließende Übergabe bleibt offen.'
  return 10
}

gt_apache_default_disable() {
  local link target
  [[ -e "$SCRATCH/apache-stock-default" ]] || return 0
  link=$(gt_path /etc/apache2/sites-enabled/000-default.conf)
  [[ -L "$link" ]] || return 2
  target=$(readlink "$link") || return 2
  [[ "$target" == ../sites-available/000-default.conf || "$target" == /etc/apache2/sites-available/000-default.conf ]] || return 2
  gt_core_mark resource.apache_default "$target" || return 2
  rm -- "$link" && sync -f "${link%/*}"
}

gt_apache_default_restore() {
  local link target=${STATE[resource.apache_default]:-}
  [[ -n "$target" ]] || return 0
  [[ "$target" == ../sites-available/000-default.conf || "$target" == /etc/apache2/sites-available/000-default.conf ]] || return 2
  link=$(gt_path /etc/apache2/sites-enabled/000-default.conf)
  gt_no_symlinks "${link%/*}" || return 2
  [[ ! -e "$link" && ! -L "$link" ]] || return 2
  ln -s "$target" "$link" && sync -f "${link%/*}"
}
gt_mail_resolve() {
  local directory jar status=0
  local -a jars=()
  while IFS= read -r -d '' jar; do jars+=("$jar"); done < <(
    find "$CORE_HOME" -maxdepth 1 -name 'grafioschtrader-server-*.jar' -print0)
  (( ${#jars[@]} == 1 )) || return 2
  directory=$(mktemp -d /tmp/gt-mail-config.XXXXXX) || return 2
  PRIVATE_DIRS+=("$directory")
  chown grafioschtrader:grafioschtrader "$directory" || return 2
  # Match the service working directory and resolve config from the deployed JAR.
  # No key in argv/environment, no Spring application context and no public endpoint.
  # shellcheck disable=SC2016
  printf '%s' "${SECRET[JASYPT_PASSWORD]}" | runuser -u grafioschtrader -- env -i \
    HOME="$CORE_HOME" PATH=/usr/bin:/bin bash -c 'cd "$1" && shift && exec "$@"' gt-mail \
    "$CORE_HOME" "${STATE[java_home]}/bin/java" -Duser.language=en \
    -Dloader.main=grafiosch.installer.InstallerMailConfiguration -cp "${jars[0]}" \
    org.springframework.boot.loader.launch.PropertiesLauncher "$directory/config" \
    > "$SCRATCH/mail-configuration.log" 2>&1 || status=2
  if (( status == 0 )); then
    [[ -f "$directory/config" && ! -L "$directory/config" ]] &&
      cp "$directory/config" "$SCRATCH/mail-configuration" || status=2
  fi
  rm -rf -- "$directory"
  (( status == 0 )) || gt_core_error \
    'Application mail configuration could not be resolved/decrypted. Use the matching backend build; details suppressed.'
  return "$status"
}

gt_mail_probe() {
  local send=${1:-${ANSWER[SMTP_TEST]}} index key
  local -a configuration=() fields=(SMTP_HOST SMTP_PORT SMTP_USER '' SMTP_AUTH SMTP_SECURITY ADMIN_EMAIL)
  rm -f -- "$SCRATCH/mail-result"
  gt_mail_resolve || return 2
  mapfile -d '' -t configuration < "$SCRATCH/mail-configuration"
  rm -f -- "$SCRATCH/mail-configuration"
  (( ${#configuration[@]} == 7 )) || return 2
  # Refuse an unexpected server/recipient/transport before contacting it. Password
  # intentionally comes only from the deployed application's decrypted property.
  for index in 0 1 2 4 5 6; do
    key=${fields[$index]}
    [[ "${configuration[$index]}" == "${ANSWER[$key]}" ]] || {
      gt_core_error "Application mail setting differs from the confirmed answer: $key"; return 2;
    }
  done
  # Credentials travel only on stdin. Neither exception text nor SMTP debug output
  # is exposed: server replies may repeat authentication material.
  cat > "$SCRATCH/mail-check.py" <<'PY'
import base64, email.message, email.utils, smtplib, ssl, sys
host, port, user, password, auth, security, recipient, send, message_id = sys.stdin.buffer.read().decode().split('\0')[:-1]
accepted = False
try:
    context = ssl.create_default_context()
    client = smtplib.SMTP_SSL(host, int(port), timeout=15, context=context) if security == 'tls' else smtplib.SMTP(host, int(port), timeout=15)
    with client:
        client.ehlo_or_helo_if_needed()
        if security == 'starttls':
            client.starttls(context=context); client.ehlo()
        if auth == 'yes':
            # smtplib.login encodes SASL responses as ASCII. Preserve UTF-8
            # credentials for PLAIN/LOGIN, as the application mail client does.
            mechanisms = client.esmtp_features.get('auth', '').upper().split()
            encode = lambda value: base64.b64encode(value.encode('utf-8')).decode('ascii')
            if 'PLAIN' in mechanisms:
                code, reply = client.docmd('AUTH', 'PLAIN ' + encode('\0'+user+'\0'+password))
                if code == 334: code, reply = client.docmd(encode('\0'+user+'\0'+password))
            elif 'LOGIN' in mechanisms:
                code, reply = client.docmd('AUTH', 'LOGIN')
                if code == 334: code, reply = client.docmd(encode(user))
                if code == 334: code, reply = client.docmd(encode(password))
            else:
                client.login(user, password)
                code, reply = 235, b''
            if code != 235: raise smtplib.SMTPAuthenticationError(code, reply)
        if send == 'yes':
            message = email.message.EmailMessage()
            message['From'] = user; message['To'] = recipient
            message['Subject'] = 'Grafioschtrader installation: SMTP test'
            message['Message-ID'] = message_id
            message['Date'] = email.utils.formatdate(localtime=True)
            message.set_content('The Grafioschtrader installer successfully submitted this test message using the selected SMTP settings.')
            if client.send_message(message): raise smtplib.SMTPException()
            # DATA acceptance is the milestone; a later QUIT/network error must
            # not cause a duplicate on recovery.
            accepted = True
            print('accepted', flush=True)
        else:
            code, _ = client.noop()
            if code != 250: raise smtplib.SMTPException()
            print('connected', flush=True)
except Exception:
    if accepted: sys.exit(0)
    print('SMTP check failed (connection, TLS, authentication or recipient); credentials and server reply suppressed.', file=sys.stderr)
    sys.exit(2)
PY
  printf '%s\0' "${configuration[@]}" "$send" \
    "<gt-install-${STATE[run_id]}@localhost>" | python3 "$SCRATCH/mail-check.py" > "$SCRATCH/mail-result" || return 1
}

gt_check_mail() {
  local state_dir field reply result send
  local completed_status
  completed_status=0
  gt_completed || completed_status=$?
  (( completed_status == 3 )) || return "$completed_status"
  state_dir=$(gt_path /var/lib/gt-install)
  gt_question_model
  gt_state_load && gt_secrets_load || return 2
  gt_stage_preflight || return 2
  gt_no_symlinks "$state_dir/lock" || return 2
  if [[ -z "$LOCK_FD" ]]; then exec {LOCK_FD}<"$state_dir/lock" || return 2; fi
  flock -n "$LOCK_FD" || return 2
  [[ "${STATE[step.app]:-}" == complete ]] && gt_core_config_valid && gt_app_artifacts && gt_app_verify || return 2
  if [[ "${ANSWER[SMTP_CONFIGURE]}" == no ]]; then
    gt_core_mark step.mail skipped || return 2
    gt_text 'Mail skipped; registration cannot be completed. Installation remains incomplete.' 'Mail übersprungen; Registrierung kann nicht abgeschlossen werden. Installation bleibt unvollständig.'
    gt_handover; return $?
  fi
  for field in SMTP_HOST SMTP_PORT SMTP_USER SMTP_AUTH SMTP_SECURITY SMTP_TEST ADMIN_EMAIL; do
    gt_validate_answer "$field" "${ANSWER[$field]:-}" || return 2
  done
  [[ "${ANSWER[SMTP_AUTH]}:${ANSWER[SMTP_SECURITY]}" != yes:none ]] || return 2
  [[ "${ANSWER[SMTP_AUTH]}" != yes ]] || gt_valid_secret "${SECRET[SMTP_PASSWORD]:-}" || return 2
  if [[ "${STATE[resource.mail_delivery]:-}" == accepted &&
      "${STATE[resource.mail_configuration]:-}" == application-v1 ]]; then
    gt_core_mark step.mail complete || return 2
  fi
  if [[ "${STATE[step.mail]:-}" == complete && "${STATE[resource.mail_configuration]:-}" == application-v1 ]]; then
    gt_text 'Mail milestone already verified; no duplicate test message sent.' \
      'Mail-Prüfung bereits erfolgreich; keine erneute Testnachricht gesendet.'
    gt_handover; return $?
  fi
  printf 'SMTP: %s:%s; transport=%s; auth=%s; sender=%s; recipient=%s; send=%s\n' \
    "${ANSWER[SMTP_HOST]}" "${ANSWER[SMTP_PORT]}" "${ANSWER[SMTP_SECURITY]}" "${ANSWER[SMTP_AUTH]}" "${ANSWER[SMTP_USER]}" "${ANSWER[ADMIN_EMAIL]}" "${ANSWER[SMTP_TEST]}"
  if [[ "${STATE[step.mail]:-}" == intent ]]; then
    gt_text 'Previous attempt was interrupted; the same Message-ID may be submitted again.' 'Vorheriger Versuch unterbrochen; dieselbe Message-ID wird möglicherweise erneut gesendet.'
  fi
  if [[ "$CORE_CONFIRM" != yes ]]; then
    { exec {QUESTION_FD}<>/dev/tty; } 2>/dev/null || return 2
    printf 'check-mail: ' >&"$QUESTION_FD"
    IFS= read -r -u "$QUESTION_FD" reply && [[ "$reply" == check-mail ]] || return 130
  fi
  gt_core_mark step.mail intent || return 2
  send=${ANSWER[SMTP_TEST]}
  [[ "${STATE[resource.mail_delivery]:-}" != accepted ]] || send=no
  rm -f -- "$SCRATCH/mail-result"
  gt_mail_probe "$send"; result=$?
  if [[ -f "$SCRATCH/mail-result" ]] && grep -qx accepted "$SCRATCH/mail-result"; then
    gt_core_mark resource.mail_delivery accepted || return 2
    gt_text 'Test message accepted by the SMTP server; actual inbox delivery is not verified.' 'Testnachricht vom SMTP-Server angenommen; tatsächliche Zustellung im Postfach nicht geprüft.'
  elif (( result == 0 )) && [[ -f "$SCRATCH/mail-result" ]] && grep -qx connected "$SCRATCH/mail-result"; then
    [[ "${STATE[resource.mail_delivery]:-}" == accepted ]] || gt_core_mark resource.mail_delivery not-requested || return 2
    gt_text 'SMTP connection, selected TLS and authentication verified; no test message requested.' 'SMTP-Verbindung, gewähltes TLS und Anmeldung geprüft; keine Testnachricht gewünscht.'
  else
    gt_core_error 'Mail check failed; resolve SMTP settings/server access, then repeat --check-mail.'
    if (( result == 2 )); then gt_handover blocked; return $?; fi
    gt_core_mark step.mail failed || return 1
    gt_handover; return $?
  fi
  gt_core_mark resource.mail_configuration application-v1 && gt_core_mark step.mail complete || return 2
  gt_handover
}
# Completion is a recorded installation outcome, not a health check after later updates.
# Reports use only selected public fields; neither secrets nor diagnostic logs are copied.
gt_result_remember_warnings() {
  local warning digest
  for warning in "${NOTES[@]}" "${PLAN_WARNINGS[@]/#/WARN: }"; do
    [[ "$warning" == 'WARN: '* ]] || continue
    digest=$(printf '%s' "$warning" | sha256sum) || return 1
    STATE[resource.warning.${digest%% *}]=$warning
  done
}

gt_result_milestones() {
  local key marker
  RESULT=([backend]=pending [web]=pending [tls]=pending [mail]=pending [mail_delivery]=pending)
  for key in backend web mail; do
    marker=$key; [[ "$key" != backend ]] || marker=app
    case "${STATE[step.$marker]:-}" in
      complete) RESULT[$key]=ok ;;
      failed) RESULT[$key]=failed ;;
      skipped) RESULT[$key]=skipped ;;
    esac
  done
  if [[ -z "${ANSWER[DOMAIN]:-}" ]]; then RESULT[tls]=skipped
  else
    case "${STATE[step.tls]:-}" in
      complete) RESULT[tls]=ok ;;
      failed) RESULT[tls]=failed ;;
      unverified) [[ "${ANSWER[TLS_SOURCE]:-}" != proxy ]] || RESULT[tls]=unverified ;;
    esac
  fi
  case "${STATE[resource.mail_delivery]:-}" in
    accepted|not-requested) RESULT[mail_delivery]=${STATE[resource.mail_delivery]} ;;
    *) [[ "${STATE[step.mail]:-}" != intent ]] || RESULT[mail_delivery]=uncertain ;;
  esac
  if [[ "${ANSWER[SMTP_CONFIGURE]:-}" == no ]]; then
    RESULT[mail]=skipped RESULT[mail_delivery]=skipped
  elif [[ "${RESULT[mail]}" == ok ]]; then
    if [[ "${STATE[resource.mail_configuration]:-}" != application-v1 ||
        ( "${ANSWER[SMTP_TEST]:-}" == yes && "${RESULT[mail_delivery]}" != accepted ) ||
        ( "${ANSWER[SMTP_TEST]:-}" != yes && "${RESULT[mail_delivery]}" != accepted &&
          "${RESULT[mail_delivery]}" != not-requested ) ]]; then RESULT[mail]=pending; fi
  fi
  RESULT[status]=incomplete RESULT[exit_code]=10
  if [[ "${RESULT[backend]}" != ok || "${RESULT[web]}" == failed ]]; then
    RESULT[status]=failed RESULT[exit_code]=1
  elif [[ "${RESULT[web]}:${RESULT[mail]}" == ok:ok &&
      "${RESULT[tls]}" =~ ^(ok|unverified|skipped)$ &&
      "${STATE[built_commit]:-}" =~ ^[a-f0-9]{40}$ ]]; then
    RESULT[status]=complete RESULT[exit_code]=0
  fi
}

gt_completion_valid() {
  local step
  [[ "${STATE[completed_at]:-}" =~ ^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}Z$ &&
      "${STATE[installer_sha256]:-}" =~ ^[a-f0-9]{64}$ &&
      "${STATE[built_commit]:-}" == "${STATE[planned_commit]:-}" &&
      "${STATE[built_commit]:-}" =~ ^[a-f0-9]{40}$ ]] || return 2
  for step in core app app_build app_start web mail; do
    [[ "${STATE[step.$step]:-}" == complete ]] || return 2
  done
  [[ "${ANSWER[SMTP_CONFIGURE]:-}" == yes && "${ANSWER[SMTP_TEST]:-}" =~ ^(yes|no)$ &&
      -n "${ANSWER[ADMIN_EMAIL]:-}" && -n "${STATE[resource.web_lan]:-}" ]] || return 2
  gt_result_milestones
  [[ "${RESULT[status]}" == complete ]]
}

gt_result_details() {
  local key index=0 address=${STATE[resource.web_lan]:-unknown}
  [[ "$address" != *:* ]] || address="[$address]"
  RESULT[url]="http://$address/grafioschtrader/"
  RESULT[lan_url]=${RESULT[url]}
  [[ -z "${ANSWER[DOMAIN]:-}" ]] || RESULT[url]="https://${ANSWER[DOMAIN]}/grafioschtrader/"
  for key in run_id planned_commit built_commit installer_sha256 completed_at; do
    RESULT[$key]=${STATE[$key]:-pending}
  done
  RESULT[admin_email]=${ANSWER[ADMIN_EMAIL]:-pending}
  RESULT[registration]=$(gt_text "Register with ${RESULT[admin_email]}; this account becomes administrator." \
    "Mit ${RESULT[admin_email]} registrieren; dieses Konto wird Administrator.")
  RESULT[update]=$(gt_text 'After hand-over, run ./gtupdate.sh as grafioschtrader in /home/grafioschtrader.' \
    'Nach der Übergabe ./gtupdate.sh als grafioschtrader in /home/grafioschtrader ausführen.')
  RESULT[configuration]=$(gt_text \
    'Updates merge template keys in application.properties and drop additional keys.' \
    'Updates übernehmen Vorlagenschlüssel in application.properties und entfernen zusätzliche Schlüssel.')
  RESULT[production_configuration]=$(gt_text \
    'Put additional keys in application-production.properties; updates preserve this file unchanged.' \
    'Zusätzliche Schlüssel in application-production.properties ablegen; Updates erhalten diese Datei unverändert.')
  RESULT[launchers]=$(gt_text 'Keep the generated launchers and assigned cron slot.' \
    'Erzeugte Startskripte und zugewiesenen Cron-Zeitpunkt beibehalten.')
  RESULT[recovery]=$(gt_text 'Resume pending stages with the original journal and secrets.' \
    'Offene Stufen mit ursprünglichem Journal und Geheimnissen fortsetzen.')
  RESULT[database]=$(gt_text 'Restoring files does not roll back database migrations.' \
    'Wiederhergestellte Dateien setzen Datenbankmigrationen nicht zurück.')
  while IFS= read -r key; do
    [[ "$key" == resource.warning.* ]] || continue
    RESULT[warning.$((++index))]=${STATE[$key]}
  done < <(printf '%s\n' "${!STATE[@]}" | LC_ALL=C sort)
  gt_result_actions
}

gt_result_actions() {
  if [[ "${RESULT[mail]}" == skipped ]]; then
    RESULT[action.mail]=$(gt_text 'Without mail nobody can complete registration, so there is no administrator yet.' \
      'Ohne Mail kann niemand die Registrierung abschließen; daher gibt es noch keinen Administrator.')
  elif [[ "${RESULT[mail]}" != ok ]]; then
    RESULT[action.mail]=$(gt_text 'Resolve SMTP settings or server access, then repeat --check-mail.' \
      'SMTP-Einstellungen oder Serverzugriff klären, danach --check-mail wiederholen.')
  fi
  [[ "${RESULT[web]}" == ok ]] || RESULT[action.web]=$(gt_text \
    'Complete web integration with --install-web, then repeat --check-mail.' \
    'Webanbindung mit --install-web abschließen, danach --check-mail wiederholen.')
  if [[ "${RESULT[tls]}" == unverified ]]; then
    RESULT[action.tls]=$(gt_text "Verify ${RESULT[url]} from outside this network." \
      "${RESULT[url]} von außerhalb dieses Netzes prüfen.")
  elif [[ "${RESULT[tls]}" == failed || "${RESULT[tls]}" == pending ]]; then
    RESULT[action.tls]=$(gt_text \
      'Use LAN access only until HTTPS works; sessions use bearer tokens. Resume --install-web.' \
      'Bis HTTPS funktioniert nur LAN-Zugriff nutzen; Sitzungen verwenden Bearer-Tokens. --install-web fortsetzen.')
  fi
  case "${RESULT[mail_delivery]}" in
    accepted) RESULT[mail_delivery_note]=$(gt_text 'SMTP accepted the test message; inbox delivery is not verified.' \
      'SMTP hat die Testnachricht angenommen; die Zustellung im Postfach ist nicht geprüft.') ;;
    not-requested) RESULT[mail_delivery_note]=$(gt_text 'SMTP verified without sending a test message.' \
      'SMTP ohne Versand einer Testnachricht geprüft.') ;;
    uncertain) RESULT[mail_delivery_note]=$(gt_text 'Interrupted attempt; delivery is uncertain. A retry may resend.' \
      'Unterbrochener Versuch; Zustellung ungewiss. Eine Wiederholung kann erneut senden.') ;;
  esac
}

gt_result_print() {
  local key
  gt_text 'Installation result (recorded milestones)' 'Installationsergebnis (gespeicherte Prüfergebnisse)'
  while IFS= read -r key; do
    printf '%s=%s\n' "$key" "$(gt_safe "${RESULT[$key]}")"
  done < <(printf '%s\n' "${!RESULT[@]}" | LC_ALL=C sort)
}

gt_handover() {
  local outcome=${1:-} digest state_dir
  state_dir=$(gt_path /var/lib/gt-install)
  gt_private_dir "$state_dir" || return 2
  gt_no_symlinks "$state_dir/result" || return 2
  if [[ -e "$state_dir/result" ]]; then gt_private_read "$state_dir/result" || return 2; PRIVATE_CONTENT=''; fi
  digest=$(sha256sum "${BASH_SOURCE[0]}") || return 1
  STATE[installer_sha256]=${digest%% *}
  gt_result_remember_warnings || return 1
  gt_result_milestones
  case "$outcome" in
    blocked) RESULT[status]=blocked RESULT[exit_code]=2 ;;
    failed) RESULT[status]=failed RESULT[exit_code]=1 ;;
    '') ;;
    *) return 2 ;;
  esac
  if [[ "${RESULT[status]}" == complete ]]; then
    STATE[completed_at]=$(date -u +%Y-%m-%dT%H:%M:%SZ) || return 1
    if ! gt_completion_valid; then
      unset 'STATE[completed_at]'
      gt_core_error 'Completion evidence is inconsistent; restore the original journal.'
      return 2
    fi
  fi
  gt_result_details
  # Publish the result first. A crash before the journal commit resumes without another SMTP send.
  gt_atomic_map "$state_dir/result" RESULT || return 1
  [[ "${RESULT[status]}" != complete ]] || STATE[status]=complete
  gt_state_save || return 1
  gt_result_print
  return "${RESULT[exit_code]}"
}

# 3 means normal entry may continue; 0 is completed and 2 is an invalid completed journal.
gt_completed() {
  local file
  file=$(gt_path /var/lib/gt-install/state)
  [[ -e "$file" || -L "$file" ]] || return 3
  [[ "$(gt_literal "$file" status)" == complete ]] || return 3
  gt_question_model
  gt_state_load || { gt_core_error 'Invalid completed installation journal.'; return 2; }
  gt_result_details
  printf 'host.class=completed\n'
  gt_text 'Installation completed; use the updater for subsequent changes.' \
    'Installation abgeschlossen; für weitere Updates den Updater verwenden.'
  gt_result_print
}
gt_install_core() {
  local key resume=no before after reply file state_dir
  local completed_status
  completed_status=0
  gt_completed || completed_status=$?
  (( completed_status == 3 )) || return "$completed_status"
  state_dir=$(gt_path /var/lib/gt-install)
  gt_question_model
  if [[ -e "$state_dir/state" || -L "$state_dir/state" ]]; then
    if ! gt_state_load || ! gt_secrets_load; then
      gt_core_error 'Invalid journal or missing/invalid original secrets; recover them before resuming.'; return 2
    fi
    resume=yes
    [[ -z "${STATE[step.app]:-}" ]] || { gt_core_error 'Application stage has begun; resume with --install-app.'; return 2; }
  fi
  gt_inventory; gt_compatibility; gt_report
  if [[ "$resume" == no && "${FACT[host.class]}" != fresh ]]; then gt_core_error 'Host is not fresh.'; return 2; fi
  if [[ -n "$ANSWERS_FILE" ]]; then gt_answers_file "$ANSWERS_FILE" || return 2; fi
  if [[ -z "$ANSWERS_FILE" || "$CORE_CONFIRM" != yes ]]; then
    { exec {QUESTION_FD}<>/dev/tty; } 2>/dev/null || { gt_core_error 'Terminal required, or use --answers FILE --yes.'; return 2; }
    QUESTION_OUTPUT=$QUESTION_FD
  fi
  if [[ "$resume" == no ]]; then
    gt_prepare_root || return $?
    if [[ -n "$ANSWERS_FILE" ]]; then gt_file_questions || return 2; else gt_questions || return $?; fi
    gt_prepare_secrets || return $?
  else
    # Configuration and application secrets are immutable in this core stage. Never rotate them.
    for key in "${!FILE_ANSWERS[@]}"; do
      [[ "$key" != DB_ROOT_PASSWORD ]] || continue
      if [[ "${Q_TYPE[$key]}" == secret ]]; then [[ "${FILE_ANSWERS[$key]}" == "${SECRET[$key]:-}" ]] || return 2
      else [[ "${FILE_ANSWERS[$key]}" == "${ANSWER[$key]:-}" ]] || return 2; fi
    done
    if [[ "${STATE[new_database_server]}" == yes || "${FACT[database.query]}" != ok ]]; then
      gt_collect_secret DB_ROOT_PASSWORD || return $?
    fi
    if [[ "${FACT[database.vendor]}" != absent ]]; then
      file=$(gt_db_options DB_ROOT_PASSWORD root) || return 2
      gt_database "$file"; rm -f -- "$file"
      gt_compatibility
    fi
  fi
  if ! gt_core_plan; then gt_plan_report; return 2; fi
  gt_prepare_dns || return $?
  gt_core_plan; local plan_status=$?
  gt_plan_report
  (( plan_status == 0 )) || return 2
  if [[ "$CORE_CONFIRM" != yes ]]; then
    printf '%s: ' "$(gt_text 'Type install-core to execute exactly this scope' 'install-core eingeben, um genau diese Stufe auszuführen')" >&"$QUESTION_OUTPUT"
    IFS= read -r -u "$QUESTION_FD" reply && [[ "$reply" == install-core ]] || return 130
  fi
  before=$(gt_core_snapshot | LC_ALL=C sort | sha256sum)
  gt_inventory
  if [[ "${FACT[database.vendor]}" != absent && -n "${SECRET[DB_ROOT_PASSWORD]:-}" ]]; then
    file=$(gt_db_options DB_ROOT_PASSWORD root) || return 2; gt_database "$file"; rm -f -- "$file"
  fi
  gt_compatibility
  gt_verify_dns || return 2
  if ! gt_core_plan; then gt_plan_report; return 2; fi
  after=$(gt_core_snapshot | LC_ALL=C sort | sha256sum)
  [[ "$before" == "$after" ]] || { gt_core_error 'Inventory changed after planning; run again to review a fresh plan.'; return 2; }
  gt_private_dir "$state_dir" || return 2
  gt_no_symlinks "$state_dir/lock" || return 2
  if [[ -z "$LOCK_FD" ]]; then exec {LOCK_FD}>"$state_dir/lock" || return 2; fi
  flock -n "$LOCK_FD" || { gt_message lock >&2; return 2; }
  if [[ "$resume" == no ]]; then gt_core_begin || return 2; fi
  gt_build_record || return 2
  gt_core_execute
}

gt_cleanup() {
  set +vx
  gt_restore_terminal
  if [[ "${STATE[step.toolchains]:-}" == running ]]; then gt_alternatives_restore || :; fi
  SECRET=() SECRET_STATUS=() FILE_ANSWERS=() SECRET_INPUT=''
  PRIVATE_CONTENT=''
  local dir
  for dir in "${PRIVATE_FILES[@]}"; do rm -f -- "$dir"; done
  for dir in "${PRIVATE_DIRS[@]}"; do rm -rf -- "$dir"; done
  [[ -z "$SCRATCH" ]] || rm -rf -- "$SCRATCH"
}
main() {
  set +vx
  gt_reset
  local arg
  while (( $# )); do
    arg=$1; shift
    case "$arg" in
      --check|--dry-run|--prepare|--install-core|--install-app|--install-web|--check-mail) [[ -z "$MODE" || "$MODE" == "$arg" ]] || { gt_message mode >&2; return 2; }; MODE=$arg ;;
      --answers) [[ $# -gt 0 && -z "$ANSWERS_FILE" && -n "$1" && "$1" != --* ]] || { gt_message mode >&2; return 2; }; ANSWERS_FILE=$1; shift ;;
      --plain) ;;
      --yes) CORE_CONFIRM=yes ;;
      --help|-h) printf 'Usage: sudo bash gt-install.sh {--check|--dry-run|--prepare [--answers FILE]|--install-core [--answers FILE] [--yes]|--install-app [--yes]|--install-web [--yes]|--check-mail [--yes]} [--plain]\n'; return 0 ;;
      *) gt_message mode >&2; return 2 ;;
    esac
  done
  [[ -n "$MODE" && ( -z "$ANSWERS_FILE" || "$MODE" == --prepare || "$MODE" == --install-core ) &&
    ( "$CORE_CONFIRM" == no || "$MODE" == --install-core || "$MODE" == --install-app || "$MODE" == --install-web || "$MODE" == --check-mail ) ]] || { gt_message mode >&2; return 2; }
  [[ -n "${BASH_SOURCE[0]:-}" && -f "${BASH_SOURCE[0]}" ]] || { gt_message pipe >&2; return 2; }
  (( EUID == 0 )) || { gt_message root >&2; return 2; }
  command -v timeout >/dev/null || { gt_message unavailable timeout >&2; return 1; }
  # Read an existing lock without creating the state directory or lock file.
  if [[ -e /var/lib/gt-install/lock ]]; then
    if ! exec {LOCK_FD}</var/lib/gt-install/lock || ! flock -n "$LOCK_FD"; then gt_message lock >&2; return 2; fi
  fi
  umask 077
  SCRATCH=$(mktemp -d) || return 1
  trap gt_cleanup EXIT
  trap 'exit 130' INT
  trap 'exit 143' TERM
  export GIT_TERMINAL_PROMPT=0
  case "$MODE" in --dry-run) gt_dry_run ;; --prepare) gt_prepare ;; --install-core) gt_install_core ;; --install-app) gt_install_app ;; --install-web) gt_install_web ;; --check-mail) gt_check_mail ;; *) gt_check ;; esac
}

[[ "${GT_INSTALL_SOURCE_ONLY:-}" == 1 ]] || main "$@"
